async fn health() -> Json<serde_json::Value> {
    Json(json!({ "ok": true }))
}

async fn list_environment_profiles(
    State(state): State<AppState>,
) -> Result<Json<EnvironmentProfilesResponse>, ApiError> {
    Ok(Json(EnvironmentProfilesResponse {
        profiles: environment_profile_responses(&state).await?,
        provider_transport_attempts: pharness_fireworks::DEFAULT_MAX_TRANSPORT_ATTEMPTS,
    }))
}

async fn environment_profile_responses(
    state: &AppState,
) -> Result<Vec<crate::dto::EnvironmentProfileResponse>, ApiError> {
    let now = current_millis();
    let mut responses = Vec::new();
    for profile in state.environment_profiles.iter() {
        let mut response = environment::profile_response(profile);
        if response.status == "configured_unverified" {
            let capability = format!("environment_profile:{}", profile.id);
            if let Some(verification) = state
                .store
                .latest_capability_verification(&capability)
                .await?
            {
                response.status =
                    if verification.expires_at.parse::<u128>().unwrap_or_default() <= now {
                        response
                            .blockers
                            .push("isolated runner verification expired".to_string());
                        "stale".to_string()
                    } else {
                        if verification.status != "available" {
                            response.blockers.push(verification.summary);
                        }
                        verification.status
                    };
            }
        }
        responses.push(response);
    }
    Ok(responses)
}

fn environment_profile_readiness_blocker(profile: &EnvironmentProfileResponse) -> Option<String> {
    if profile.status == "available" {
        return None;
    }
    let detail = if profile.blockers.is_empty() {
        match profile.status.as_str() {
            "configured_unverified" => {
                "runner profile requires a fresh passing isolated verification"
            }
            "stale" => "isolated runner verification expired",
            _ => "runner profile is unavailable",
        }
        .to_string()
    } else {
        profile.blockers.join("; ")
    };
    Some(format!("environment_profile {}: {detail}", profile.id))
}

fn capability_verification_summary(outcome: &CapabilityVerificationOutcome) -> String {
    let permission = outcome.permission.as_deref().unwrap_or("required access");
    let repository = outcome
        .repository
        .as_deref()
        .map(|repo| format!(" for {repo}"))
        .unwrap_or_default();
    if outcome.available {
        format!("Isolated identity verified {permission}{repository}")
    } else {
        format!("Isolated identity did not verify {permission}{repository}")
    }
}

/// Gate `/api/internal/*` behind the configured worker token.
///
/// Worker ingest is disabled entirely when no token is configured, so a
/// loopback-only local deployment exposes no unauthenticated write surface
/// for remote workers.
async fn require_worker_token(
    State(state): State<AppState>,
    request: Request,
    next: Next,
) -> Response {
    let Some(expected) = state.worker_token.as_deref() else {
        return ApiError::conflict("worker ingest is disabled: no worker token is configured")
            .into_response();
    };

    let provided = request
        .headers()
        .get(axum::http::header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "));

    match provided {
        Some(token) if token_matches(token, expected) => next.run(request).await,
        _ => ApiError::unauthorized("invalid or missing worker token").into_response(),
    }
}

fn token_matches(provided: &str, expected: &str) -> bool {
    let provided = Sha256::digest(provided.as_bytes());
    let expected = Sha256::digest(expected.as_bytes());
    provided == expected
}

/// Authenticated operator identity resolved from the bearer token.
#[derive(Debug, Clone)]
pub struct OperatorIdentity(pub String);

/// Gate operator routes behind `PHARNESS_OPERATOR_TOKENS` when configured.
///
/// `/health` stays open for probes. With no operator tokens configured the
/// API keeps its loopback-trusting local behavior.
async fn require_operator_token(
    State(state): State<AppState>,
    mut request: Request,
    next: Next,
) -> Response {
    if state.operator_tokens.is_empty() || request.uri().path() == "/health" {
        return next.run(request).await;
    }

    let provided = request
        .headers()
        .get(axum::http::header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "));

    let matched = provided.and_then(|token| {
        state
            .operator_tokens
            .iter()
            .find(|(_, expected)| token_matches(token, expected))
            .map(|(name, _)| name.clone())
    });

    match matched {
        Some(name) => {
            request.extensions_mut().insert(OperatorIdentity(name));
            next.run(request).await
        }
        None => ApiError::unauthorized("invalid or missing operator token").into_response(),
    }
}

async fn config_effective(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
) -> Json<serde_json::Value> {
    let worker = state.worker.config_json();
    let operator = json!({
        "auth_required": !state.operator_tokens.is_empty(),
        "name": identity.map(|Extension(OperatorIdentity(name))| name),
    });

    Json(json!({
        "api": {
            "name": "pharness-api",
        },
        "cluster": {
            "kubectl_bin": state.cluster_tools.kubectl_bin(),
            "argocd_namespace": state.cluster_tools.argocd_namespace(),
            "prometheus_configured": state.cluster_tools.prometheus_configured(),
            "loki_configured": state.cluster_tools.loki_configured(),
            "registry_alias_count": state.cluster_tools.registry_alias_count(),
        },
        "policy": policy_json(&state.policy),
        "worker": worker,
        "workspace": {
            "local_coding_enabled": state.worker.supports_local_workspace() && state.workspace.configured(),
            "allowed_repo_count": state.workspace.allowed_repo_count(),
        },
        "operator": operator,
    }))
}

async fn capability_statuses(state: &AppState) -> Result<Vec<CapabilityStatusResponse>, ApiError> {
    let worker = state.worker.config_json();
    let configured = |pointer: &str| {
        worker
            .pointer(pointer)
            .and_then(Value::as_bool)
            .unwrap_or(false)
    };
    let status = |capability: &str, is_configured: bool, configured_summary: &str| {
        CapabilityStatusResponse {
            capability: capability.to_string(),
            status: if is_configured {
                "configured_unverified"
            } else {
                "unavailable"
            }
            .to_string(),
            summary: if is_configured {
                configured_summary.to_string()
            } else {
                format!("{capability} is not configured for the isolated execution identity")
            },
            verified_at: None,
            expires_at: None,
        }
    };
    let mut statuses = vec![
        status(
            "model_provider",
            worker.get("enabled").and_then(Value::as_bool).unwrap_or(false),
            "Model provider is configured but has not passed a fresh isolated credential check.",
        ),
        status(
            "source_workspace",
            state.workspace.remote_configured() || state.workspace.configured(),
            "At least one workspace repository is allowlisted.",
        ),
        status(
            "source_writer",
            configured("/git_writer/available"),
            "Source writer identity and allowlist are configured but repository reachability is unverified.",
        ),
        status(
            "source_observer",
            configured("/git_observer/available"),
            "Source observer identity and allowlist are configured but repository reachability is unverified.",
        ),
        status(
            "gitops_writer",
            configured("/gitops_writer/available"),
            "GitOps writer identity and allowlist are configured but repository reachability is unverified.",
        ),
        status(
            "gitops_observer",
            configured("/gitops_observer/available"),
            "GitOps observer identity and allowlist are configured but repository reachability is unverified.",
        ),
        status(
            "tekton",
            state.worker.supports_remote_workspace(),
            "Tekton executor is configured but cluster authorization is unverified.",
        ),
        status(
            "argo",
            configured("/argo_executor/available"),
            "Argo runner identity and exact Application allowlist are configured but authorization is unverified.",
        ),
        status(
            "observability",
            state.cluster_tools.prometheus_configured(),
            "Prometheus endpoint is configured but target inventory has not been freshly verified.",
        ),
    ];
    let now = current_millis();
    for status in &mut statuses {
        if status.status != "configured_unverified" {
            continue;
        }
        let Some(verification) = state
            .store
            .latest_capability_verification(&status.capability)
            .await?
        else {
            continue;
        };
        let expires = verification.expires_at.parse::<u128>().unwrap_or_default();
        status.verified_at = Some(verification.verified_at.clone());
        status.expires_at = Some(verification.expires_at.clone());
        if expires <= now {
            status.status = "stale".to_string();
            status.summary = format!(
                "{} verification expired; run the isolated preflight again",
                status.capability
            );
        } else {
            status.status = verification.status;
            status.summary = verification.summary;
        }
    }
    Ok(statuses)
}

async fn system_readiness(
    State(state): State<AppState>,
) -> Result<Json<SystemReadinessResponse>, ApiError> {
    let worker = state.worker.config_json();
    let capabilities = capability_statuses(&state).await?;
    let mut blockers = capabilities
        .iter()
        .filter(|capability| capability.status != "available")
        .map(|capability| format!("{}: {}", capability.capability, capability.summary))
        .collect::<Vec<_>>();
    if !state.protected_target.exact_locked_match {
        blockers.push(
            "protected_target: deployed configuration does not exactly match the locked yfinance-wrapper production target"
                .to_string(),
        );
    }
    let environment_profiles = environment_profile_responses(&state).await?;
    if environment_profiles.is_empty() {
        blockers
            .push("environment_profiles: no immutable runner profile is configured".to_string());
    }
    blockers.extend(
        environment_profiles
            .iter()
            .filter_map(environment_profile_readiness_blocker),
    );
    Ok(Json(SystemReadinessResponse {
        api_revision: state.build.api_revision.clone(),
        ui_revision: state.build.ui_revision.clone(),
        runtime_image_digest: state.build.runtime_image_digest.clone(),
        ui_image_digest: state.build.ui_image_digest.clone(),
        platform_versions_match: state.build.api_revision != "unknown"
            && state.build.api_revision == state.build.ui_revision
            && immutable_image_digest(&state.build.runtime_image_digest)
            && immutable_image_digest(&state.build.ui_image_digest),
        capabilities,
        repository_allowlists: json!({
            "workspace": state.workspace.allowed_remote_repos(),
            "source_writer": worker.pointer("/git_writer/allowed_repos").cloned().unwrap_or_else(|| json!([])),
            "source_observer": worker.pointer("/git_observer/allowed_repos").cloned().unwrap_or_else(|| json!([])),
            "gitops_writer": worker.pointer("/gitops_writer/allowed_repos").cloned().unwrap_or_else(|| json!([])),
            "gitops_observer": worker.pointer("/gitops_observer/allowed_repos").cloned().unwrap_or_else(|| json!([])),
        }),
        targets: protected_target_json(),
        environment_profiles,
        blockers,
    }))
}

async fn preflight_system_capability(
    State(state): State<AppState>,
    Path(capability): Path<String>,
) -> Result<Json<CapabilityStatusResponse>, ApiError> {
    let profile = capability
        .strip_prefix("environment_profile:")
        .and_then(|id| {
            state
                .environment_profiles
                .iter()
                .find(|profile| profile.id == id)
        });
    let configured = if let Some(profile) = profile {
        let response = environment::profile_response(profile);
        CapabilityStatusResponse {
            capability: capability.clone(),
            status: response.status,
            summary: if response.blockers.is_empty() {
                "Runner profile is configured but has not passed isolated verification.".to_string()
            } else {
                response.blockers.join("; ")
            },
            verified_at: None,
            expires_at: None,
        }
    } else {
        capability_statuses(&state)
            .await?
            .into_iter()
            .find(|entry| entry.capability == capability)
            .ok_or_else(|| ApiError::not_found("capability", &capability))?
    };
    if configured.status == "unavailable" {
        return Ok(Json(configured));
    }
    let repository = (capability == "source_workspace")
        .then(|| state.workspace.allowed_remote_repos().first().cloned())
        .flatten();
    let outcome = match profile {
        Some(profile) => state.worker.verify_environment_profile(profile).await,
        None => {
            state
                .worker
                .verify_capability(&capability, repository.as_deref())
                .await
        }
    };
    let now = current_millis();
    let (status, summary, principal, verified_repository, permission) = match outcome {
        Ok(outcome) => (
            if outcome.available {
                "available"
            } else {
                "unavailable"
            },
            capability_verification_summary(&outcome),
            outcome.principal,
            outcome.repository,
            outcome.permission,
        ),
        Err(_) => (
            "unavailable",
            "Isolated capability verification could not complete".to_string(),
            None,
            repository,
            None,
        ),
    };
    let verification = state
        .store
        .create_capability_verification(CreateCapabilityVerification {
            id: format!(
                "capverify_{}_{}",
                safe_id_fragment(&capability),
                unique_suffix()
            ),
            capability: capability.clone(),
            status: status.to_string(),
            summary: summary.clone(),
            principal,
            repository: verified_repository,
            permission,
            verified_at: now.to_string(),
            expires_at: (now + 15 * 60 * 1_000).to_string(),
        })
        .await?;
    Ok(Json(CapabilityStatusResponse {
        capability,
        status: verification.status,
        summary: verification.summary,
        verified_at: Some(verification.verified_at),
        expires_at: Some(verification.expires_at),
    }))
}

fn protected_target_json() -> Value {
    json!({
        "environment": PROTECTED_ENVIRONMENT,
        "namespace": PROTECTED_NAMESPACE,
        "argo_application": PROTECTED_ARGO_APPLICATION,
        "workload_kind": PROTECTED_WORKLOAD_KIND,
        "workload_name": PROTECTED_WORKLOAD_NAME,
        "source_repo": PROTECTED_SOURCE_REPO,
        "gitops_repo": PROTECTED_GITOPS_REPO,
        "kustomization_path": PROTECTED_KUSTOMIZATION_PATH,
        "image_name": PROTECTED_IMAGE_NAME,
        "rollback_owner": PROTECTED_ROLLBACK_OWNER,
    })
}

fn immutable_image_digest(value: &str) -> bool {
    value.strip_prefix("sha256:").is_some_and(|digest| {
        digest.len() == 64
            && digest
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    })
}

fn immutable_git_object_id(value: &str) -> bool {
    matches!(value.len(), 40 | 64)
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

async fn execute_capability(
    State(state): State<AppState>,
    Json(request): Json<ExecuteCapabilityRequest>,
) -> Result<Json<ExecuteCapabilityResponse>, ApiError> {
    execute_direct_capability(&state, request.action, request.timeout_ms)
        .await
        .map(Json)
}

async fn execute_direct_capability(
    state: &AppState,
    action: AgentAction,
    requested_timeout_ms: Option<u64>,
) -> Result<ExecuteCapabilityResponse, ApiError> {
    let timeout_ms = direct_capability_timeout_ms(requested_timeout_ms);
    if !is_direct_capability_action(&action) {
        return Err(ApiError::bad_request(format!(
            "{} is not exposed through direct capability execution",
            action.kind_name()
        )));
    }

    let decision = state.policy.evaluate_action(&action);
    let response = match &decision {
        PolicyDecision::Allow { .. } => {
            let action_name = action.kind_name().to_string();
            match timeout(
                Duration::from_millis(timeout_ms),
                state.cluster_tools.execute(&action),
            )
            .await
            {
                Ok(Ok(result)) => {
                    let evidence =
                        persist_direct_capability_evidence(&state.store, &action_name, &result)
                            .await?;
                    append_direct_capability_audit_event(
                        &state.store,
                        DirectCapabilityAuditInput {
                            kind: "direct_capability.executed",
                            action: &action,
                            decision: &decision,
                            executed: true,
                            cancelled: false,
                            timeout_ms,
                            result: Some(&result),
                            error: None,
                        },
                    )
                    .await?;
                    ExecuteCapabilityResponse {
                        status: "ok".to_string(),
                        action: action_name,
                        decision: decision.clone(),
                        executed: true,
                        cancelled: false,
                        timeout_ms,
                        artifact_id: evidence.artifact_id,
                        observation_id: evidence.observation_id,
                        result: Some(result),
                        error: None,
                    }
                }
                Ok(Err(error)) => {
                    let error = error.to_string();
                    append_direct_capability_audit_event(
                        &state.store,
                        DirectCapabilityAuditInput {
                            kind: "direct_capability.failed",
                            action: &action,
                            decision: &decision,
                            executed: true,
                            cancelled: false,
                            timeout_ms,
                            result: None,
                            error: Some(&error),
                        },
                    )
                    .await?;
                    ExecuteCapabilityResponse {
                        status: "tool_error".to_string(),
                        action: action_name,
                        decision: decision.clone(),
                        executed: true,
                        cancelled: false,
                        timeout_ms,
                        artifact_id: None,
                        observation_id: None,
                        result: None,
                        error: Some(error),
                    }
                }
                Err(_) => {
                    let error = format!("capability execution cancelled after {timeout_ms} ms");
                    append_direct_capability_audit_event(
                        &state.store,
                        DirectCapabilityAuditInput {
                            kind: "direct_capability.cancelled",
                            action: &action,
                            decision: &decision,
                            executed: true,
                            cancelled: true,
                            timeout_ms,
                            result: None,
                            error: Some(&error),
                        },
                    )
                    .await?;
                    ExecuteCapabilityResponse {
                        status: "cancelled".to_string(),
                        action: action_name,
                        decision: decision.clone(),
                        executed: true,
                        cancelled: true,
                        timeout_ms,
                        artifact_id: None,
                        observation_id: None,
                        result: None,
                        error: Some(error),
                    }
                }
            }
        }
        PolicyDecision::Ask { .. } => ExecuteCapabilityResponse {
            status: "approval_required".to_string(),
            action: action.kind_name().to_string(),
            decision: decision.clone(),
            executed: false,
            cancelled: false,
            timeout_ms,
            artifact_id: None,
            observation_id: None,
            result: None,
            error: None,
        },
        PolicyDecision::Deny { summary, .. } => ExecuteCapabilityResponse {
            status: "denied".to_string(),
            action: action.kind_name().to_string(),
            decision: decision.clone(),
            executed: false,
            cancelled: false,
            timeout_ms,
            artifact_id: None,
            observation_id: None,
            result: None,
            error: Some(summary.clone()),
        },
    };
    if matches!(decision, PolicyDecision::Deny { .. }) {
        append_direct_capability_audit_event(
            &state.store,
            DirectCapabilityAuditInput {
                kind: "direct_capability.denied",
                action: &action,
                decision: &decision,
                executed: false,
                cancelled: false,
                timeout_ms,
                result: None,
                error: None,
            },
        )
        .await?;
    }

    Ok(response)
}

#[derive(Debug, Default)]
struct DirectCapabilityEvidence {
    artifact_id: Option<String>,
    observation_id: Option<String>,
}

async fn persist_direct_capability_evidence(
    store: &SqliteStore,
    action_name: &str,
    result: &ToolResult,
) -> Result<DirectCapabilityEvidence, ApiError> {
    let Some(source) = direct_evidence_source(result) else {
        return Ok(DirectCapabilityEvidence::default());
    };

    let (session_id, run_id) =
        root_session_for_request(store, None, None, "direct capability evidence").await?;
    let artifact_kind = direct_artifact_kind(&result.content, source);
    let artifact_id = format!("art_direct_{}_{}", action_name, unique_suffix());
    let artifact = store
        .create_artifact(CreateArtifact {
            id: artifact_id.clone(),
            session_id: session_id.clone(),
            run_id: run_id.clone(),
            kind: artifact_kind,
            label: result.summary.clone(),
            mime_type: Some("application/json".to_string()),
            path: None,
            content_text: None,
            content_json: Some(result.content.clone()),
        })
        .await?;

    let kind = direct_observation_kind(&result.content, source);
    let subject = direct_observation_subject(&result.content, source, &kind);
    let observation = store
        .create_observation(CreateObservation {
            id: format!("obs_direct_{}_{}", action_name, unique_suffix()),
            session_id,
            run_id,
            source: source.to_string(),
            kind: kind.clone(),
            subject: subject.clone(),
            summary: result.summary.clone(),
            resource_namespace: direct_observation_namespace(&result.content),
            resource_kind: direct_observation_resource_kind(&result.content, source, &kind),
            resource_name: direct_observation_resource_name(
                &result.content,
                source,
                &kind,
                &subject,
            ),
            resource_ref_json: Some(direct_observation_resource_ref(
                action_name,
                source,
                &kind,
                &subject,
            )),
            artifact_id: Some(artifact.id.clone()),
            data_json: direct_observation_data(&result.content),
        })
        .await?;
    append_observation_audit_event(
        store,
        &observation,
        "observation.created",
        Some("api".to_string()),
        Some(format!("direct capability {action_name}")),
    )
    .await?;

    Ok(DirectCapabilityEvidence {
        artifact_id: Some(artifact.id),
        observation_id: Some(observation.id),
    })
}

fn direct_evidence_source(result: &ToolResult) -> Option<&str> {
    let source = result.content.get("source")?.as_str()?;
    matches!(
        source,
        "kubernetes" | "argocd" | "prometheus" | "loki" | "tekton"
    )
    .then_some(source)
}

fn direct_artifact_kind(content: &Value, source: &str) -> String {
    if source == "tekton"
        && content.get("resource").and_then(Value::as_str) == Some("pipeline_run_analysis")
    {
        "pipeline_run_analysis".to_string()
    } else {
        format!("{source}_tool_result")
    }
}

fn direct_observation_kind(content: &Value, source: &str) -> String {
    content
        .get("resource")
        .and_then(Value::as_str)
        .or_else(|| content.get("action").and_then(Value::as_str))
        .map(str::to_string)
        .unwrap_or_else(|| format!("{source}_read"))
}

fn direct_observation_subject(content: &Value, source: &str, kind: &str) -> String {
    if source == "tekton" && kind == "pipeline_run_analysis" {
        if let (Some(namespace), Some(name)) = (
            content
                .pointer("/analysis/pipeline_run/namespace")
                .and_then(Value::as_str),
            content
                .pointer("/analysis/pipeline_run/name")
                .and_then(Value::as_str),
        ) {
            return format!("{namespace}/{name}");
        }
    }
    if let Some(query) = content.get("query").and_then(Value::as_str) {
        return query.to_string();
    }
    if let Some(name) = content.get("name").and_then(Value::as_str) {
        return name.to_string();
    }
    if let Some(namespace) = content.get("namespace").and_then(Value::as_str) {
        return format!("{namespace}/{kind}");
    }
    format!("{source}/{kind}")
}

fn direct_observation_namespace(content: &Value) -> Option<String> {
    first_direct_string(&[
        content.pointer("/namespace"),
        content.pointer("/output/metadata/namespace"),
        content.pointer("/analysis/pipeline_run/namespace"),
    ])
}

fn direct_observation_resource_kind(content: &Value, source: &str, kind: &str) -> Option<String> {
    let output_kind = content.pointer("/output/kind").and_then(Value::as_str);
    if output_kind.is_some_and(|value| value != "List") {
        return output_kind.map(str::to_string);
    }
    if source == "tekton" && kind == "pipeline_run_analysis" {
        return Some("PipelineRun".to_string());
    }

    first_direct_string(&[
        content.pointer("/analysis/pipeline_run/kind"),
        content.pointer("/resource"),
    ])
    .or_else(|| match (source, kind) {
        ("argocd", _) => Some("Application".to_string()),
        ("prometheus", "inventory") => Some("inventory".to_string()),
        ("prometheus", _) => Some("query".to_string()),
        ("loki", "log_summary") => Some("log_summary".to_string()),
        (_, value) if !value.trim().is_empty() => Some(value.to_string()),
        _ => None,
    })
}

fn direct_observation_resource_name(
    content: &Value,
    source: &str,
    kind: &str,
    subject: &str,
) -> Option<String> {
    first_direct_string(&[
        content.pointer("/name"),
        content.pointer("/output/metadata/name"),
        content.pointer("/analysis/pipeline_run/name"),
    ])
    .or_else(|| match (source, kind) {
        ("prometheus", "inventory") => Some("inventory".to_string()),
        ("loki", "log_summary") => Some("log_summary".to_string()),
        _ if !subject.trim().is_empty() && !subject.contains('/') => Some(subject.to_string()),
        _ => None,
    })
}

fn first_direct_string(values: &[Option<&Value>]) -> Option<String> {
    values
        .iter()
        .filter_map(|value| value.and_then(Value::as_str))
        .map(str::trim)
        .find(|value| !value.is_empty())
        .map(str::to_string)
}

fn direct_observation_resource_ref(
    action_name: &str,
    source: &str,
    kind: &str,
    subject: &str,
) -> Value {
    json!({
        "source": source,
        "kind": kind,
        "name": subject,
        "metadata": {
            "capability": action_name,
            "direct": true,
        },
    })
}

fn direct_observation_data(content: &Value) -> Value {
    let mut data = Map::new();
    for key in [
        "source",
        "resource",
        "namespace",
        "name",
        "query",
        "output",
        "response",
        "inventory",
        "analysis",
    ] {
        if let Some(value) = content.get(key) {
            data.insert(key.to_string(), value.clone());
        }
    }
    Value::Object(data)
}

fn direct_capability_timeout_ms(requested: Option<u64>) -> u64 {
    requested
        .unwrap_or(DEFAULT_DIRECT_CAPABILITY_TIMEOUT_MS)
        .clamp(1, MAX_DIRECT_CAPABILITY_TIMEOUT_MS)
}

fn is_direct_capability_action(action: &AgentAction) -> bool {
    matches!(
        action,
        AgentAction::KubernetesGet { .. }
            | AgentAction::ArgoGetApp { .. }
            | AgentAction::PrometheusQuery { .. }
            | AgentAction::PrometheusInventory { .. }
            | AgentAction::LokiLogSummary { .. }
            | AgentAction::TektonGetPipelineRuns { .. }
            | AgentAction::TektonGetTaskRuns { .. }
            | AgentAction::TektonAnalyzePipelineRun { .. }
            | AgentAction::RegistryInspectImage { .. }
    )
}

fn run_policy(default: &SafetyPolicy, override_mode: Option<PolicyMode>) -> SafetyPolicy {
    let mut policy = default.clone();
    if let Some(mode) = override_mode {
        policy.mode = mode;
    }
    policy
}

fn policy_json(policy: &SafetyPolicy) -> serde_json::Value {
    json!({
        "subject": &policy.subject,
        "environment": &policy.environment,
        "mode": policy.mode,
        "allow_read_only_shell": policy.allow_read_only_shell,
        "require_approval_for_writes": policy.require_approval_for_writes,
        "require_approval_for_network": policy.require_approval_for_network,
        "require_approval_for_destructive": policy.require_approval_for_destructive,
        "deny_privileged": policy.deny_privileged,
        "deny_secret_access": policy.deny_secret_access,
        "permission_grant_count": policy.permission_grants.len(),
    })
}

async fn active_permission_grants(store: &SqliteStore) -> Result<Vec<PermissionGrant>, ApiError> {
    let now = current_millis();
    let grants = store
        .list_permission_grants(Some("active"), 200)
        .await?
        .into_iter()
        .filter(|grant| grant_is_unexpired(grant, now))
        .map(permission_grant_snapshot)
        .collect::<Result<Vec<_>, _>>()?;

    Ok(grants)
}

fn permission_grant_snapshot(grant: StoredPermissionGrant) -> Result<PermissionGrant, ApiError> {
    let scope =
        serde_json::from_value::<PermissionGrantScope>(grant.scope_json).map_err(|error| {
            ApiError::internal(format!(
                "permission grant {} has invalid scope: {error}",
                grant.id
            ))
        })?;
    let policy =
        serde_json::from_value::<PermissionGrantPolicy>(grant.policy_json).map_err(|error| {
            ApiError::internal(format!(
                "permission grant {} has invalid policy: {error}",
                grant.id
            ))
        })?;

    Ok(PermissionGrant {
        id: grant.id,
        subject: grant.subject,
        scope,
        policy,
        expires_at: grant.expires_at,
    })
}

fn grant_is_unexpired(grant: &StoredPermissionGrant, now_millis: u128) -> bool {
    grant
        .expires_at
        .as_deref()
        .map(|expires_at| {
            expires_at
                .parse::<u128>()
                .map(|expires_at| expires_at > now_millis)
                .unwrap_or(false)
        })
        .unwrap_or(true)
}

fn group_operator_records(
    records: impl IntoIterator<Item = (String, String, String, String, String)>,
) -> Vec<OperatorResourceGroupResponse> {
    let mut groups =
        BTreeMap::<(String, String, String), Vec<OperatorResourceGroupMemberResponse>>::new();
    for (id, label, title, resource, status) in records {
        groups
            .entry((title, resource, status))
            .or_default()
            .push(OperatorResourceGroupMemberResponse { id, label });
    }
    let mut response = groups
        .into_iter()
        .map(
            |((title, resource, status), members)| OperatorResourceGroupResponse {
                key: format!("{title}\u{1f}{resource}\u{1f}{status}"),
                title,
                resource,
                status,
                count: members.len(),
                members,
            },
        )
        .collect::<Vec<OperatorResourceGroupResponse>>();
    response.sort_by(|left, right| {
        right
            .count
            .cmp(&left.count)
            .then_with(|| left.title.cmp(&right.title))
            .then_with(|| left.resource.cmp(&right.resource))
            .then_with(|| left.status.cmp(&right.status))
    });
    response
}

const OPERATOR_GROUP_PAGE_SIZE: u32 = 200;

// List responses stay paginated. Groups intentionally enumerate the full matching set so a
// repeated-record count never changes merely because the operator moved to another page.
async fn all_runs_for_operator_groups(
    store: &SqliteStore,
    mut filter: RunListFilter,
) -> Result<Vec<RunResponse>, StoreError> {
    let mut runs = Vec::new();
    filter.limit = OPERATOR_GROUP_PAGE_SIZE;
    filter.offset = 0;
    loop {
        let page = store.list_runs(filter.clone()).await?;
        let page_len = page.len();
        runs.extend(page.into_iter().map(Into::into));
        if page_len < OPERATOR_GROUP_PAGE_SIZE as usize {
            return Ok(runs);
        }
        filter.offset = filter
            .offset
            .checked_add(OPERATOR_GROUP_PAGE_SIZE)
            .ok_or_else(|| {
                StoreError::InvalidData(
                    "operator run group pagination exceeded supported range".to_string(),
                )
            })?;
    }
}

