async fn get_remediation_plan(
    State(state): State<AppState>,
    Path(plan_id): Path<String>,
) -> Result<Json<RemediationPlanResponse>, ApiError> {
    let plan = state
        .store
        .get_remediation_plan(&plan_id)
        .await?
        .ok_or_else(|| ApiError::not_found("remediation_plan", &plan_id))?;

    Ok(Json(plan.into()))
}

async fn create_remediation_plan(
    State(state): State<AppState>,
    Json(request): Json<CreateRemediationPlanRequest>,
) -> Result<Json<RemediationPlanResponse>, ApiError> {
    let incident_id = required_text(request.incident_id, "incident_id")?;
    let incident = state
        .store
        .get_incident(&incident_id)
        .await?
        .ok_or_else(|| ApiError::not_found("incident", &incident_id))?;
    let status = clean_optional_text(request.status).unwrap_or_else(|| "draft".to_string());
    validate_allowed_value(
        "status",
        &status,
        &[
            "draft",
            "proposed",
            "approved",
            "executing",
            "blocked",
            "completed",
            "rejected",
            "stale",
        ],
    )?;
    let risk_level = required_text(request.risk_level, "risk_level")?;
    validate_allowed_value(
        "risk_level",
        &risk_level,
        &["low", "medium", "high", "critical"],
    )?;
    let plan_json = request.plan_json.unwrap_or_else(|| json!({}));
    ensure_json_object(&plan_json, "plan_json")?;

    let plan = state
        .store
        .create_remediation_plan(CreateRemediationPlan {
            id: clean_optional_text(request.id)
                .unwrap_or_else(|| format!("rplan_{}", unique_suffix())),
            incident_id: incident.id.clone(),
            session_id: incident.session_id.clone(),
            run_id: incident.run_id.clone(),
            status,
            title: required_text(request.title, "title")?,
            summary: required_text(request.summary, "summary")?,
            risk_level,
            requires_approval: request.requires_approval.unwrap_or(true),
            resource_namespace: clean_optional_text(request.resource_namespace)
                .or(incident.resource_namespace),
            resource_kind: clean_optional_text(request.resource_kind).or(incident.resource_kind),
            resource_name: clean_optional_text(request.resource_name).or(incident.resource_name),
            plan_json,
        })
        .await?;
    append_remediation_plan_audit_event(
        &state.store,
        &plan,
        "remediation_plan.created",
        clean_optional_text(request.actor),
        clean_optional_text(request.reason),
    )
    .await?;
    for gate in approval_gates_from_remediation_plan(&plan) {
        let gate = state.store.create_approval_gate(gate).await?;
        append_approval_gate_audit_event(&state.store, &gate, "approval_gate.created", "created")
            .await?;
    }

    Ok(Json(plan.into()))
}

async fn transition_remediation_plan(
    State(state): State<AppState>,
    Path(plan_id): Path<String>,
    Json(request): Json<TransitionRemediationPlanRequest>,
) -> Result<Json<TransitionRemediationPlanResponse>, ApiError> {
    let current = state
        .store
        .get_remediation_plan(&plan_id)
        .await?
        .ok_or_else(|| ApiError::not_found("remediation_plan", &plan_id))?;
    let target = RemediationPlanStatus::parse(&request.target_status)?;
    let current_status = RemediationPlanStatus::parse(&current.status)?;
    current_status.ensure_can_transition_to(target)?;
    let actor = clean_optional_text(request.actor);
    let reason = clean_optional_text(request.reason);
    if target == RemediationPlanStatus::Approved
        && current.requires_approval
        && (actor.is_none() || reason.is_none())
    {
        return Err(ApiError::bad_request(
            "approving a remediation plan requires actor and reason",
        ));
    }
    let remediation_plan = state
        .store
        .update_remediation_plan_status(&plan_id, target.as_str())
        .await?;
    append_remediation_plan_audit_event(
        &state.store,
        &remediation_plan,
        &format!("remediation_plan.{}", target.as_str()),
        actor,
        reason,
    )
    .await?;

    Ok(Json(TransitionRemediationPlanResponse {
        remediation_plan: remediation_plan.into(),
    }))
}

#[derive(Debug, Default, serde::Deserialize)]
struct ListWorkItemsQuery {
    status: Option<String>,
    source_repo: Option<String>,
    target_environment: Option<String>,
    target_namespace: Option<String>,
    production_impacting: Option<bool>,
    actor: Option<String>,
    origin: Option<String>,
    include: Option<String>,
    limit: Option<u32>,
    offset: Option<u32>,
}

async fn list_work_items(
    State(state): State<AppState>,
    Query(query): Query<ListWorkItemsQuery>,
) -> Result<Json<WorkItemsResponse>, ApiError> {
    let limit = query.limit.unwrap_or(50).clamp(1, 200);
    let offset = query.offset.unwrap_or(0);
    let filter = WorkItemListFilter {
        status: clean_optional_text(query.status),
        source_repo: clean_optional_text(query.source_repo),
        target_environment: clean_optional_text(query.target_environment),
        target_namespace: clean_optional_text(query.target_namespace),
        production_impacting: query.production_impacting,
        created_by: clean_optional_text(query.actor),
        origin: clean_optional_text(query.origin),
        limit,
        offset,
    };
    let count = state.store.count_work_items(filter.clone()).await?;
    let stored_work_items = state.store.list_work_items(filter).await?;
    let include_operator_state = clean_optional_text(query.include).is_some_and(|include| {
        include
            .split(',')
            .any(|value| value.trim() == "operator_state")
    });
    let mut operator_state = BTreeMap::new();
    if include_operator_state {
        for item in &stored_work_items {
            let active_wait = state
                .store
                .get_active_controller_wait_for_work_item(&item.id)
                .await?;
            operator_state.insert(
                item.id.clone(),
                WorkItemOperatorStateResponse {
                    current_boundary: active_wait
                        .as_ref()
                        .map(|wait| format!("waiting for {}", wait.wait_kind))
                        .unwrap_or_else(|| item.status.clone()),
                    attempts_remaining: item.max_attempts.saturating_sub(item.attempt_count),
                    attention_reason: item.status_reason.clone(),
                    active_wait: active_wait.map(Into::into),
                },
            );
        }
    }
    let work_items = stored_work_items
        .into_iter()
        .map(Into::into)
        .collect::<Vec<_>>();
    Ok(Json(WorkItemsResponse {
        work_items,
        count,
        limit,
        offset,
        operator_state: include_operator_state.then_some(operator_state),
    }))
}

async fn scope_options(
    State(state): State<AppState>,
) -> Result<Json<ScopeOptionsResponse>, ApiError> {
    let work_items = state
        .store
        .list_work_items(WorkItemListFilter {
            limit: 200,
            ..WorkItemListFilter::default()
        })
        .await?;
    let workspaces = state
        .store
        .list_workspaces(WorkspaceListFilter {
            limit: 200,
            ..WorkspaceListFilter::default()
        })
        .await?;
    let gates = state
        .store
        .list_approval_gates(ApprovalGateListFilter {
            limit: 200,
            ..ApprovalGateListFilter::default()
        })
        .await?;
    let audit_events = state.store.list_audit_events(None, None, None, 200).await?;
    let runs = state
        .store
        .list_runs(RunListFilter {
            limit: 200,
            ..RunListFilter::default()
        })
        .await?;
    let approvals = state
        .store
        .list_approvals(ApprovalListFilter {
            limit: 200,
            ..ApprovalListFilter::default()
        })
        .await?;

    let mut environments = BTreeSet::new();
    let mut namespaces = BTreeSet::new();
    let mut repositories = BTreeSet::new();
    let mut branches = BTreeSet::new();
    let mut actors = BTreeSet::new();
    for item in &work_items {
        environments.insert(item.target_environment.clone());
        repositories.insert(item.source_repo.clone());
        branches.insert(item.source_ref.clone());
        if let Some(value) = &item.gitops_repo {
            repositories.insert(value.clone());
        }
        if let Some(value) = &item.gitops_ref {
            branches.insert(value.clone());
        }
        if let Some(value) = &item.target_namespace {
            namespaces.insert(value.clone());
        }
        if let Some(value) = &item.created_by {
            actors.insert(value.clone());
        }
    }
    for workspace in &workspaces {
        repositories.insert(workspace.source_repo.clone());
        branches.insert(workspace.source_ref.clone());
        if let Some(value) = &workspace.branch {
            branches.insert(value.clone());
        }
    }
    for run in &runs {
        if let Some(value) = &run.created_by {
            actors.insert(value.clone());
        }
    }
    for gate in &gates {
        if let Some(value) = &gate.resource_namespace {
            namespaces.insert(value.clone());
        }
        if let Some(value) = &gate.decided_by {
            actors.insert(value.clone());
        }
    }
    for event in &audit_events {
        if let Some(value) = &event.actor {
            actors.insert(value.clone());
        }
    }

    Ok(Json(ScopeOptionsResponse {
        environments: environments.into_iter().collect(),
        namespaces: namespaces.into_iter().collect(),
        repositories: repositories.into_iter().collect(),
        branches: branches.into_iter().collect(),
        actors: actors.into_iter().collect(),
        origins: work_items
            .iter()
            .map(|item| item.origin.clone())
            .chain(runs.iter().map(|run| run.origin.clone()))
            .chain(approvals.iter().map(|approval| approval.origin.clone()))
            .chain(gates.iter().map(|gate| gate.origin.clone()))
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect(),
    }))
}

async fn triage_summary(
    State(state): State<AppState>,
) -> Result<Json<TriageSummaryResponse>, ApiError> {
    Ok(Json(load_triage(&state, None).await?.summary))
}

#[derive(Debug, Default, serde::Deserialize)]
struct ListTriageQuery {
    origin: Option<String>,
}

async fn list_triage(
    State(state): State<AppState>,
    Query(query): Query<ListTriageQuery>,
) -> Result<Json<TriageResponse>, ApiError> {
    Ok(Json(
        load_triage(&state, clean_optional_text(query.origin)).await?,
    ))
}

async fn load_triage(state: &AppState, origin: Option<String>) -> Result<TriageResponse, ApiError> {
    let limit = 200;
    let include_legacy = matches!(origin.as_deref(), None | Some("legacy"));
    let pending_gate_filter = ApprovalGateListFilter {
        status: Some("pending".to_string()),
        origin: origin.clone(),
        limit,
        ..ApprovalGateListFilter::default()
    };
    let pending_gates =
        all_approval_gates_for_operator_groups(state.store.as_ref(), pending_gate_filter).await?;
    let pending_approval_filter = ApprovalListFilter {
        status: Some("pending".to_string()),
        origin: origin.clone(),
        limit,
        ..ApprovalListFilter::default()
    };
    let pending_approvals =
        all_approvals_for_operator_groups(state.store.as_ref(), pending_approval_filter).await?;
    let blocked_work_item_filter = WorkItemListFilter {
        status: Some("blocked".to_string()),
        origin: origin.clone(),
        limit,
        ..WorkItemListFilter::default()
    };
    let blocked_work_item_count = state
        .store
        .count_work_items(blocked_work_item_filter.clone())
        .await?;
    let blocked_work_items = state
        .store
        .list_work_items(blocked_work_item_filter)
        .await?;
    let now = i64::try_from(current_millis()).unwrap_or(i64::MAX);
    let expired_wait_count = if include_legacy {
        state.store.count_expired_controller_waits(now).await?
    } else {
        0
    };
    let expired_waits = state
        .store
        .list_expired_controller_waits(now, limit)
        .await?
        .into_iter()
        .filter(|_| include_legacy)
        .collect::<Vec<_>>();
    let proposed_remediation_filter = RemediationPlanListFilter {
        status: Some("proposed".to_string()),
        limit,
        ..RemediationPlanListFilter::default()
    };
    let proposed_remediation_count = if include_legacy {
        state
            .store
            .count_remediation_plans(proposed_remediation_filter.clone())
            .await?
    } else {
        0
    };
    let proposed_remediation = state
        .store
        .list_remediation_plans(proposed_remediation_filter)
        .await?;
    let proposed_remediation = if include_legacy {
        proposed_remediation
    } else {
        Vec::new()
    };

    let summary = TriageSummaryResponse {
        pending_approval_gates: pending_gates.len(),
        pending_tool_approvals: pending_approvals.len(),
        blocked_work_items: blocked_work_item_count,
        expired_controller_waits: expired_wait_count,
        proposed_remediation_plans: proposed_remediation_count,
        total: pending_gates.len()
            + pending_approvals.len()
            + blocked_work_item_count
            + expired_wait_count
            + proposed_remediation_count,
    };
    let mut items = Vec::with_capacity(summary.total);
    items.extend(pending_gates.into_iter().map(|gate| TriageItemResponse {
        kind: "approval_gate".to_string(),
        id: gate.id.clone(),
        title: gate.title,
        summary: gate.summary,
        status: gate.status,
        risk_level: gate.risk_level,
        origin: gate.origin,
        created_at: gate.created_at,
        resource_kind: "approval_gate".to_string(),
        resource_id: gate.id,
        work_item_id: gate.work_item_id,
    }));
    items.extend(
        pending_approvals
            .into_iter()
            .map(|approval| TriageItemResponse {
                kind: "tool_approval".to_string(),
                id: approval.id.clone(),
                title: approval.kind,
                summary: approval.summary,
                status: approval.status,
                risk_level: approval.risk_level,
                origin: approval.origin,
                created_at: approval.requested_at,
                resource_kind: "approval".to_string(),
                resource_id: approval.id,
                work_item_id: None,
            }),
    );
    items.extend(blocked_work_items.into_iter().map(|item| {
        TriageItemResponse {
            kind: "blocked_work_item".to_string(),
            id: item.id.clone(),
            title: item.title,
            summary: item.status_reason.unwrap_or(item.intent),
            status: item.status,
            risk_level: if item.production_impacting {
                "high"
            } else {
                "medium"
            }
            .to_string(),
            origin: item.origin,
            created_at: item.status_changed_at,
            resource_kind: "work_item".to_string(),
            resource_id: item.id.clone(),
            work_item_id: Some(item.id),
        }
    }));
    items.extend(expired_waits.into_iter().map(|wait| TriageItemResponse {
        kind: "expired_controller_wait".to_string(),
        id: wait.id.clone(),
        title: format!("Expired {} wait", wait.wait_kind),
        summary: format!(
            "{} did not resolve before its next observation deadline",
            wait.subject_id
        ),
        status: wait.status,
        risk_level: "high".to_string(),
        origin: "legacy".to_string(),
        created_at: wait.deadline_at,
        resource_kind: "controller_wait".to_string(),
        resource_id: wait.id,
        work_item_id: Some(wait.work_item_id),
    }));
    items.extend(
        proposed_remediation
            .into_iter()
            .map(|plan| TriageItemResponse {
                kind: "remediation_plan".to_string(),
                id: plan.id.clone(),
                title: plan.title,
                summary: plan.summary,
                status: plan.status,
                risk_level: plan.risk_level,
                origin: "legacy".to_string(),
                created_at: plan.created_at,
                resource_kind: "remediation_plan".to_string(),
                resource_id: plan.id,
                work_item_id: None,
            }),
    );
    items.sort_by(|left, right| {
        triage_kind_rank(&left.kind)
            .cmp(&triage_kind_rank(&right.kind))
            .then_with(|| {
                triage_risk_rank(&right.risk_level).cmp(&triage_risk_rank(&left.risk_level))
            })
            .then_with(|| left.created_at.cmp(&right.created_at))
    });

    Ok(TriageResponse { items, summary })
}

fn triage_kind_rank(kind: &str) -> u8 {
    match kind {
        "approval_gate" => 0,
        "tool_approval" => 1,
        "blocked_work_item" => 2,
        "expired_controller_wait" => 3,
        "remediation_plan" => 4,
        _ => u8::MAX,
    }
}

fn triage_risk_rank(risk: &str) -> u8 {
    match risk {
        "critical" => 4,
        "high" => 3,
        "medium" => 2,
        _ => 1,
    }
}

async fn get_work_item(
    State(state): State<AppState>,
    Path(work_item_id): Path<String>,
) -> Result<Json<WorkItemResponse>, ApiError> {
    let work_item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    Ok(Json(work_item.into()))
}

async fn work_item_flow(
    State(state): State<AppState>,
    Path(work_item_id): Path<String>,
) -> Result<Json<WorkItemFlowResponse>, ApiError> {
    let work_item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&work_item_id)
        .await?;
    let change_set = match work_plan.as_ref() {
        Some(plan) => state.store.get_change_set_by_work_plan(&plan.id).await?,
        None => None,
    };
    let sdlc_flow = match work_plan.clone() {
        Some(plan) => Some(
            build_sdlc_flow(
                &state.store,
                "work_item",
                &work_item_id,
                plan,
                change_set.clone(),
            )
            .await?,
        ),
        None => None,
    };
    let Json(reconcile_preview) = reconcile_work_item(
        State(state.clone()),
        None,
        Path(work_item_id.clone()),
        Json(ReconcileWorkItemRequest {
            apply: false,
            actor: None,
            reason: None,
            max_turns: None,
        }),
    )
    .await?;
    let workspaces: Vec<WorkspaceResponse> = state
        .store
        .list_workspaces(WorkspaceListFilter {
            work_item_id: Some(work_item_id.clone()),
            limit: 100,
            ..WorkspaceListFilter::default()
        })
        .await?
        .into_iter()
        .map(Into::into)
        .collect();
    let controller_waits = state
        .store
        .list_controller_waits(ControllerWaitListFilter {
            work_item_id: Some(work_item_id.clone()),
            limit: 100,
            ..ControllerWaitListFilter::default()
        })
        .await?
        .into_iter()
        .map(Into::into)
        .collect();
    let delivery_segments = work_item_delivery_segments(&sdlc_flow, workspaces.last());
    let audit_events = state
        .store
        .list_audit_events(Some("work_item"), Some(&work_item_id), None, 100)
        .await?
        .into_iter()
        .map(Into::into)
        .collect();
    let mut action_rail = Vec::new();
    if let Some(plan) = work_plan.as_ref() {
        if plan.status == "proposed" {
            action_rail.push(resource_review_action(
                "planning",
                "work_plan",
                &plan.id,
                &plan.status,
                plan.updated_at.as_deref(),
                plan.revision,
                true,
            ));
            action_rail.push(resource_review_action(
                "planning",
                "work_plan",
                &plan.id,
                &plan.status,
                plan.updated_at.as_deref(),
                plan.revision,
                false,
            ));
        } else if plan.status == "approved" && work_item.status == "awaiting_approval" {
            action_rail.push(WorkItemActionResponse {
                id: "authorize_workspace_and_start".to_string(),
                lifecycle_stage: "attempt".to_string(),
                resource: plan.id.clone(),
                status: "ready".to_string(),
                effect_class: "model_execution".to_string(),
                blockers: Vec::new(),
                approval_required: true,
                approval_requirements: vec!["attempt_workspace_write".to_string()],
                external_effect_summary: format!(
                    "Authorize one coding attempt for repository {} using only the declared writable paths, then start model execution.",
                    work_item.source_repo
                ),
                state_hash: lifecycle_action_hash(json!({
                    "action": "authorize_workspace_and_start",
                    "work_item": work_item.id,
                    "work_item_updated_at": work_item.updated_at,
                    "work_plan": plan.id,
                    "work_plan_revision": plan.revision,
                    "attempt_count": work_item.attempt_count,
                })),
            });
        }
    }
    if let Some(flow) = sdlc_flow.as_ref() {
        if let Some(change_set) = flow
            .change_set
            .as_ref()
            .filter(|item| item.status == "proposed")
        {
            action_rail.extend(resource_review_actions(
                "change_set",
                "source",
                &change_set.id,
                &change_set.status,
                change_set.updated_at.as_deref(),
                change_set.revision,
            ));
        }
        if let Some(intent) = flow
            .pipeline_intent
            .as_ref()
            .filter(|item| item.status == "proposed")
        {
            action_rail.extend(resource_review_actions(
                "pipeline_intent",
                "pipeline",
                &intent.id,
                &intent.status,
                intent.updated_at.as_deref(),
                0,
            ));
        }
        if let Some(intent) = flow
            .deployment_intent
            .as_ref()
            .filter(|item| item.status == "proposed")
        {
            action_rail.extend(resource_review_actions(
                "deployment_intent",
                "deployment",
                &intent.id,
                &intent.status,
                intent.updated_at.as_deref(),
                0,
            ));
        }
        if let Some(release) = flow
            .release
            .as_ref()
            .filter(|item| item.status == "proposed")
        {
            action_rail.extend(resource_review_actions(
                "release",
                "release",
                &release.id,
                &release.status,
                release.updated_at.as_deref(),
                0,
            ));
        }
    }
    let lifecycle_gates = state
        .store
        .list_approval_gates(ApprovalGateListFilter {
            work_item_id: Some(work_item_id.clone()),
            limit: 200,
            ..ApprovalGateListFilter::default()
        })
        .await?;
    for gate in lifecycle_gates
        .iter()
        .filter(|gate| gate.status == "pending")
    {
        let (eligible, boundary_summary) = approval_gate_lifecycle_readiness(&state, gate).await?;
        action_rail.push(WorkItemActionResponse {
            id: format!("satisfy_approval_gate:{}", gate.id),
            lifecycle_stage: approval_gate_lifecycle_stage(&gate.gate_kind).to_string(),
            resource: gate.id.clone(),
            status: if eligible { "ready" } else { "blocked" }.to_string(),
            effect_class: "approval_boundary".to_string(),
            blockers: (!eligible)
                .then(|| ReconcileBlockerResponse {
                    code: "future_lifecycle_gate".to_string(),
                    summary: boundary_summary.clone(),
                })
                .into_iter()
                .collect(),
            approval_required: true,
            approval_requirements: vec![gate.gate_kind.clone()],
            external_effect_summary: if eligible {
                gate.summary.clone()
            } else {
                format!("Future gate: {} {boundary_summary}", gate.summary)
            },
            state_hash: lifecycle_action_hash(json!({
                "action": "satisfy_approval_gate",
                "gate_id": gate.id,
                "gate_status": gate.status,
                "gate_kind": gate.gate_kind,
                "eligible": eligible,
                "boundary": boundary_summary,
                "work_item_updated_at": work_item.updated_at,
            })),
        });
    }
    if let Some(run_id) = workspaces
        .last()
        .and_then(|workspace| workspace.run_id.as_ref())
    {
        if let Some(extension) = state.store.pending_budget_extension_for_run(run_id).await? {
            action_rail.push(WorkItemActionResponse {
                id: "approve_budget_extension".to_string(),
                lifecycle_stage: "attempt".to_string(),
                resource: extension.id,
                status: "ready".to_string(),
                effect_class: "approval_boundary".to_string(),
                blockers: Vec::new(),
                approval_required: true,
                approval_requirements: vec!["budget_extension".to_string()],
                external_effect_summary: format!(
                    "Resume the existing workspace with exactly {} additional turns and {} additional tokens.",
                    extension.turn_increment, extension.token_increment
                ),
                state_hash: extension.state_hash,
            });
        }
    }
    if matches!(work_item.status.as_str(), "blocked" | "failed") {
        let mut blockers = Vec::new();
        if work_item.attempt_count >= work_item.max_attempts {
            blockers.push(ReconcileBlockerResponse {
                code: "attempt_budget_exhausted".to_string(),
                summary: "The WorkItem has no remaining attempt budget.".to_string(),
            });
        }
        if change_set.is_some() {
            blockers.push(ReconcileBlockerResponse {
                code: "source_delivery_started".to_string(),
                summary:
                    "Replanning is disabled after a ChangeSet exists; review or roll back instead."
                        .to_string(),
            });
        }
        action_rail.push(WorkItemActionResponse {
            id: "replan_work_item".to_string(),
            lifecycle_stage: "planning".to_string(),
            resource: work_item.id.clone(),
            status: if blockers.is_empty() { "ready" } else { "blocked" }.to_string(),
            effect_class: "internal".to_string(),
            blockers,
            approval_required: false,
            approval_requirements: Vec::new(),
            external_effect_summary: "Create a fresh isolated workspace for another explicit coding attempt; no attempt starts automatically.".to_string(),
            state_hash: lifecycle_action_hash(json!({
                "action": "replan_work_item",
                "work_item": work_item.id,
                "status": work_item.status,
                "updated_at": work_item.updated_at,
                "attempt_count": work_item.attempt_count,
                "max_attempts": work_item.max_attempts,
                "change_set": change_set.as_ref().map(|value| &value.id),
            })),
        });
    }
    action_rail.push(work_item_action_response(&reconcile_preview));
    let rollback_intent = latest_rollback_intent(&state, &work_item, None).await?;
    let rollback_writer_base_ready = sdlc_flow
        .as_ref()
        .and_then(|flow| flow.gitops_delivery.as_ref())
        .and_then(|delivery| delivery.latest_merge.as_ref())
        .is_some();
    if let Some(rollback) = rollback_intent.as_ref() {
        let rollback_id = rollback
            .pointer("/content/rollback_intent_id")
            .and_then(Value::as_str)
            .unwrap_or("rollback_unavailable");
        let status = rollback
            .pointer("/content/status")
            .and_then(Value::as_str)
            .unwrap_or("unavailable");
        let (action_id, action_status, effect_class, summary, approval_requirements) = match status {
            "prepared" if rollback_writer_base_ready => ("approve_rollback", "ready", "approval_boundary", format!("Approve the digest-bound RollbackIntent {rollback_id}; no rollback runs automatically."), vec!["production_rollback".to_string()]),
            "prepared" => ("approve_rollback", "blocked", "external_wait", format!("RollbackIntent {rollback_id} is prepared, but its writer cannot be authorized until the deployment GitOps pull request has an observed immutable merge."), vec!["production_rollback".to_string()]),
            "approved" => ("execute_rollback_gitops_pr", "ready", "external_effect", format!("Create the digest-only rollback pull request in {PROTECTED_GITOPS_REPO}; merge remains manual."), Vec::new()),
            "awaiting_manual_merge" => ("observe_rollback_merge", "ready", "external_effect", format!("Observe the rollback pull request in {PROTECTED_GITOPS_REPO}; merge remains manual."), Vec::new()),
            "ready_for_argo_sync" => ("approve_rollback_argo_sync", "ready", "approval_boundary", format!("Open a fresh production rollback window before syncing exact Argo Application {PROTECTED_ARGO_APPLICATION}."), vec!["production_rollback_deployment".to_string(), "cluster_mutation".to_string(), "production_impact".to_string()]),
            "argo_approved" => ("execute_rollback_argo_sync", "ready", "external_effect", format!("Sync exact Argo Application {PROTECTED_ARGO_APPLICATION} to the observed rollback merge; no other target may be supplied."), Vec::new()),
            "argo_syncing" => ("observe_rollback_argo_sync", "ready", "external_effect", format!("Observe the isolated Argo executor and verify {PROTECTED_WORKLOAD_NAME} against the captured baseline digest."), Vec::new()),
            "verified" => ("rollback_verified", "completed", "internal", format!("RollbackIntent {rollback_id} was explicitly synced and verified."), Vec::new()),
            _ => ("inspect_rollback", "blocked", "internal", format!("Inspect RollbackIntent {rollback_id} with owner {PROTECTED_ROLLBACK_OWNER}."), Vec::new()),
        };
        let state_hash = format!("{:x}", Sha256::digest(rollback.to_string().as_bytes()));
        action_rail.push(WorkItemActionResponse {
            id: action_id.to_string(),
            lifecycle_stage: "rollback".to_string(),
            resource: rollback_id.to_string(),
            status: action_status.to_string(),
            effect_class: effect_class.to_string(),
            blockers: Vec::new(),
            approval_required: !approval_requirements.is_empty(),
            approval_requirements,
            external_effect_summary: summary,
            state_hash,
        });
    }

    let desired_digest = sdlc_flow
        .as_ref()
        .and_then(|flow| flow.pipeline_intent.as_ref())
        .and_then(|intent| intent.intent_json.pointer("/build_output/image_digest"))
        .and_then(Value::as_str);
    let current_digest = rollback_intent
        .as_ref()
        .and_then(|rollback| rollback.pointer("/content/baseline/image_digest"))
        .and_then(Value::as_str);
    let desired_gitops_revision = sdlc_flow
        .as_ref()
        .and_then(|flow| flow.gitops_delivery.as_ref())
        .and_then(|delivery| delivery.latest_merge.as_ref())
        .and_then(|artifact| artifact.content_json.as_ref())
        .and_then(|content| content.get("merge_commit_sha"))
        .and_then(Value::as_str);
    let release_evidence = sdlc_flow
        .as_ref()
        .and_then(|flow| flow.release.as_ref())
        .map(|release| &release.release_json);
    let delivery_configuration = json!({
        "pipeline_contract_id": work_item.pipeline_contract_id,
        "deployment_contract_id": work_item.deployment_contract_id,
        "gitops": {
            "repository": work_item.gitops_repo,
            "ref": work_item.gitops_ref,
            "kustomization_path": work_item.gitops_kustomization_path,
            "image_name": work_item.gitops_image_name,
            "desired_revision": desired_gitops_revision,
        },
        "target": {
            "environment": work_item.target_environment,
            "namespace": work_item.target_namespace,
            "argo_application": work_item.argo_application,
            "workload_kind": work_item.workload_kind,
            "workload_name": work_item.workload_name,
        },
        "current_digest": current_digest,
        "desired_digest": desired_digest,
        "argo": {
            "sync_status": release_evidence.and_then(|evidence| evidence.pointer("/post_sync_verification/argo/sync_status")).and_then(Value::as_str),
            "health_status": release_evidence.and_then(|evidence| evidence.pointer("/post_sync_verification/argo/health_status")).and_then(Value::as_str),
        },
        "production_window_expires_at": rollback_intent.as_ref().and_then(|rollback| rollback.pointer("/content/argo_authorization_expires_at").or_else(|| rollback.pointer("/content/authorization_expires_at"))).and_then(Value::as_str),
        "baseline_digest": current_digest,
        "rollback_owner": work_item.rollback_owner,
        "rollback_intent_id": rollback_intent.as_ref().and_then(|rollback| rollback.pointer("/content/rollback_intent_id")).and_then(Value::as_str),
        "rollback_status": rollback_intent.as_ref().and_then(|rollback| rollback.pointer("/content/status")).and_then(Value::as_str),
    });

    Ok(Json(WorkItemFlowResponse {
        work_item: work_item.into(),
        reconcile_preview,
        sdlc_flow,
        delivery_segments,
        workspaces,
        controller_waits,
        audit_events,
        action_rail,
        delivery_configuration,
    }))
}

fn lifecycle_action_hash(payload: Value) -> String {
    format!("{:x}", Sha256::digest(payload.to_string().as_bytes()))
}

fn resource_review_actions(
    resource_kind: &str,
    lifecycle_stage: &str,
    resource_id: &str,
    status: &str,
    updated_at: Option<&str>,
    revision: i64,
) -> Vec<WorkItemActionResponse> {
    vec![
        resource_review_action(
            lifecycle_stage,
            resource_kind,
            resource_id,
            status,
            updated_at,
            revision,
            true,
        ),
        resource_review_action(
            lifecycle_stage,
            resource_kind,
            resource_id,
            status,
            updated_at,
            revision,
            false,
        ),
    ]
}

fn resource_review_action(
    lifecycle_stage: &str,
    resource_kind: &str,
    resource_id: &str,
    status: &str,
    updated_at: Option<&str>,
    revision: i64,
    approve: bool,
) -> WorkItemActionResponse {
    let action_id = format!(
        "{}_{resource_kind}",
        if approve { "approve" } else { "reject" }
    );
    WorkItemActionResponse {
        id: action_id.clone(),
        lifecycle_stage: lifecycle_stage.to_string(),
        resource: resource_id.to_string(),
        status: "ready".to_string(),
        effect_class: "approval_boundary".to_string(),
        blockers: Vec::new(),
        approval_required: true,
        approval_requirements: vec![format!("{resource_kind}_review")],
        external_effect_summary: format!(
            "{} {resource_kind} {resource_id}. This review changes durable PHarness state only.",
            if approve { "Approve" } else { "Reject" }
        ),
        state_hash: lifecycle_action_hash(json!({
            "action": &action_id,
            "resource_kind": resource_kind,
            "resource_id": resource_id,
            "status": status,
            "updated_at": updated_at,
            "revision": revision,
        })),
    }
}

fn work_item_action_response(preview: &ReconcileWorkItemResponse) -> WorkItemActionResponse {
    let action = preview.action.as_str();
    let lifecycle_stage = if action.contains("pipeline") {
        "pipeline"
    } else if action.contains("gitops") {
        "gitops"
    } else if action.contains("deployment") || action.contains("argo") {
        "deployment"
    } else if action.contains("release") || action == "complete_work_item" {
        "release"
    } else {
        "source"
    };
    let effect_class = if action == "start_coding_attempt" {
        "model_execution"
    } else if action.contains("approval") || action.contains("authorization") {
        "approval_boundary"
    } else if action.starts_with("wait_") || action.contains("merge") {
        "external_wait"
    } else if matches!(
        action,
        "awaiting_git_delivery_execution"
            | "awaiting_pull_request_observation"
            | "awaiting_pipeline_execution"
            | "awaiting_gitops_base_revision"
            | "awaiting_gitops_delivery_execution"
            | "awaiting_gitops_pull_request_observation"
            | "awaiting_deployment_execution"
            | "awaiting_release_verification"
    ) {
        "external_effect"
    } else {
        "internal"
    };
    let hash_payload = json!({
        "work_item_id": preview.work_item.id,
        "work_item_updated_at": preview.work_item.updated_at,
        "action": preview.action,
        "can_apply": preview.can_apply,
        "blockers": preview.blockers,
        "authorization_checks": preview.authorization_checks,
    });
    let approval_requirements = preview
        .authorization_checks
        .iter()
        .filter(|check| matches!(check.status.as_str(), "missing" | "blocked" | "unavailable"))
        .map(|check| check.kind.clone())
        .collect::<Vec<_>>();
    WorkItemActionResponse {
        id: preview.action.clone(),
        lifecycle_stage: lifecycle_stage.to_string(),
        resource: preview.work_item.id.clone(),
        status: if preview.can_apply {
            "ready"
        } else {
            "blocked"
        }
        .to_string(),
        effect_class: effect_class.to_string(),
        blockers: preview.blockers.clone(),
        approval_required: effect_class == "approval_boundary" || !approval_requirements.is_empty(),
        approval_requirements,
        external_effect_summary: preview.effect_summary.clone(),
        state_hash: format!("{:x}", Sha256::digest(hash_payload.to_string().as_bytes())),
    }
}

fn work_item_delivery_segments(
    flow: &Option<SdlcFlowResponse>,
    workspace: Option<&WorkspaceResponse>,
) -> Vec<DeliverySegmentResponse> {
    let Some(flow) = flow else {
        return vec![delivery_segment(
            "source",
            "Source",
            "active",
            "Awaiting WorkPlan declaration before source work can begin.",
            Vec::new(),
        )];
    };

    sdlc_flow_delivery_segments(flow, workspace)
}

fn sdlc_flow_delivery_segments(
    flow: &SdlcFlowResponse,
    workspace: Option<&WorkspaceResponse>,
) -> Vec<DeliverySegmentResponse> {
    let change_set = flow.change_set.as_ref();
    let source_blocked = change_set.is_some_and(|item| is_blocked_delivery_status(&item.status));
    let source_complete = workspace.is_some_and(|item| item.status == "captured")
        && change_set.is_some_and(|item| is_complete_delivery_status(&item.status));
    let mut source_resources = vec![delivery_resource(
        "work_plan",
        &flow.work_plan.id,
        "WorkPlan",
        Some(flow.work_plan.summary.clone()),
    )];
    if let Some(workspace) = workspace {
        source_resources.push(delivery_resource(
            "workspace",
            &workspace.id,
            "Workspace",
            Some(format!(
                "{} @ {}",
                workspace.source_repo,
                workspace
                    .resolved_commit
                    .as_deref()
                    .unwrap_or(workspace.source_ref.as_str())
            )),
        ));
    }
    if let Some(change_set) = change_set {
        source_resources.push(delivery_resource(
            "change_set",
            &change_set.id,
            "ChangeSet",
            Some(change_set.summary.clone()),
        ));
    }
    if let Some(artifact) = flow
        .git_delivery
        .as_ref()
        .and_then(|delivery| delivery.latest_result.as_ref())
    {
        source_resources.push(delivery_resource(
            "artifact",
            &artifact.id,
            "Source PR evidence",
            Some(artifact.label.clone()),
        ));
    }
    let source = delivery_segment(
        "source",
        "Source",
        if source_blocked {
            "blocked"
        } else if source_complete {
            "complete"
        } else {
            "active"
        },
        if source_blocked {
            change_set
                .and_then(|item| item.status_reason.as_deref())
                .unwrap_or("Source change requires a new reviewed revision.")
        } else if source_complete {
            "Immutable source change and workspace provenance are recorded."
        } else {
            "Awaiting a captured workspace and reviewed source ChangeSet."
        },
        source_resources,
    );

    let pipeline = flow.pipeline_intent.as_ref();
    let build = next_delivery_segment(
        "build",
        "Build",
        source_complete,
        pipeline.map(|item| item.status.as_str()),
        pipeline.map(|item| {
            item.status_reason
                .as_deref()
                .unwrap_or(item.summary.as_str())
        }),
        pipeline.map(|item| {
            vec![delivery_resource(
                "pipeline_intent",
                &item.id,
                "PipelineIntent",
                Some(item.summary.clone()),
            )]
        }),
        [
            "Awaiting immutable source delivery before build can start.",
            "Awaiting a PipelineIntent for the immutable source revision.",
        ],
    );
    let build_complete = build.status == "complete";

    let gitops = flow.gitops_change_set.as_ref();
    let gitops_segment = next_delivery_segment(
        "gitops",
        "GitOps",
        build_complete,
        gitops.map(|item| item.status.as_str()),
        gitops.map(|item| {
            item.status_reason
                .as_deref()
                .unwrap_or(item.summary.as_str())
        }),
        gitops.map(|item| {
            vec![delivery_resource(
                "gitops_change_set",
                &item.id,
                "GitOps ChangeSet",
                Some(item.summary.clone()),
            )]
        }),
        [
            "Awaiting verified build output before GitOps delivery can start.",
            "Awaiting a GitOps ChangeSet for the verified build output.",
        ],
    );
    let gitops_complete = gitops_segment.status == "complete";

    let deploy = flow.deployment_intent.as_ref();
    let deploy_segment = next_delivery_segment(
        "deploy",
        "Deploy",
        gitops_complete,
        deploy.map(|item| item.status.as_str()),
        deploy.map(|item| {
            item.status_reason
                .as_deref()
                .unwrap_or(item.summary.as_str())
        }),
        deploy.map(|item| {
            vec![delivery_resource(
                "deployment_intent",
                &item.id,
                "DeploymentIntent",
                Some(item.summary.clone()),
            )]
        }),
        [
            "Awaiting GitOps merge provenance before deployment can start.",
            "Awaiting a DeploymentIntent for the immutable GitOps revision.",
        ],
    );
    let deploy_complete = deploy_segment.status == "complete";

    let release = flow.release.as_ref();
    let mut verify_resources = release
        .map(|item| {
            vec![delivery_resource(
                "release",
                &item.id,
                "Release",
                Some(item.summary.clone()),
            )]
        })
        .unwrap_or_default();
    if let Some(evidence) = &flow.registry_evidence {
        verify_resources.push(delivery_resource(
            "registry_evidence",
            &evidence.id,
            "Registry evidence",
            Some(evidence.summary.clone()),
        ));
    }
    let verify = next_delivery_segment(
        "verify",
        "Verify",
        deploy_complete,
        release.map(|item| item.status.as_str()),
        release.map(|item| {
            item.status_reason
                .as_deref()
                .unwrap_or(item.summary.as_str())
        }),
        Some(verify_resources),
        [
            "Awaiting completed deployment before verification can start.",
            "Awaiting a Release and post-deploy verification evidence.",
        ],
    );

    vec![source, build, gitops_segment, deploy_segment, verify]
}

fn delivery_resource(
    kind: &str,
    id: &str,
    label: &str,
    summary: Option<String>,
) -> DeliverySegmentResourceResponse {
    DeliverySegmentResourceResponse {
        kind: kind.to_string(),
        id: id.to_string(),
        label: label.to_string(),
        summary,
    }
}

fn delivery_segment(
    key: &str,
    label: &str,
    status: &str,
    summary: &str,
    resources: Vec<DeliverySegmentResourceResponse>,
) -> DeliverySegmentResponse {
    DeliverySegmentResponse {
        key: key.to_string(),
        label: label.to_string(),
        status: status.to_string(),
        summary: summary.to_string(),
        stopping_reason: (status != "complete").then(|| summary.to_string()),
        resources,
    }
}

fn next_delivery_segment(
    key: &str,
    label: &str,
    previous_complete: bool,
    resource_status: Option<&str>,
    resource_summary: Option<&str>,
    resources: Option<Vec<DeliverySegmentResourceResponse>>,
    summaries: [&str; 2],
) -> DeliverySegmentResponse {
    if !previous_complete {
        return delivery_segment(key, label, "unreached", summaries[0], Vec::new());
    }
    let Some(status) = resource_status else {
        return delivery_segment(key, label, "active", summaries[1], Vec::new());
    };
    let mapped_status = if is_complete_delivery_status(status) {
        "complete"
    } else if is_blocked_delivery_status(status) {
        "blocked"
    } else {
        "active"
    };
    delivery_segment(
        key,
        label,
        mapped_status,
        resource_summary.unwrap_or("Controller state recorded."),
        resources.unwrap_or_default(),
    )
}

fn is_complete_delivery_status(status: &str) -> bool {
    matches!(
        status,
        "captured"
            | "completed"
            | "verified"
            | "merged"
            | "succeeded"
            | "satisfied"
            | "ready"
            | "applied"
    )
}

fn is_blocked_delivery_status(status: &str) -> bool {
    matches!(status, "blocked" | "failed" | "rejected" | "stale")
}

async fn preflight_work_item(
    State(state): State<AppState>,
    Json(request): Json<CreateWorkItemRequest>,
) -> Result<Json<WorkItemPreflightResponse>, ApiError> {
    build_work_item_preflight(&state, &request).await.map(Json)
}

async fn build_work_item_preflight(
    state: &AppState,
    request: &CreateWorkItemRequest,
) -> Result<WorkItemPreflightResponse, ApiError> {
    let source_repo = request.source_repo.trim().trim_end_matches('/');
    let source_ref = request.source_ref.trim();
    let production =
        request.production_impacting || request.target_environment.trim() == PROTECTED_ENVIRONMENT;
    let budget = run_budget_from_request(request);
    let mut normalized_submission = json!({
        "title": request.title.trim(),
        "intent": request.intent.trim(),
        "acceptance_criteria": request.acceptance_criteria.iter().map(|value| value.trim()).filter(|value| !value.is_empty()).collect::<Vec<_>>(),
        "source_repo": source_repo,
        "source_ref": source_ref,
        "source_commit": request.source_commit.as_deref().map(str::trim),
        "pipeline_contract_id": request.pipeline_contract_id.as_deref().map(str::trim),
        "deployment_contract_id": request.deployment_contract_id.as_deref().map(str::trim),
        "gitops_repo": request.gitops_repo.as_deref().map(|value| value.trim().trim_end_matches('/')),
        "gitops_ref": request.gitops_ref.as_deref().map(str::trim),
        "gitops_kustomization_path": request.gitops_kustomization_path.as_deref().map(str::trim),
        "gitops_image_name": request.gitops_image_name.as_deref().map(str::trim),
        "target_environment": request.target_environment.trim(),
        "target_namespace": request.target_namespace.as_deref().map(str::trim),
        "argo_application": request.argo_application.as_deref().map(str::trim),
        "workload_kind": request.workload_kind.as_deref().map(str::trim),
        "workload_name": request.workload_name.as_deref().map(str::trim),
        "rollback_owner": request.rollback_owner.as_deref().map(str::trim),
        "production_impacting": production,
        "max_attempts": request.max_attempts.unwrap_or(3).clamp(1, 10),
        "max_elapsed_seconds": request.max_elapsed_seconds.unwrap_or(3_600).clamp(60, 86_400),
        "environment_profile_id": request.environment_profile_id.as_deref().map(str::trim),
        "run_budget": budget.as_ref().ok(),
    });
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if let Err(error) = &budget {
        blockers.push(error.message.clone());
    }
    if source_repo.is_empty() {
        blockers.push("source repository is required".to_string());
    }
    if source_ref.is_empty() {
        blockers.push("source base branch is required".to_string());
    }
    if request
        .acceptance_criteria
        .iter()
        .all(|value| value.trim().is_empty())
    {
        warnings.push(
            "No acceptance commands are defined; completion evidence will be weak.".to_string(),
        );
    }
    if let Some(commit) = request.source_commit.as_deref().map(str::trim) {
        if !immutable_git_object_id(commit) {
            blockers
                .push("source_commit must be a full 40- or 64-character Git object ID".to_string());
        }
    } else if production {
        blockers.push("production requires an immutable source_commit".to_string());
    }
    if production && !request_matches_protected_target(request) {
        blockers.push(
            "production target does not exactly match the protected yfinance-wrapper target"
                .to_string(),
        );
    } else if request.target_environment.trim() != "dev" && !production {
        blockers.push("only dev or the exact protected production target is supported".to_string());
    }
    if production && !state.protected_target.exact_locked_match {
        blockers.push(
            "deployed protected-target configuration does not exactly match the locked production target"
                .to_string(),
        );
    }

    let profile_id = request
        .environment_profile_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let selected_profile = match profile_id {
        Some(id) => match environment::select_profile(&state.environment_profiles, id, source_repo)
        {
            Ok(profile) => Some(profile),
            Err(error) => {
                blockers.push(error);
                None
            }
        },
        None if production => {
            blockers.push("production requires environment_profile_id".to_string());
            None
        }
        None => {
            warnings.push(
                "No immutable environment profile selected; legacy generic runner will be used."
                    .to_string(),
            );
            None
        }
    };
    if production {
        if let Some(profile) = selected_profile {
            let capability = format!("environment_profile:{}", profile.id);
            let verified = state
                .store
                .latest_capability_verification(&capability)
                .await?
                .is_some_and(|verification| {
                    verification.status == "available"
                        && verification
                            .expires_at
                            .parse::<u128>()
                            .is_ok_and(|expires| expires > current_millis())
                });
            if !verified {
                blockers.push(format!(
                    "environment profile {} requires a fresh passing isolated verification",
                    profile.id
                ));
            }
        }
    }

    let mut repository_contract = None;
    let mut repository_contract_hash = None;
    if production {
        if let (Some(profile), Some(commit)) = (
            selected_profile,
            request
                .source_commit
                .as_deref()
                .map(str::trim)
                .filter(|value| immutable_git_object_id(value)),
        ) {
            match environment::inspect_remote_project_contract(source_repo, commit).await {
                Ok((contract, hash)) => {
                    if contract.environment_profile != profile.id {
                        blockers.push(format!(
                            "repository contract selects {} instead of requested profile {}",
                            contract.environment_profile, profile.id
                        ));
                    }
                    let declared = contract
                        .acceptance_commands
                        .iter()
                        .map(|command| command.command.trim())
                        .collect::<BTreeSet<_>>();
                    for requested in request
                        .acceptance_criteria
                        .iter()
                        .map(|command| command.trim())
                        .filter(|command| !command.is_empty())
                    {
                        if !declared.contains(requested) {
                            blockers.push(format!(
                                "acceptance command is not declared by the repository contract: {requested}"
                            ));
                        }
                    }
                    repository_contract_hash = Some(hash);
                    repository_contract = serde_json::to_value(contract).ok();
                }
                Err(error) => blockers.push(format!(
                    "repository contract preflight failed before submission: {error}"
                )),
            }
        }
    }
    if let Some(object) = normalized_submission.as_object_mut() {
        object.insert(
            "repository_contract".to_string(),
            repository_contract
                .clone()
                .unwrap_or(serde_json::Value::Null),
        );
        object.insert(
            "repository_contract_hash".to_string(),
            repository_contract_hash
                .clone()
                .map(serde_json::Value::String)
                .unwrap_or(serde_json::Value::Null),
        );
    }

    let pipeline_contract = match request.pipeline_contract_id.as_deref().map(str::trim) {
        Some(id) if !id.is_empty() => match state.store.get_pipeline_contract(id).await? {
            Some(contract) => {
                if contract.status != "active" {
                    blockers.push(format!(
                        "PipelineContract {id} is {} rather than active",
                        contract.status
                    ));
                }
                if production
                    && (contract.namespace != PROTECTED_PIPELINE_NAMESPACE
                        || contract.pipeline_ref != PROTECTED_PIPELINE_REF
                        || pipeline_contract_spec(&contract.contract_json)
                            .and_then(|spec| {
                                validate_pipeline_contract_spec(&spec)?;
                                if spec.source_revision_param.as_deref() != Some("revision") {
                                    return Err(ApiError::bad_request(
                                        "protected production PipelineContract must bind revision as its immutable source parameter",
                                    ));
                                }
                                Ok(())
                            })
                            .is_err())
                {
                    blockers.push(format!(
                        "PipelineContract {id} does not match tekton-pipelines/pharness-yfinance-build with immutable revision"
                    ));
                }
                Some(contract)
            }
            None => {
                blockers.push(format!("PipelineContract {id} does not exist"));
                None
            }
        },
        _ if production => {
            blockers.push("production requires pipeline_contract_id".to_string());
            None
        }
        _ => None,
    };
    let deployment_contract = match request.deployment_contract_id.as_deref().map(str::trim) {
        Some(id) if !id.is_empty() => match state.store.get_deployment_contract(id).await? {
            Some(contract) => {
                if contract.status != "active" {
                    blockers.push(format!(
                        "DeploymentContract {id} is {} rather than active",
                        contract.status
                    ));
                }
                if production {
                    let target_matches = contract.target_environment == PROTECTED_ENVIRONMENT
                        && contract.target_namespace == PROTECTED_NAMESPACE
                        && contract.argo_application == PROTECTED_ARGO_APPLICATION;
                    let spec_matches = deployment_contract_spec(&contract.contract_json)
                        .and_then(|spec| {
                            validate_deployment_contract_spec(&spec)?;
                            validate_protected_production_deployment_contract(&spec)
                        })
                        .is_ok();
                    if !target_matches || !spec_matches {
                        blockers.push(format!(
                            "DeploymentContract {id} does not match the exact protected workload and /healthz contract"
                        ));
                    }
                }
                Some(contract)
            }
            None => {
                blockers.push(format!("DeploymentContract {id} does not exist"));
                None
            }
        },
        _ if production => {
            blockers.push("production requires deployment_contract_id".to_string());
            None
        }
        _ => None,
    };

    let checks = capability_statuses(state).await?;
    if production {
        for capability in [
            "model_provider",
            "source_workspace",
            "source_writer",
            "source_observer",
            "gitops_writer",
            "gitops_observer",
            "tekton",
            "argo",
            "observability",
        ] {
            if let Some(check) = checks.iter().find(|check| check.capability == capability) {
                if check.status != "available" {
                    blockers.push(format!(
                        "{} must have a fresh passing isolated verification: {}",
                        check.capability, check.summary
                    ));
                }
            }
        }
    }
    let selected_contracts = json!({
        "pipeline": pipeline_contract,
        "deployment": deployment_contract,
    });
    let predicted_external_mutations = if production {
        vec![
            format!("source pull request in {PROTECTED_SOURCE_REPO}"),
            "PipelineRun tekton-pipelines/pharness-yfinance-build".to_string(),
            format!("GitOps pull request in {PROTECTED_GITOPS_REPO}"),
            format!("Argo sync of {PROTECTED_ARGO_APPLICATION}"),
        ]
    } else {
        vec![format!("source pull request in {source_repo}")]
    };
    let production_gates = if production {
        vec![
            "source_mutation".to_string(),
            "pipeline_mutation".to_string(),
            "gitops_mutation".to_string(),
            "cluster_mutation".to_string(),
            "production_deployment".to_string(),
        ]
    } else {
        Vec::new()
    };
    let rollback_prerequisites = if production {
        vec![
            "capture current deployment image digest and readiness".to_string(),
            "capture current Argo and GitOps revisions".to_string(),
            format!("bind rollback ownership to {PROTECTED_ROLLBACK_OWNER}"),
            "prepare a digest-only rollback pull request before Argo authorization".to_string(),
        ]
    } else {
        Vec::new()
    };
    let hash_payload = json!({
        "submission": normalized_submission,
        "contracts": selected_contracts,
        "checks": checks,
        "mutations": predicted_external_mutations,
    });
    let state_hash = format!("{:x}", Sha256::digest(hash_payload.to_string().as_bytes()));
    Ok(WorkItemPreflightResponse {
        ready: blockers.is_empty(),
        state_hash,
        normalized_submission,
        selected_contracts,
        checks,
        blockers,
        warnings,
        predicted_external_mutations,
        production_gates,
        rollback_prerequisites,
    })
}

fn request_matches_protected_target(request: &CreateWorkItemRequest) -> bool {
    request.target_environment.trim() == PROTECTED_ENVIRONMENT
        && request.target_namespace.as_deref().map(str::trim) == Some(PROTECTED_NAMESPACE)
        && request.argo_application.as_deref().map(str::trim) == Some(PROTECTED_ARGO_APPLICATION)
        && request.workload_kind.as_deref().map(str::trim) == Some(PROTECTED_WORKLOAD_KIND)
        && request.workload_name.as_deref().map(str::trim) == Some(PROTECTED_WORKLOAD_NAME)
        && request.source_repo.trim().trim_end_matches('/') == PROTECTED_SOURCE_REPO
        && request
            .gitops_repo
            .as_deref()
            .map(|value| value.trim().trim_end_matches('/'))
            == Some(PROTECTED_GITOPS_REPO)
        && request.gitops_kustomization_path.as_deref().map(str::trim)
            == Some(PROTECTED_KUSTOMIZATION_PATH)
        && request.gitops_image_name.as_deref().map(str::trim) == Some(PROTECTED_IMAGE_NAME)
        && request.rollback_owner.as_deref().map(str::trim) == Some(PROTECTED_ROLLBACK_OWNER)
}

fn stored_work_item_matches_protected_target(item: &StoredWorkItem) -> bool {
    item.production_impacting
        && item.target_environment == PROTECTED_ENVIRONMENT
        && item.target_namespace.as_deref() == Some(PROTECTED_NAMESPACE)
        && item.argo_application.as_deref() == Some(PROTECTED_ARGO_APPLICATION)
        && item.workload_kind.as_deref() == Some(PROTECTED_WORKLOAD_KIND)
        && item.workload_name.as_deref() == Some(PROTECTED_WORKLOAD_NAME)
        && item.source_repo.trim_end_matches('/') == PROTECTED_SOURCE_REPO
        && item
            .gitops_repo
            .as_deref()
            .map(|value| value.trim_end_matches('/'))
            == Some(PROTECTED_GITOPS_REPO)
        && item.gitops_kustomization_path.as_deref() == Some(PROTECTED_KUSTOMIZATION_PATH)
        && item.gitops_image_name.as_deref() == Some(PROTECTED_IMAGE_NAME)
        && item.rollback_owner.as_deref() == Some(PROTECTED_ROLLBACK_OWNER)
        && item
            .source_commit
            .as_deref()
            .is_some_and(immutable_git_object_id)
        && item.pipeline_contract_id.is_some()
        && item.deployment_contract_id.is_some()
}

fn work_item_target_supported(item: &StoredWorkItem) -> bool {
    (!item.production_impacting && item.target_environment == "dev")
        || stored_work_item_matches_protected_target(item)
}

fn bounded_production_grant_expiry(
    item: &StoredWorkItem,
    requested: Option<String>,
) -> Result<Option<String>, ApiError> {
    if !item.production_impacting {
        return Ok(requested);
    }
    let expires_at = requested.ok_or_else(|| {
        ApiError::bad_request("production authorization requires expires_at within 30 minutes")
    })?;
    let expires_ms = expires_at
        .parse::<u128>()
        .map_err(|_| ApiError::bad_request("expires_at must be unix milliseconds"))?;
    let now = current_millis();
    if expires_ms <= now || expires_ms > now + 30 * 60 * 1_000 {
        return Err(ApiError::bad_request(
            "production authorization must expire within the next 30 minutes",
        ));
    }
    Ok(Some(expires_at))
}

async fn create_work_item(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Json(request): Json<CreateWorkItemRequest>,
) -> Result<Json<WorkItemResponse>, ApiError> {
    let production =
        request.production_impacting || request.target_environment.trim() == PROTECTED_ENVIRONMENT;
    let production_preflight = if production {
        let preflight = build_work_item_preflight(&state, &request).await?;
        if !preflight.ready {
            return Err(ApiError::conflict(format!(
                "production WorkItem preflight failed: {}",
                preflight.blockers.join("; ")
            )));
        }
        if request.preflight_state_hash.as_deref() != Some(preflight.state_hash.as_str()) {
            return Err(ApiError::conflict(
                "production WorkItem preflight is missing or stale; run preflight again",
            ));
        }
        Some(preflight)
    } else {
        None
    };
    let run_budget = run_budget_from_request(&request)?;
    let title = required_text(request.title, "title")?;
    let intent = required_text(request.intent, "intent")?;
    let source_repo = required_text(request.source_repo, "source_repo")?;
    let source_ref = required_text(request.source_ref, "source_ref")?;
    let target_environment = required_text(request.target_environment, "target_environment")?;
    let target_namespace = clean_optional_text(request.target_namespace);
    let argo_application = clean_optional_text(request.argo_application);
    validate_kubernetes_name("target_environment", &target_environment)?;
    if let Some(namespace) = &target_namespace {
        validate_kubernetes_name("target_namespace", namespace)?;
    }
    if let Some(application) = &argo_application {
        validate_kubernetes_name("argo_application", application)?;
    }
    let max_attempts = if production {
        request.max_attempts.unwrap_or(2).clamp(1, 3)
    } else {
        request.max_attempts.unwrap_or(2).clamp(1, 10)
    };
    let max_elapsed_seconds = run_budget.active_execution_seconds;
    let repository_contract_json = production_preflight
        .as_ref()
        .and_then(|preflight| preflight.normalized_submission.get("repository_contract"))
        .filter(|value| !value.is_null())
        .cloned();
    let repository_contract_hash = production_preflight
        .as_ref()
        .and_then(|preflight| {
            preflight
                .normalized_submission
                .get("repository_contract_hash")
        })
        .and_then(serde_json::Value::as_str)
        .map(ToOwned::to_owned);
    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    let work_item = state
        .store
        .create_work_item(CreateWorkItem {
            id: format!("witem_{}", unique_suffix()),
            status: "submitted".to_string(),
            title,
            intent,
            acceptance_criteria: request
                .acceptance_criteria
                .into_iter()
                .filter_map(|criterion| clean_optional_text(Some(criterion)))
                .collect(),
            source_repo,
            source_ref,
            source_commit: clean_optional_text(request.source_commit),
            pipeline_contract_id: clean_optional_text(request.pipeline_contract_id),
            deployment_contract_id: clean_optional_text(request.deployment_contract_id),
            gitops_repo: clean_optional_text(request.gitops_repo),
            gitops_ref: clean_optional_text(request.gitops_ref),
            gitops_kustomization_path: clean_optional_text(request.gitops_kustomization_path),
            gitops_image_name: clean_optional_text(request.gitops_image_name),
            target_environment,
            target_namespace,
            argo_application,
            workload_kind: clean_optional_text(request.workload_kind),
            workload_name: clean_optional_text(request.workload_name),
            rollback_owner: clean_optional_text(request.rollback_owner),
            production_impacting: production,
            max_attempts,
            max_elapsed_seconds,
            created_by: actor.clone(),
            environment_profile_id: clean_optional_text(request.environment_profile_id),
            run_budget,
            repository_contract_json,
            repository_contract_hash,
            environment_preparation_status: if production {
                "pending".to_string()
            } else {
                "not_required".to_string()
            },
        })
        .await?;
    let work_item = state
        .store
        .set_work_item_origin(&work_item.id, "operator")
        .await?;
    append_work_item_audit_event(
        &state.store,
        &work_item,
        "work_item.submitted",
        actor,
        json!({ "status": "submitted" }),
    )
    .await?;
    Ok(Json(work_item.into()))
}

async fn list_work_item_events(
    State(state): State<AppState>,
    Path(work_item_id): Path<String>,
) -> Result<Json<AuditEventsResponse>, ApiError> {
    state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    let events = state
        .store
        .list_audit_events(Some("work_item"), Some(&work_item_id), None, 200)
        .await?
        .into_iter()
        .map(Into::into)
        .collect();
    Ok(Json(AuditEventsResponse { events }))
}

#[derive(Debug, Default, serde::Deserialize)]
struct ListControllerWaitsQuery {
    status: Option<String>,
    wait_kind: Option<String>,
    due_before_ms: Option<i64>,
    limit: Option<u32>,
    offset: Option<u32>,
}

async fn list_work_item_controller_waits(
    State(state): State<AppState>,
    Path(work_item_id): Path<String>,
    Query(query): Query<ListControllerWaitsQuery>,
) -> Result<Json<ControllerWaitsResponse>, ApiError> {
    state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    let limit = query.limit.unwrap_or(50).clamp(1, 200);
    let offset = query.offset.unwrap_or(0);
    let controller_waits = state
        .store
        .list_controller_waits(ControllerWaitListFilter {
            work_item_id: Some(work_item_id),
            status: clean_optional_text(query.status),
            wait_kind: clean_optional_text(query.wait_kind),
            due_before_ms: query.due_before_ms,
            limit,
            offset,
        })
        .await?
        .into_iter()
        .map(Into::into)
        .collect::<Vec<_>>();
    let count = controller_waits.len();
    Ok(Json(ControllerWaitsResponse {
        controller_waits,
        count,
        limit,
        offset,
    }))
}

/// Reconcile due controller waits against already-persisted delivery evidence.
/// This endpoint never calls a provider, creates a worker Job, retries an
/// action, merges a pull request, or mutates an external target.
async fn reconcile_due_controller_waits(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Json(request): Json<ReconcileDueControllerWaitsRequest>,
) -> Result<Json<ReconcileDueControllerWaitsResponse>, ApiError> {
    let evaluated_at = current_millis();
    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    let waits = state
        .store
        .list_controller_waits(ControllerWaitListFilter {
            status: Some("active".to_string()),
            due_before_ms: Some(
                i64::try_from(evaluated_at)
                    .map_err(|_| ApiError::internal("controller clock exceeds SQLite range"))?,
            ),
            limit: request.limit.unwrap_or(25).clamp(1, 50),
            ..ControllerWaitListFilter::default()
        })
        .await?;
    let checked = waits.len();
    let mut pending = 0;
    let mut progressed = 0;
    let mut blocked = 0;
    let mut results = Vec::with_capacity(waits.len());

    for wait in waits {
        let work_item = state
            .store
            .get_work_item(&wait.work_item_id)
            .await?
            .ok_or_else(|| ApiError::not_found("work_item", &wait.work_item_id))?;
        if matches!(
            work_item.status.as_str(),
            "completed" | "cancelled" | "failed"
        ) {
            let reason = format!("WorkItem is terminal ({})", work_item.status);
            let resolved = state
                .store
                .resolve_controller_wait(&wait.id, "resolved", reason.clone())
                .await?;
            append_controller_wait_audit_event(
                &state.store,
                &resolved,
                "controller_wait.resolved",
                actor.clone(),
                Some(reason.clone()),
            )
            .await?;
            results.push(ControllerWaitTickResult {
                controller_wait: resolved.into(),
                outcome: "resolved".to_string(),
                next_action: None,
                work_item: work_item.into(),
                message: reason,
            });
            continue;
        }

        let deadline_at = wait.deadline_at.parse::<u128>().unwrap_or(0);
        if deadline_at <= evaluated_at || wait.check_count >= wait.max_checks {
            let reason = if deadline_at <= evaluated_at {
                "controller wait deadline elapsed without observed progress".to_string()
            } else {
                format!(
                    "controller wait exhausted {} observation checks without observed progress",
                    wait.max_checks
                )
            };
            let expired = state
                .store
                .resolve_controller_wait(&wait.id, "expired", reason.clone())
                .await?;
            append_controller_wait_audit_event(
                &state.store,
                &expired,
                "controller_wait.expired",
                actor.clone(),
                Some(reason.clone()),
            )
            .await?;
            let work_item = block_work_item_from_controller_wait_expiry(
                &state,
                &work_item,
                &expired,
                actor.clone(),
                reason.clone(),
            )
            .await?;
            blocked += 1;
            results.push(ControllerWaitTickResult {
                controller_wait: expired.into(),
                outcome: "blocked".to_string(),
                next_action: None,
                work_item: work_item.into(),
                message: reason,
            });
            continue;
        }

        if let Err(error) = observe_due_controller_wait(&state, &wait, actor.clone()).await {
            append_controller_wait_audit_event(
                &state.store,
                &wait,
                "controller_wait.observation_failed",
                actor.clone(),
                Some(format!(
                    "read-only PipelineRun observation was unavailable ({})",
                    controller_wait_observation_failure_reason(&error)
                )),
            )
            .await?;
        }

        let Json(snapshot) = reconcile_work_item(
            State(state.clone()),
            None,
            Path(work_item.id.clone()),
            Json(ReconcileWorkItemRequest {
                apply: false,
                actor: actor.clone(),
                reason: None,
                max_turns: None,
            }),
        )
        .await?;
        let expected_action = wait
            .data_json
            .get("controller_action")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if snapshot.action == expected_action {
            let checked_wait = state
                .store
                .record_controller_wait_check(
                    &wait.id,
                    evaluated_at
                        .saturating_add(CONTROLLER_WAIT_INTERVAL_MS)
                        .to_string(),
                )
                .await?;
            append_controller_wait_audit_event(
                &state.store,
                &checked_wait,
                "controller_wait.checked",
                actor.clone(),
                Some("no new durable evidence observed".to_string()),
            )
            .await?;
            pending += 1;
            results.push(ControllerWaitTickResult {
                controller_wait: checked_wait.into(),
                outcome: "pending".to_string(),
                next_action: Some(snapshot.action),
                work_item: snapshot.work_item,
                message: "no new durable evidence observed; scheduled the next bounded check"
                    .to_string(),
            });
        } else {
            let reason = format!(
                "durable evidence advanced controller action from {expected_action} to {}",
                snapshot.action
            );
            let resolved = state
                .store
                .resolve_controller_wait(&wait.id, "resolved", reason.clone())
                .await?;
            append_controller_wait_audit_event(
                &state.store,
                &resolved,
                "controller_wait.progressed",
                actor.clone(),
                Some(reason.clone()),
            )
            .await?;
            progressed += 1;
            results.push(ControllerWaitTickResult {
                controller_wait: resolved.into(),
                outcome: "progressed".to_string(),
                next_action: Some(snapshot.action),
                work_item: snapshot.work_item,
                message: reason,
            });
        }
    }

    Ok(Json(ReconcileDueControllerWaitsResponse {
        evaluated_at: evaluated_at.to_string(),
        checked,
        pending,
        progressed,
        blocked,
        results,
    }))
}

/// Refreshes only the PipelineRun already named in durable PipelineIntent execution state.
/// This is an observation adapter: it never dispatches Tekton work, retries an execution, or
/// otherwise mutates an external system. Terminal evidence uses the existing outcome boundary;
/// the normal controller reconciliation decides whether that evidence made progress.
async fn observe_due_controller_wait(
    state: &AppState,
    wait: &StoredControllerWait,
    actor: Option<String>,
) -> Result<(), ApiError> {
    match wait.wait_kind.as_str() {
        "pipeline_execution" => observe_due_pipeline_execution_wait(state, wait, actor).await,
        "deployment_execution" => observe_due_deployment_execution_wait(state, wait, actor).await,
        _ => Ok(()),
    }
}

async fn observe_due_pipeline_execution_wait(
    state: &AppState,
    wait: &StoredControllerWait,
    actor: Option<String>,
) -> Result<(), ApiError> {
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&wait.work_item_id)
        .await?
        .ok_or_else(|| ApiError::conflict("controller wait has no WorkPlan lineage"))?;
    let change_set = state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .ok_or_else(|| ApiError::conflict("controller wait has no ChangeSet lineage"))?;
    let intent = state
        .store
        .get_pipeline_intent_by_change_set(&change_set.id)
        .await?
        .ok_or_else(|| ApiError::conflict("controller wait has no PipelineIntent lineage"))?;
    if intent.status != "executing" {
        return Ok(());
    }

    let execution_id = intent
        .intent_json
        .pointer("/execution_state/execution_id")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| ApiError::conflict("PipelineIntent execution has no execution_id"))?
        .to_string();
    let namespace = intent
        .intent_json
        .pointer("/execution_state/pipeline_run_namespace")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| ApiError::conflict("PipelineIntent execution has no PipelineRun namespace"))?
        .to_string();
    let name = intent
        .intent_json
        .pointer("/execution_state/pipeline_run_name")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| ApiError::conflict("PipelineIntent execution has no PipelineRun name"))?
        .to_string();
    validate_kubernetes_name("PipelineIntent PipelineRun namespace", &namespace)?;
    validate_kubernetes_name("PipelineIntent PipelineRun name", &name)?;

    let action = AgentAction::TektonAnalyzePipelineRun {
        id: ActionId::new(format!("controller.wait.{}.tekton", wait.id)),
        reason: "Observe the exact PipelineRun recorded by a durable controller wait".to_string(),
        namespace: namespace.clone(),
        name: name.clone(),
    };
    if !matches!(
        state.policy.evaluate_action(&action),
        PolicyDecision::Allow { .. }
    ) {
        return Err(ApiError::conflict(
            "controller policy does not permit read-only Tekton PipelineRun observation",
        ));
    }
    let result = state
        .cluster_tools
        .execute(&action)
        .await
        .map_err(|_| ApiError::internal("read-only Tekton PipelineRun observation failed"))?;
    let analysis = result
        .content
        .get("analysis")
        .cloned()
        .ok_or_else(|| ApiError::internal("Tekton observation returned no analysis"))?;
    validate_pipeline_run_analysis_target(&namespace, &name, &analysis)?;
    let observed_status = analysis
        .pointer("/summary/status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");

    match observed_status {
        "succeeded" | "failed" | "cancelled" => {
            let outcome_status = if observed_status == "succeeded" {
                "completed"
            } else {
                "failed"
            };
            let Json(updated) = internal_pipeline_intent_execution_outcome(
                State(state.clone()),
                Path(intent.id.clone()),
                Json(PipelineIntentExecutionOutcomeRequest {
                    execution_id: execution_id.clone(),
                    status: outcome_status.to_string(),
                    pipeline_run_namespace: Some(namespace.clone()),
                    pipeline_run_name: Some(name.clone()),
                    error: (observed_status != "succeeded")
                        .then(|| format!("PipelineRun reached terminal {observed_status} status")),
                    pipeline_run_analysis: Some(analysis.clone()),
                    analysis_error: None,
                }),
            )
            .await?;
            let updated_intent = state
                .store
                .get_pipeline_intent(&updated.id)
                .await?
                .ok_or_else(|| ApiError::not_found("pipeline_intent", &updated.id))?;
            append_pipeline_intent_audit_event(
                &state.store,
                &updated_intent,
                "pipeline_intent.execution_observed",
                actor.or_else(|| Some("controller:tekton-observer".to_string())),
                Some("recorded terminal PipelineRun evidence from an exact typed read".to_string()),
                json!({
                    "execution_id": execution_id,
                    "pipeline_run_namespace": namespace,
                    "pipeline_run_name": name,
                    "observed_status": observed_status,
                }),
            )
            .await?;
        }
        "running" | "unknown" => {
            persist_pipeline_execution_wait_observation(
                state,
                &intent,
                PipelineExecutionWaitObservationInput {
                    execution_id: &execution_id,
                    namespace: &namespace,
                    name: &name,
                    observed_status,
                    analysis: &analysis,
                },
                actor,
            )
            .await?;
        }
        _ => {
            return Err(ApiError::internal(
                "Tekton observation returned an unsupported PipelineRun status",
            ));
        }
    }

    Ok(())
}

/// Reads one Argo CD Application already bound to an active Argo execution.
/// It never initiates reconciliation: terminal evidence is accepted only from
/// Argo's compact operation phase and exact declared application target.
async fn observe_due_deployment_execution_wait(
    state: &AppState,
    wait: &StoredControllerWait,
    actor: Option<String>,
) -> Result<(), ApiError> {
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&wait.work_item_id)
        .await?
        .ok_or_else(|| ApiError::conflict("controller wait has no WorkPlan lineage"))?;
    let change_set = state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .ok_or_else(|| ApiError::conflict("controller wait has no ChangeSet lineage"))?;
    let pipeline_intent = state
        .store
        .get_pipeline_intent_by_change_set(&change_set.id)
        .await?
        .ok_or_else(|| ApiError::conflict("controller wait has no PipelineIntent lineage"))?;
    let intent = state
        .store
        .get_deployment_intent_by_pipeline_intent(&pipeline_intent.id)
        .await?
        .ok_or_else(|| ApiError::conflict("controller wait has no DeploymentIntent lineage"))?;
    if intent.status != "approved" {
        return Ok(());
    }
    let target = deployment_target(&intent)?;
    validate_kubernetes_name("DeploymentIntent argo_application", &target.application)?;
    let run_id = intent
        .run_id
        .clone()
        .ok_or_else(|| ApiError::conflict("DeploymentIntent has no coding run provenance"))?;
    let artifacts = state.store.list_artifacts(&run_id).await?;
    let execution = artifacts
        .iter()
        .filter(|artifact| {
            artifact.kind == "argo_sync_execution"
                && artifact.content_json.as_ref().is_some_and(|content| {
                    content.get("deployment_intent_id").and_then(Value::as_str)
                        == Some(intent.id.as_str())
                })
        })
        .max_by_key(|artifact| (&artifact.created_at, &artifact.id))
        .ok_or_else(|| ApiError::conflict("DeploymentIntent has no active Argo sync execution"))?;
    let execution_content = execution
        .content_json
        .as_ref()
        .and_then(Value::as_object)
        .ok_or_else(|| ApiError::conflict("Argo sync execution has no structured content"))?;
    let execution_id =
        required_json_string(execution_content, "execution_id", "Argo sync execution")?;
    let execution_target = execution_content
        .get("target")
        .and_then(Value::as_object)
        .ok_or_else(|| ApiError::conflict("Argo sync execution has no immutable target"))?;
    if execution_target.get("environment").and_then(Value::as_str) != Some(&target.environment)
        || execution_target.get("namespace").and_then(Value::as_str) != Some(&target.namespace)
        || execution_target
            .get("argo_application")
            .and_then(Value::as_str)
            != Some(&target.application)
    {
        return Err(ApiError::conflict(
            "Argo sync execution target no longer matches DeploymentIntent",
        ));
    }

    let action = AgentAction::ArgoGetApp {
        id: ActionId::new(format!("controller.wait.{}.argo", wait.id)),
        reason: "Observe the exact Argo CD Application recorded by a durable controller wait"
            .to_string(),
        app: target.application.clone(),
    };
    if !matches!(
        state.policy.evaluate_action(&action),
        PolicyDecision::Allow { .. }
    ) {
        return Err(ApiError::conflict(
            "controller policy does not permit read-only Argo Application observation",
        ));
    }
    let result = state
        .cluster_tools
        .execute(&action)
        .await
        .map_err(|_| ApiError::internal("read-only Argo Application observation failed"))?;
    let analysis = result
        .content
        .get("analysis")
        .cloned()
        .ok_or_else(|| ApiError::internal("Argo observation returned no analysis"))?;
    if analysis.get("kind").and_then(Value::as_str) != Some("Application")
        || analysis.get("name").and_then(Value::as_str) != Some(target.application.as_str())
    {
        return Err(ApiError::internal(
            "Argo observation did not match the durable Application target",
        ));
    }
    let sync_status = analysis.get("sync_status").and_then(Value::as_str);
    let health_status = analysis
        .get("health_status")
        .and_then(Value::as_str)
        .map(ToOwned::to_owned);
    let operation_phase = analysis.get("operation_phase").and_then(Value::as_str);
    let revision = analysis
        .get("operation_revision")
        .and_then(Value::as_str)
        .or_else(|| analysis.get("revision").and_then(Value::as_str))
        .map(ToOwned::to_owned);

    let terminal_status = match operation_phase {
        Some("Succeeded") if sync_status == Some("Synced") => Some("completed"),
        Some("Failed" | "Error") => Some("failed"),
        Some("Terminated") => Some("cancelled"),
        _ => None,
    };
    if let Some(status) = terminal_status {
        let Json(result) = internal_argo_sync_outcome(
            State(state.clone()),
            Path(intent.id.clone()),
            Json(ArgoSyncOutcomeRequest {
                execution_id: execution_id.clone(),
                status: status.to_string(),
                sync_status: sync_status.map(ToOwned::to_owned),
                health_status,
                operation_phase: operation_phase.map(ToOwned::to_owned),
                revision,
                error_code: (status != "completed").then(|| {
                    if status == "cancelled" {
                        "cancelled".to_string()
                    } else {
                        "argo_operation_failed".to_string()
                    }
                }),
            }),
        )
        .await?;
        append_deployment_intent_audit_event(
            &state.store,
            &intent,
            "deployment_intent.execution_observed",
            actor.or_else(|| Some("controller:argo-observer".to_string())),
            Some(
                "recorded terminal Argo Application evidence from an exact typed read".to_string(),
            ),
            json!({
                "execution_id": execution_id,
                "argo_application": target.application,
                "observed_status": status,
                "operation_phase": operation_phase,
                "sync_status": sync_status,
                "result_artifact_id": result.id,
            }),
        )
        .await?;
    } else {
        persist_deployment_execution_wait_observation(
            state,
            &intent,
            DeploymentExecutionWaitObservationInput {
                execution_id: &execution_id,
                application: &target.application,
                observed_operation_phase: operation_phase,
                observed_sync_status: sync_status,
                analysis: &analysis,
            },
            actor,
        )
        .await?;
    }
    Ok(())
}

struct DeploymentExecutionWaitObservationInput<'a> {
    execution_id: &'a str,
    application: &'a str,
    observed_operation_phase: Option<&'a str>,
    observed_sync_status: Option<&'a str>,
    analysis: &'a Value,
}

async fn persist_deployment_execution_wait_observation(
    state: &AppState,
    intent: &StoredDeploymentIntent,
    input: DeploymentExecutionWaitObservationInput<'_>,
    actor: Option<String>,
) -> Result<(), ApiError> {
    let phase = input.observed_operation_phase.unwrap_or("unknown");
    let observation_id = format!(
        "obs_argo_wait_{}_{}",
        safe_controller_wait_id_fragment(input.execution_id),
        safe_controller_wait_id_fragment(phase)
    );
    let observation = match state.store.get_observation(&observation_id).await? {
        Some(existing) => existing,
        None => {
            let created = state
                .store
                .create_observation(CreateObservation {
                    id: observation_id,
                    session_id: intent.session_id.clone(),
                    run_id: intent.run_id.clone(),
                    source: "argocd".to_string(),
                    kind: "argo_sync_wait_observation".to_string(),
                    subject: input.application.to_string(),
                    summary: format!(
                        "Argo Application {} remains {} during bounded controller wait",
                        input.application, phase
                    ),
                    resource_namespace: input
                        .analysis
                        .get("namespace")
                        .and_then(Value::as_str)
                        .map(ToOwned::to_owned),
                    resource_kind: Some("Application".to_string()),
                    resource_name: Some(input.application.to_string()),
                    resource_ref_json: Some(json!({
                        "apiVersion": "argoproj.io/v1alpha1",
                        "kind": "Application",
                        "name": input.application,
                    })),
                    artifact_id: None,
                    data_json: json!({
                        "execution_id": input.execution_id,
                        "operation_phase": input.observed_operation_phase,
                        "sync_status": input.observed_sync_status,
                        "analysis": input.analysis,
                    }),
                })
                .await?;
            append_observation_audit_event(
                &state.store,
                &created,
                "observation.created",
                actor
                    .clone()
                    .or_else(|| Some("controller:argo-observer".to_string())),
                Some("recorded nonterminal exact Argo Application observation".to_string()),
            )
            .await?;
            created
        }
    };
    append_deployment_intent_audit_event(
        &state.store,
        intent,
        "deployment_intent.execution_observed",
        actor.or_else(|| Some("controller:argo-observer".to_string())),
        Some(
            "recorded nonterminal Argo Application observation from an exact typed read"
                .to_string(),
        ),
        json!({
            "execution_id": input.execution_id,
            "argo_application": input.application,
            "operation_phase": input.observed_operation_phase,
            "sync_status": input.observed_sync_status,
            "observation_id": observation.id,
        }),
    )
    .await?;
    Ok(())
}

struct PipelineExecutionWaitObservationInput<'a> {
    execution_id: &'a str,
    namespace: &'a str,
    name: &'a str,
    observed_status: &'a str,
    analysis: &'a Value,
}

async fn persist_pipeline_execution_wait_observation(
    state: &AppState,
    intent: &StoredPipelineIntent,
    input: PipelineExecutionWaitObservationInput<'_>,
    actor: Option<String>,
) -> Result<(), ApiError> {
    let observation_id = format!(
        "obs_pipeline_wait_{}_{}",
        safe_controller_wait_id_fragment(input.execution_id),
        input.observed_status
    );
    let observation = match state.store.get_observation(&observation_id).await? {
        Some(existing) => existing,
        None => {
            let created = state
                .store
                .create_observation(CreateObservation {
                    id: observation_id,
                    session_id: intent.session_id.clone(),
                    run_id: intent.run_id.clone(),
                    source: "tekton".to_string(),
                    kind: "pipeline_run_wait_observation".to_string(),
                    subject: format!("{}/{}", input.namespace, input.name),
                    summary: format!(
                        "PipelineRun {}/{} remains {} during bounded controller wait",
                        input.namespace, input.name, input.observed_status
                    ),
                    resource_namespace: Some(input.namespace.to_string()),
                    resource_kind: Some("PipelineRun".to_string()),
                    resource_name: Some(input.name.to_string()),
                    resource_ref_json: Some(json!({
                        "apiVersion": "tekton.dev/v1",
                        "kind": "PipelineRun",
                        "namespace": input.namespace,
                        "name": input.name,
                    })),
                    artifact_id: None,
                    data_json: json!({
                        "execution_id": input.execution_id,
                        "observed_status": input.observed_status,
                        "analysis": input.analysis,
                    }),
                })
                .await?;
            append_observation_audit_event(
                &state.store,
                &created,
                "observation.created",
                actor
                    .clone()
                    .or_else(|| Some("controller:tekton-observer".to_string())),
                Some("recorded nonterminal exact PipelineRun observation".to_string()),
            )
            .await?;
            created
        }
    };
    append_pipeline_intent_audit_event(
        &state.store,
        intent,
        "pipeline_intent.execution_observed",
        actor.or_else(|| Some("controller:tekton-observer".to_string())),
        Some("recorded nonterminal PipelineRun observation from an exact typed read".to_string()),
        json!({
            "execution_id": input.execution_id,
            "pipeline_run_namespace": input.namespace,
            "pipeline_run_name": input.name,
            "observed_status": input.observed_status,
            "observation_id": observation.id,
        }),
    )
    .await?;
    Ok(())
}

fn validate_pipeline_run_analysis_target(
    namespace: &str,
    name: &str,
    analysis: &Value,
) -> Result<(), ApiError> {
    if analysis.get("kind").and_then(Value::as_str) != Some("PipelineRunAnalysis") {
        return Err(ApiError::internal(
            "Tekton observation returned an invalid PipelineRun analysis",
        ));
    }
    if analysis
        .pointer("/pipeline_run/namespace")
        .and_then(Value::as_str)
        != Some(namespace)
        || analysis
            .pointer("/pipeline_run/name")
            .and_then(Value::as_str)
            != Some(name)
    {
        return Err(ApiError::internal(
            "Tekton observation did not match the durable PipelineRun target",
        ));
    }
    Ok(())
}

fn safe_controller_wait_id_fragment(value: &str) -> String {
    let digest = Sha256::digest(value.as_bytes());
    format!("{:x}", digest)[..16].to_string()
}

fn controller_wait_observation_failure_reason(error: &ApiError) -> &'static str {
    match error.status {
        StatusCode::CONFLICT => "target or policy validation failed",
        _ => "typed observer did not return usable evidence",
    }
}

async fn transition_work_item(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
    Json(request): Json<TransitionWorkItemRequest>,
) -> Result<Json<WorkItemResponse>, ApiError> {
    let current = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    let target = WorkItemStatus::parse(&request.target_status)?;
    WorkItemStatus::parse(&current.status)?.ensure_can_transition_to(target)?;
    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    let reason = clean_optional_text(request.reason);
    let work_item = state
        .store
        .update_work_item_status(
            &work_item_id,
            target.as_str(),
            actor.clone(),
            reason.clone(),
        )
        .await?;
    append_work_item_audit_event(
        &state.store,
        &work_item,
        &format!("work_item.{}", target.as_str()),
        actor,
        json!({
            "previous_status": current.status,
            "status": work_item.status,
            "reason": reason,
        }),
    )
    .await?;
    Ok(Json(work_item.into()))
}

async fn cancel_work_item(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
    Json(request): Json<TransitionWorkItemRequest>,
) -> Result<Json<WorkItemResponse>, ApiError> {
    if request.target_status != "cancelled" {
        return Err(ApiError::bad_request(
            "work item cancel requires target_status cancelled",
        ));
    }
    transition_work_item(State(state), identity, Path(work_item_id), Json(request)).await
}

async fn create_work_plan_from_work_item(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
) -> Result<Json<CreateWorkPlanResponse>, ApiError> {
    if let Some(existing) = state
        .store
        .get_work_plan_by_work_item(&work_item_id)
        .await?
    {
        return Ok(Json(CreateWorkPlanResponse {
            work_plan: existing.into(),
            created: false,
        }));
    }
    let work_item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    if work_item.status != "planning" {
        return Err(ApiError::conflict(
            "a WorkItem must be planning before it can create a WorkPlan",
        ));
    }
    let actor = identity.map(|Extension(OperatorIdentity(name))| name);
    let session_id = SessionId::new(format!("ses_work_item_{}", unique_suffix()));
    state
        .store
        .create_session(CreateSession {
            id: session_id.clone(),
            title: format!("WorkItem: {}", work_item.title),
            cwd: format!("work-item/{}", work_item.id),
        })
        .await?;
    let work_plan = state
        .store
        .create_work_plan(work_plan_from_work_item(
            &work_item,
            session_id,
            format!("wplan_{}", unique_suffix()),
        ))
        .await?;
    for gate in approval_gates_from_work_item(&work_item, &work_plan) {
        let gate = state.store.create_approval_gate(gate).await?;
        append_approval_gate_audit_event(&state.store, &gate, "approval_gate.created", "created")
            .await?;
    }
    let workspace = state
        .store
        .create_workspace(CreateWorkspace {
            id: format!("ws_{}", unique_suffix()),
            work_item_id: work_item.id.clone(),
            run_id: None,
            status: "declared".to_string(),
            source_repo: work_item.source_repo.clone(),
            source_ref: work_item.source_ref.clone(),
            resolved_commit: None,
            branch: None,
            retention_status: "ephemeral".to_string(),
            actor: actor.clone(),
            reason: Some("WorkItem planning declared an isolated workspace".to_string()),
        })
        .await?;
    append_work_item_audit_event(
        &state.store,
        &work_item,
        "work_item.work_plan_created",
        actor.clone(),
        json!({ "work_plan_id": work_plan.id, "workspace_id": workspace.id }),
    )
    .await?;
    append_workspace_audit_event(&state.store, &workspace, "workspace.declared", actor).await?;

    let work_item = state
        .store
        .update_work_item_status(
            &work_item.id,
            "awaiting_approval",
            None,
            Some("WorkPlan and workspace are ready for review".to_string()),
        )
        .await?;
    append_work_item_audit_event(
        &state.store,
        &work_item,
        "work_item.awaiting_approval",
        None,
        json!({ "work_plan_id": work_plan.id, "workspace_id": workspace.id }),
    )
    .await?;

    Ok(Json(CreateWorkPlanResponse {
        work_plan: work_plan.into(),
        created: true,
    }))
}

async fn execute_work_item_action(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path((work_item_id, action_id)): Path<(String, String)>,
    Json(request): Json<ExecuteWorkItemActionRequest>,
) -> Result<Json<Value>, ApiError> {
    if request.reason.trim().is_empty() {
        return Err(ApiError::bad_request("action execution reason is required"));
    }
    if matches!(
        action_id.as_str(),
        "approve_rollback"
            | "execute_rollback_gitops_pr"
            | "approve_rollback_argo_sync"
            | "execute_rollback_argo_sync"
            | "observe_rollback_merge"
            | "observe_rollback_argo_sync"
    ) {
        let item = state
            .store
            .get_work_item(&work_item_id)
            .await?
            .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
        let rollback = latest_rollback_intent(&state, &item, None)
            .await?
            .ok_or_else(|| ApiError::conflict("WorkItem has no RollbackIntent action"))?;
        let rollback_id = rollback
            .pointer("/content/rollback_intent_id")
            .and_then(Value::as_str)
            .ok_or_else(|| ApiError::conflict("RollbackIntent ID is unavailable"))?;
        let expected_action_id = match rollback.pointer("/content/status").and_then(Value::as_str) {
            Some("prepared") => "approve_rollback",
            Some("approved") => "execute_rollback_gitops_pr",
            Some("awaiting_manual_merge") => "observe_rollback_merge",
            Some("ready_for_argo_sync") => "approve_rollback_argo_sync",
            Some("argo_approved") => "execute_rollback_argo_sync",
            Some("argo_syncing") => "observe_rollback_argo_sync",
            _ => {
                return Err(ApiError::conflict(
                    "RollbackIntent has no executable action at its current lifecycle state",
                ))
            }
        };
        let current_hash = format!("{:x}", Sha256::digest(rollback.to_string().as_bytes()));
        if action_id != expected_action_id || request.state_hash != current_hash {
            return Err(ApiError::conflict(
                "action preview is stale; reload the WorkItem flow before executing",
            ));
        }
        let response = match action_id.as_str() {
            "approve_rollback" | "approve_rollback_argo_sync" => {
                approve_rollback_intent(
                    State(state.clone()),
                    identity,
                    Path(rollback_id.to_string()),
                    Json(RollbackIntentRequest {
                        actor: request.actor,
                        reason: request.reason,
                        expires_at: None,
                    }),
                )
                .await?
                .0
            }
            "execute_rollback_gitops_pr" | "execute_rollback_argo_sync" => {
                execute_rollback_intent(State(state), Path(rollback_id.to_string()))
                    .await?
                    .0
            }
            "observe_rollback_merge" | "observe_rollback_argo_sync" => {
                observe_rollback_intent(State(state), Path(rollback_id.to_string()))
                    .await?
                    .0
            }
            _ => unreachable!(),
        };
        return Ok(Json(response));
    }
    let actor = identity
        .clone()
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor.clone()))
        .ok_or_else(|| ApiError::bad_request("action execution actor is required"))?;
    let Json(flow) = work_item_flow(State(state.clone()), Path(work_item_id.clone())).await?;
    if let Some(action) = flow
        .action_rail
        .iter()
        .find(|action| action.id == action_id)
    {
        if action.state_hash != request.state_hash {
            return Err(ApiError::conflict(
                "action preview is stale; reload the WorkItem flow before executing",
            ));
        }
        if action.status != "ready" {
            return Err(ApiError::conflict(format!(
                "action {} is blocked: {}",
                action.id,
                action
                    .blockers
                    .iter()
                    .map(|blocker| blocker.summary.as_str())
                    .collect::<Vec<_>>()
                    .join("; ")
            )));
        }
        let transition_target = if action.id.starts_with("approve_") {
            "approved"
        } else {
            "rejected"
        };
        let value = match action.id.as_str() {
            "approve_work_plan" | "reject_work_plan" => serde_json::to_value(
                transition_work_plan(
                    State(state.clone()),
                    Path(action.resource.clone()),
                    Json(TransitionWorkPlanRequest {
                        target_status: transition_target.to_string(),
                        actor: Some(actor.clone()),
                        reason: Some(request.reason.clone()),
                    }),
                )
                .await?
                .0,
            ),
            "authorize_workspace_and_start" => serde_json::to_value(
                execute_work_item(
                    State(state.clone()),
                    identity.clone(),
                    Path(work_item_id.clone()),
                    Json(ExecuteWorkItemRequest {
                        actor: Some(actor.clone()),
                        reason: Some(request.reason.clone()),
                        max_turns: None,
                    }),
                )
                .await?
                .0,
            ),
            "replan_work_item" => serde_json::to_value(
                replan_work_item(
                    State(state.clone()),
                    identity.clone(),
                    Path(work_item_id.clone()),
                    Json(ReplanWorkItemRequest {
                        actor: Some(actor.clone()),
                        reason: request.reason.clone(),
                    }),
                )
                .await?
                .0,
            ),
            "approve_budget_extension" => {
                let extension = state
                    .store
                    .get_budget_extension(&action.resource)
                    .await?
                    .ok_or_else(|| ApiError::not_found("budget_extension", &action.resource))?;
                serde_json::to_value(
                    runs::approve_run_budget_extension(
                        State(state.clone()),
                        identity.clone(),
                        Path((extension.run_id.to_string(), extension.id)),
                        Json(ApproveBudgetExtensionRequest {
                            actor: actor.clone(),
                            reason: request.reason.clone(),
                            state_hash: request.state_hash.clone(),
                        }),
                    )
                    .await?
                    .0,
                )
            }
            action_id if action_id.starts_with("satisfy_approval_gate:") => {
                let gate_id = action_id
                    .strip_prefix("satisfy_approval_gate:")
                    .ok_or_else(|| ApiError::conflict("approval gate action is malformed"))?;
                serde_json::to_value(
                    decide_approval_gate(
                        state.clone(),
                        gate_id.to_string(),
                        "satisfied",
                        DecideApprovalGateRequest {
                            decided_by: Some(actor.clone()),
                            reason: Some(request.reason.clone()),
                        },
                    )
                    .await?
                    .0,
                )
            }
            "approve_change_set" | "reject_change_set" => serde_json::to_value(
                transition_change_set(
                    State(state.clone()),
                    Path(action.resource.clone()),
                    Json(TransitionChangeSetRequest {
                        target_status: transition_target.to_string(),
                        actor: Some(actor.clone()),
                        reason: Some(request.reason.clone()),
                    }),
                )
                .await?
                .0,
            ),
            "approve_pipeline_intent" | "reject_pipeline_intent" => serde_json::to_value(
                transition_pipeline_intent(
                    State(state.clone()),
                    Path(action.resource.clone()),
                    Json(TransitionPipelineIntentRequest {
                        target_status: transition_target.to_string(),
                        actor: Some(actor.clone()),
                        reason: Some(request.reason.clone()),
                    }),
                )
                .await?
                .0,
            ),
            "approve_deployment_intent" | "reject_deployment_intent" => serde_json::to_value(
                transition_deployment_intent(
                    State(state.clone()),
                    Path(action.resource.clone()),
                    Json(TransitionDeploymentIntentRequest {
                        target_status: transition_target.to_string(),
                        actor: Some(actor.clone()),
                        reason: Some(request.reason.clone()),
                    }),
                )
                .await?
                .0,
            ),
            "approve_release" | "reject_release" => serde_json::to_value(
                transition_release(
                    State(state.clone()),
                    Path(action.resource.clone()),
                    Json(TransitionReleaseRequest {
                        target_status: transition_target.to_string(),
                        actor: Some(actor.clone()),
                        reason: Some(request.reason.clone()),
                    }),
                )
                .await?
                .0,
            ),
            _ => {
                // The controller-derived reconcile action below remains the
                // compatibility path for non-review lifecycle actions.
                serde_json::to_value(Value::Null)
            }
        }
        .map_err(|error| {
            ApiError::internal(format!("failed to serialize action result: {error}"))
        })?;
        if value != Value::Null {
            return Ok(Json(value));
        }
    }
    let Json(preview) = reconcile_work_item(
        State(state.clone()),
        identity.clone(),
        Path(work_item_id.clone()),
        Json(ReconcileWorkItemRequest {
            apply: false,
            actor: request.actor.clone(),
            reason: Some(request.reason.clone()),
            max_turns: None,
        }),
    )
    .await?;
    let action = work_item_action_response(&preview);
    if action.id != action_id || action.state_hash != request.state_hash {
        return Err(ApiError::conflict(
            "action preview is stale; reload the WorkItem flow before executing",
        ));
    }
    if !preview.can_apply {
        return Err(ApiError::conflict(format!(
            "action {} is blocked: {}",
            action.id, preview.message
        )));
    }
    let Json(response) = reconcile_work_item(
        State(state),
        identity,
        Path(work_item_id),
        Json(ReconcileWorkItemRequest {
            apply: true,
            actor: request.actor,
            reason: Some(request.reason),
            max_turns: None,
        }),
    )
    .await?;
    Ok(Json(serde_json::to_value(response).map_err(|error| {
        ApiError::internal(format!("failed to serialize reconcile response: {error}"))
    })?))
}

async fn advance_work_item(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
    Json(request): Json<AdvanceWorkItemRequest>,
) -> Result<Json<AdvanceWorkItemResponse>, ApiError> {
    if request.reason.trim().is_empty() {
        return Err(ApiError::bad_request("advance reason is required"));
    }
    let max_steps = request.max_steps.unwrap_or(10).clamp(1, 10);
    let mut steps = Vec::new();
    for _ in 0..max_steps {
        let Json(preview) = reconcile_work_item(
            State(state.clone()),
            identity.clone(),
            Path(work_item_id.clone()),
            Json(ReconcileWorkItemRequest {
                apply: false,
                actor: request.actor.clone(),
                reason: Some(request.reason.clone()),
                max_turns: None,
            }),
        )
        .await?;
        let safe_internal = matches!(
            preview.action.as_str(),
            "declare_work_plan"
                | "capture_change_set"
                | "prepare_git_delivery"
                | "complete_work_item"
        );
        if !safe_internal || !preview.can_apply {
            return Ok(Json(AdvanceWorkItemResponse {
                stopped_at: work_item_action_response(&preview),
                steps,
            }));
        }
        let Json(applied) = reconcile_work_item(
            State(state.clone()),
            identity.clone(),
            Path(work_item_id.clone()),
            Json(ReconcileWorkItemRequest {
                apply: true,
                actor: request.actor.clone(),
                reason: Some(request.reason.clone()),
                max_turns: None,
            }),
        )
        .await?;
        steps.push(applied);
    }
    let Json(preview) = reconcile_work_item(
        State(state),
        identity,
        Path(work_item_id),
        Json(ReconcileWorkItemRequest {
            apply: false,
            actor: request.actor,
            reason: Some(request.reason),
            max_turns: None,
        }),
    )
    .await?;
    Ok(Json(AdvanceWorkItemResponse {
        stopped_at: work_item_action_response(&preview),
        steps,
    }))
}

#[derive(Debug, serde::Deserialize)]
struct RollbackIntentRequest {
    actor: Option<String>,
    reason: String,
    #[serde(default)]
    expires_at: Option<String>,
}

async fn prepare_work_item_rollback_intent(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
    Json(request): Json<RollbackIntentRequest>,
) -> Result<Json<Value>, ApiError> {
    let reason = required_text(request.reason.clone(), "reason")?;
    let item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    if !stored_work_item_matches_protected_target(&item) {
        return Err(ApiError::conflict(
            "RollbackIntent is limited to the exact protected production target",
        ));
    }
    if let Some(existing) = latest_rollback_intent(&state, &item, None).await? {
        return Ok(Json(existing));
    }
    let deployment = execute_direct_capability(
        &state,
        AgentAction::KubernetesGet {
            id: ActionId::new(format!("act_{}_baseline_deployment", unique_suffix())),
            reason: reason.clone(),
            resource: "deployments".to_string(),
            namespace: Some(PROTECTED_NAMESPACE.to_string()),
            name: Some(PROTECTED_WORKLOAD_NAME.to_string()),
            all_namespaces: false,
            label_selector: None,
        },
        None,
    )
    .await?;
    let argo = execute_direct_capability(
        &state,
        AgentAction::ArgoGetApp {
            id: ActionId::new(format!("act_{}_baseline_argo", unique_suffix())),
            reason: reason.clone(),
            app: PROTECTED_ARGO_APPLICATION.to_string(),
        },
        None,
    )
    .await?;
    let pods = execute_direct_capability(
        &state,
        AgentAction::KubernetesGet {
            id: ActionId::new(format!("act_{}_baseline_pods", unique_suffix())),
            reason: reason.clone(),
            resource: "pods".to_string(),
            namespace: Some(PROTECTED_NAMESPACE.to_string()),
            name: None,
            all_namespaces: false,
            label_selector: Some("app=yfinance-wrapper".to_string()),
        },
        None,
    )
    .await?;
    let deployment_result = deployment.result.ok_or_else(|| {
        ApiError::conflict("production baseline Deployment observation did not execute")
    })?;
    let argo_result = argo.result.ok_or_else(|| {
        ApiError::conflict("production baseline Argo observation did not execute")
    })?;
    let pods_result = pods
        .result
        .ok_or_else(|| ApiError::conflict("production baseline Pod observation did not execute"))?;
    let expected_image = item
        .gitops_image_name
        .as_deref()
        .ok_or_else(|| ApiError::conflict("protected target has no image name"))?;
    let images = deployment_result
        .content
        .pointer("/analysis/containers")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let image_ref = images
        .iter()
        .filter_map(|container| container.get("image").and_then(Value::as_str))
        .find(|image| image.starts_with(&format!("{expected_image}@sha256:")))
        .ok_or_else(|| {
            ApiError::conflict(
                "running protected Deployment does not expose the expected immutable image",
            )
        })?
        .to_string();
    let image_digest = image_ref
        .split_once('@')
        .map(|(_, digest)| digest.to_string())
        .filter(|digest| immutable_image_digest(digest))
        .ok_or_else(|| ApiError::conflict("production baseline image digest is malformed"))?;
    let running_image_ids = pods_result
        .content
        .pointer("/output/items")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .flat_map(|pod| {
            pod.pointer("/status/containers")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
        })
        .filter_map(|container| container.get("imageID").and_then(Value::as_str))
        .collect::<Vec<_>>();
    if running_image_ids.is_empty()
        || !running_image_ids
            .iter()
            .all(|image_id| image_id.ends_with(&image_digest))
    {
        return Err(ApiError::conflict(
            "running Pod imageID does not exactly match the declared production baseline digest",
        ));
    }
    let ready = deployment_result
        .content
        .pointer("/analysis/status")
        .and_then(Value::as_str)
        == Some("healthy");
    if !ready {
        return Err(ApiError::conflict(
            "production baseline Deployment must be healthy before rollback preparation",
        ));
    }
    let argo_revision = argo_result
        .content
        .pointer("/analysis/revision")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("production baseline Argo revision is unavailable"))?;
    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    let rollback_intent_id = format!("rollback_{}", unique_suffix());
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&item.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent requires a WorkPlan"))?;
    let run_id = item
        .current_run_id
        .clone()
        .ok_or_else(|| ApiError::conflict("RollbackIntent requires coding run provenance"))?;
    let run = state
        .store
        .get_run(&run_id)
        .await?
        .ok_or_else(|| ApiError::not_found("run", run_id.as_str()))?;
    let gate = state
        .store
        .create_approval_gate(CreateApprovalGate {
            id: format!("agate_{}_rollback", unique_suffix()),
            work_item_id: Some(item.id.clone()),
            remediation_plan_id: None,
            incident_id: None,
            session_id: run.session_id.clone(),
            run_id: Some(run_id.clone()),
            status: "pending".to_string(),
            gate_kind: "production_rollback".to_string(),
            gate_order: 90,
            title: format!("Approve rollback for {}", item.title),
            summary: format!("Restore only {image_digest} through a manual GitOps pull request"),
            risk_level: "critical".to_string(),
            resource_namespace: item.target_namespace.clone(),
            resource_kind: item.workload_kind.clone(),
            resource_name: item.workload_name.clone(),
            gate_json: json!({
                "rollback_intent_id": rollback_intent_id,
                "work_plan_id": work_plan.id,
                "baseline_digest": image_digest,
                "argo_application": PROTECTED_ARGO_APPLICATION,
            }),
        })
        .await?;
    let content = json!({
        "rollback_intent_id": rollback_intent_id,
        "work_item_id": item.id,
        "status": "prepared",
        "baseline": {
            "image_ref": image_ref,
            "image_digest": image_digest,
            "deployment_ready": true,
            "running_image_ids_verified": true,
            "argo_revision": argo_revision,
            "gitops_revision": argo_revision,
        },
        "target": protected_target_json(),
        "rollback_owner": PROTECTED_ROLLBACK_OWNER,
        "approval_gate_id": gate.id,
        "manual_merge_required": true,
        "automatic_rollback": false,
        "reason": reason,
        "created_by": actor,
    });
    let artifact = append_rollback_intent_artifact(&state, &run, &content).await?;
    Ok(Json(rollback_intent_response(&artifact)))
}

async fn get_work_item_rollback_intent(
    State(state): State<AppState>,
    Path(work_item_id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    let item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    Ok(Json(
        latest_rollback_intent(&state, &item, None)
            .await?
            .unwrap_or_else(|| json!({ "status": "unavailable", "work_item_id": item.id })),
    ))
}

async fn approve_rollback_intent(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(rollback_intent_id): Path<String>,
    Json(request): Json<RollbackIntentRequest>,
) -> Result<Json<Value>, ApiError> {
    let reason = required_text(request.reason.clone(), "reason")?;
    let (item, current, run) = rollback_intent_context(&state, &rollback_intent_id).await?;
    let current_status = current.pointer("/content/status").and_then(Value::as_str);
    if current_status == Some("ready_for_argo_sync") {
        return approve_rollback_argo_sync(
            RollbackArgoApprovalContext {
                state: &state,
                rollback_intent_id: &rollback_intent_id,
                item: &item,
                current: &current,
                run: &run,
            },
            identity,
            request,
            reason,
        )
        .await;
    }
    if current_status != Some("prepared") {
        return Err(ApiError::conflict(
            "RollbackIntent must be prepared for its writer or ready for its explicit Argo approval",
        ));
    }
    let expires_at = bounded_production_grant_expiry(&item, request.expires_at)?;
    let gate_id = current
        .pointer("/content/approval_gate_id")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("RollbackIntent approval gate is unavailable"))?;
    let gate = state
        .store
        .get_approval_gate(gate_id)
        .await?
        .filter(|gate| gate.status == "pending")
        .ok_or_else(|| ApiError::conflict("RollbackIntent approval gate is not pending"))?;
    let baseline_digest_from_intent = current
        .pointer("/content/baseline/image_digest")
        .and_then(Value::as_str)
        .filter(|value| immutable_image_digest(value))
        .ok_or_else(|| ApiError::conflict("RollbackIntent baseline digest is invalid"))?;
    if gate.work_item_id.as_deref() != Some(item.id.as_str())
        || gate.gate_kind != "production_rollback"
        || gate
            .gate_json
            .get("rollback_intent_id")
            .and_then(Value::as_str)
            != Some(rollback_intent_id.as_str())
        || gate
            .gate_json
            .get("baseline_digest")
            .and_then(Value::as_str)
            != Some(baseline_digest_from_intent)
        || gate
            .gate_json
            .get("argo_application")
            .and_then(Value::as_str)
            != Some(PROTECTED_ARGO_APPLICATION)
    {
        return Err(ApiError::conflict(
            "RollbackIntent approval gate no longer matches its immutable target binding",
        ));
    }
    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    state
        .store
        .decide_approval_gate(gate_id, "satisfied", actor.clone(), Some(reason.clone()))
        .await?;
    let content = current
        .get("content")
        .cloned()
        .ok_or_else(|| ApiError::internal("RollbackIntent content is unavailable"))?;
    let mut content = content
        .as_object()
        .cloned()
        .ok_or_else(|| ApiError::internal("RollbackIntent content is malformed"))?;
    let baseline_digest = content
        .get("baseline")
        .and_then(|value| value.get("image_digest"))
        .and_then(Value::as_str)
        .filter(|value| immutable_image_digest(value))
        .ok_or_else(|| ApiError::conflict("RollbackIntent baseline digest is invalid"))?
        .to_string();
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&item.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent WorkPlan is unavailable"))?;
    let change_set = state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent ChangeSet is unavailable"))?;
    let pipeline_intent = state
        .store
        .get_pipeline_intent_by_change_set(&change_set.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent PipelineIntent is unavailable"))?;
    let source_merge_sha = pipeline_intent
        .intent_json
        .pointer("/source_provenance/merge_commit_sha")
        .and_then(Value::as_str)
        .filter(|value| is_git_sha(value))
        .ok_or_else(|| ApiError::conflict("rollback source merge provenance is unavailable"))?
        .to_string();
    let rollback_base_commit =
        observed_gitops_merge_for_deployment(&state.store, &item, &pipeline_intent)
            .await?
            .and_then(|artifact| artifact.content_json)
            .and_then(|content| {
                content
                    .get("merge_commit_sha")
                    .and_then(Value::as_str)
                    .map(str::to_string)
            })
            .filter(|value| is_git_sha(value))
            .ok_or_else(|| {
                ApiError::conflict(
                    "rollback writer authorization requires the observed deployment GitOps merge",
                )
            })?;
    let branch = format!(
        "pharness/rollback-{}",
        safe_id_fragment(&rollback_intent_id)
    );
    let permission_grant = create_permission_grant_record(
        &state.store,
        CreatePermissionGrantRequest {
            subject: DEFAULT_GITOPS_WRITER_SUBJECT.to_string(),
            created_by: actor.clone(),
            reason: format!("RollbackIntent {rollback_intent_id}: {reason}"),
            scope: json!({
                "environment": PROTECTED_ENVIRONMENT,
                "capability_kinds": ["git"],
                "actions": GITOPS_DELIVERY_ACTIONS,
                "max_risk": "critical",
                "repos": [PROTECTED_GITOPS_REPO],
                "branches": [branch],
                "work_item_ids": [item.id],
                "work_plan_ids": [work_plan.id],
                "change_set_ids": [change_set.id],
                "pipeline_intent_ids": [pipeline_intent.id],
                "pipeline_contract_ids": [item.pipeline_contract_id],
                "deployment_contract_ids": [item.deployment_contract_id],
                "source_merge_shas": [source_merge_sha],
                "gitops_merge_shas": [rollback_base_commit],
                "image_digests": [baseline_digest],
                "production_impacting": true,
            }),
            policy: json!({ "policy_mode": "supervised_autonomy" }),
            expires_at: expires_at.clone(),
        },
    )
    .await?;
    content.insert("status".to_string(), json!("approved"));
    content.insert("approved_by".to_string(), json!(actor));
    content.insert("approval_reason".to_string(), json!(reason));
    content.insert("authorization_expires_at".to_string(), json!(expires_at));
    content.insert(
        "permission_grant_id".to_string(),
        json!(permission_grant.id),
    );
    content.insert(
        "rollback_base_commit".to_string(),
        json!(rollback_base_commit),
    );
    let artifact = append_rollback_intent_artifact(&state, &run, &Value::Object(content)).await?;
    Ok(Json(rollback_intent_response(&artifact)))
}

struct RollbackArgoApprovalContext<'a> {
    state: &'a AppState,
    rollback_intent_id: &'a str,
    item: &'a StoredWorkItem,
    current: &'a Value,
    run: &'a pharness_store::StoredRun,
}

async fn approve_rollback_argo_sync(
    context: RollbackArgoApprovalContext<'_>,
    identity: Option<Extension<OperatorIdentity>>,
    request: RollbackIntentRequest,
    reason: String,
) -> Result<Json<Value>, ApiError> {
    let RollbackArgoApprovalContext {
        state,
        rollback_intent_id,
        item,
        current,
        run,
    } = context;
    if !stored_work_item_matches_protected_target(item) {
        return Err(ApiError::conflict(
            "rollback Argo approval is limited to the exact protected production target",
        ));
    }
    let expires_at = bounded_production_grant_expiry(item, request.expires_at)?;
    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    let content = current
        .get("content")
        .and_then(Value::as_object)
        .cloned()
        .ok_or_else(|| ApiError::conflict("RollbackIntent content is unavailable"))?;
    let baseline_digest = content
        .get("baseline")
        .and_then(|value| value.get("image_digest"))
        .and_then(Value::as_str)
        .filter(|value| immutable_image_digest(value))
        .ok_or_else(|| ApiError::conflict("RollbackIntent baseline digest is invalid"))?
        .to_string();
    let gitops_merge_sha = content
        .get("gitops_merge_sha")
        .and_then(Value::as_str)
        .filter(|value| is_git_sha(value))
        .ok_or_else(|| ApiError::conflict("rollback GitOps merge provenance is unavailable"))?
        .to_string();
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&item.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent WorkPlan is unavailable"))?;
    let change_set = state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent ChangeSet is unavailable"))?;
    let pipeline_intent = state
        .store
        .get_pipeline_intent_by_change_set(&change_set.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent PipelineIntent is unavailable"))?;
    let source_merge_sha = pipeline_intent
        .intent_json
        .pointer("/source_provenance/merge_commit_sha")
        .and_then(Value::as_str)
        .filter(|value| is_git_sha(value))
        .ok_or_else(|| {
            ApiError::conflict("rollback authorization requires source merge provenance")
        })?
        .to_string();

    let mut gate_ids = Vec::new();
    for (order, gate_kind) in [
        (91, "production_rollback_deployment"),
        (92, "cluster_mutation"),
        (93, "production_impact"),
    ] {
        let gate = state
            .store
            .create_approval_gate(CreateApprovalGate {
                id: format!("agate_{}_rollback_argo", unique_suffix()),
                work_item_id: Some(item.id.clone()),
                remediation_plan_id: None,
                incident_id: None,
                session_id: run.session_id.clone(),
                run_id: Some(run.id.clone()),
                status: "pending".to_string(),
                gate_kind: gate_kind.to_string(),
                gate_order: order,
                title: format!("Approve {gate_kind} for {}", item.title),
                summary: format!(
                    "Sync {PROTECTED_ARGO_APPLICATION} only to rollback merge {gitops_merge_sha} and restore {baseline_digest}"
                ),
                risk_level: "critical".to_string(),
                resource_namespace: Some(PROTECTED_NAMESPACE.to_string()),
                resource_kind: Some("Application".to_string()),
                resource_name: Some(PROTECTED_ARGO_APPLICATION.to_string()),
                gate_json: json!({
                    "rollback_intent_id": rollback_intent_id,
                    "work_plan_id": work_plan.id,
                    "gitops_merge_sha": gitops_merge_sha,
                    "baseline_digest": baseline_digest,
                    "argo_application": PROTECTED_ARGO_APPLICATION,
                    "scope": {
                        "work_item_id": item.id,
                        "work_plan_id": work_plan.id,
                        "environment": PROTECTED_ENVIRONMENT,
                        "production_impacting": true,
                        "source_repository": item.source_repo,
                        "source_ref": item.source_ref,
                        "gitops_repository": item.gitops_repo,
                        "gitops_ref": item.gitops_ref,
                        "target_namespace": PROTECTED_NAMESPACE,
                        "argo_application": PROTECTED_ARGO_APPLICATION,
                        "actions": ARGO_SYNC_ACTIONS,
                    },
                }),
            })
            .await?;
        state
            .store
            .decide_approval_gate(&gate.id, "satisfied", actor.clone(), Some(reason.clone()))
            .await?;
        gate_ids.push(gate.id);
    }
    let grant = create_permission_grant_record(
        &state.store,
        CreatePermissionGrantRequest {
            subject: DEFAULT_ARGO_RUNNER_SUBJECT.to_string(),
            created_by: actor.clone(),
            reason: format!("RollbackIntent {rollback_intent_id} Argo sync: {reason}"),
            scope: json!({
                "environment": PROTECTED_ENVIRONMENT,
                "capability_kinds": ["argo_sync"],
                "actions": ARGO_SYNC_ACTIONS,
                "max_risk": "critical",
                "namespaces": [PROTECTED_NAMESPACE],
                "work_item_ids": [item.id],
                "work_plan_ids": [work_plan.id],
                "change_set_ids": [change_set.id],
                "pipeline_intent_ids": [pipeline_intent.id],
                "deployment_intent_ids": [rollback_intent_id],
                "argo_applications": [PROTECTED_ARGO_APPLICATION],
                "pipeline_contract_ids": [item.pipeline_contract_id],
                "deployment_contract_ids": [item.deployment_contract_id],
                "source_merge_shas": [source_merge_sha],
                "gitops_merge_shas": [gitops_merge_sha],
                "image_digests": [baseline_digest],
                "production_impacting": true,
            }),
            policy: json!({ "policy_mode": "supervised_autonomy" }),
            expires_at: expires_at.clone(),
        },
    )
    .await?;
    let mut updated = content;
    updated.insert("status".to_string(), json!("argo_approved"));
    updated.insert("argo_approved_by".to_string(), json!(actor));
    updated.insert("argo_approval_reason".to_string(), json!(reason));
    updated.insert(
        "argo_authorization_expires_at".to_string(),
        json!(expires_at),
    );
    updated.insert("argo_permission_grant_id".to_string(), json!(grant.id));
    updated.insert("argo_approval_gate_ids".to_string(), json!(gate_ids));
    let artifact = append_rollback_intent_artifact(state, run, &Value::Object(updated)).await?;
    Ok(Json(rollback_intent_response(&artifact)))
}

async fn preflight_rollback_intent(
    State(state): State<AppState>,
    Path(rollback_intent_id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    let (item, current, _run) = rollback_intent_context(&state, &rollback_intent_id).await?;
    let status = current.pointer("/content/status").and_then(Value::as_str);
    let argo_phase = status == Some("argo_approved");
    let expires_at = current
        .pointer(if argo_phase {
            "/content/argo_authorization_expires_at"
        } else {
            "/content/authorization_expires_at"
        })
        .and_then(Value::as_str)
        .and_then(|value| value.parse::<u128>().ok());
    let authorization_fresh = expires_at.is_some_and(|value| value > current_millis());
    let permission_grant_id = current
        .pointer(if argo_phase {
            "/content/argo_permission_grant_id"
        } else {
            "/content/permission_grant_id"
        })
        .and_then(Value::as_str);
    let grant_fresh = match permission_grant_id {
        Some(grant_id) => state
            .store
            .get_permission_grant(grant_id)
            .await?
            .is_some_and(|grant| {
                grant.status == "active" && grant_is_unexpired(&grant, current_millis())
            }),
        None => false,
    };
    let exact_binding = if argo_phase {
        match current.get("content").and_then(Value::as_object) {
            Some(content) => {
                validate_rollback_argo_grant(&state, &item, &rollback_intent_id, content)
                    .await
                    .is_ok()
            }
            None => false,
        }
    } else {
        true
    };
    let ready = matches!(status, Some("approved" | "argo_approved"))
        && authorization_fresh
        && grant_fresh
        && exact_binding;
    Ok(Json(json!({
        "rollback_intent_id": rollback_intent_id,
        "status": if ready { if argo_phase { "ready_for_argo" } else { "ready_for_writer" } } else { "blocked" },
        "ready": ready,
        "authorization_fresh": authorization_fresh,
        "grant_fresh": grant_fresh,
        "writer_grant_fresh": !argo_phase && grant_fresh,
        "argo_grant_fresh": argo_phase && grant_fresh,
        "exact_binding": exact_binding,
        "manual_merge_required": true,
        "automatic_rollback": false,
        "content": current.get("content"),
    })))
}

async fn execute_rollback_intent(
    State(state): State<AppState>,
    Path(rollback_intent_id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    let Json(preflight) =
        preflight_rollback_intent(State(state.clone()), Path(rollback_intent_id.clone())).await?;
    if preflight.get("ready").and_then(Value::as_bool) != Some(true) {
        return Err(ApiError::conflict(
            "RollbackIntent is not ready for its next isolated executor",
        ));
    }
    if preflight.get("status").and_then(Value::as_str) == Some("ready_for_argo") {
        return dispatch_rollback_argo_sync(&state, &rollback_intent_id).await;
    }
    let (item, current, run) = rollback_intent_context(&state, &rollback_intent_id).await?;
    require_fresh_capability(&state, "gitops_writer").await?;
    let settings = state
        .worker
        .gitops_writer_settings()
        .ok_or_else(|| ApiError::conflict("GitOps rollback writer is not configured"))?;
    if !settings
        .allowed_repos
        .iter()
        .any(|repo| repo == PROTECTED_GITOPS_REPO)
    {
        return Err(ApiError::conflict(
            "protected GitOps repository is not allowlisted for the rollback writer",
        ));
    }
    let content = current
        .get("content")
        .and_then(Value::as_object)
        .ok_or_else(|| ApiError::conflict("RollbackIntent content is unavailable"))?;
    let baseline_digest = content
        .get("baseline")
        .and_then(|value| value.get("image_digest"))
        .and_then(Value::as_str)
        .filter(|value| immutable_image_digest(value))
        .ok_or_else(|| ApiError::conflict("RollbackIntent baseline digest is invalid"))?;
    let base_commit = content
        .get("rollback_base_commit")
        .and_then(Value::as_str)
        .filter(|value| is_git_sha(value))
        .ok_or_else(|| ApiError::conflict("RollbackIntent writer base revision is invalid"))?;
    let permission_grant_id = content
        .get("permission_grant_id")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("RollbackIntent has no short-lived writer grant"))?;
    let permission_grant = state
        .store
        .get_permission_grant(permission_grant_id)
        .await?
        .filter(|grant| grant.status == "active" && grant_is_unexpired(grant, current_millis()))
        .ok_or_else(|| ApiError::conflict("RollbackIntent writer grant is expired or revoked"))?;
    let grant_scope =
        serde_json::from_value::<PermissionGrantScope>(permission_grant.scope_json)
            .map_err(|_| ApiError::conflict("RollbackIntent writer grant scope is malformed"))?;
    let expected_branch = format!(
        "pharness/rollback-{}",
        safe_id_fragment(&rollback_intent_id)
    );
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&item.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent WorkPlan is unavailable"))?;
    let change_set = state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent ChangeSet is unavailable"))?;
    let pipeline_intent = state
        .store
        .get_pipeline_intent_by_change_set(&change_set.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent PipelineIntent is unavailable"))?;
    let source_merge_sha = pipeline_intent
        .intent_json
        .pointer("/source_provenance/merge_commit_sha")
        .and_then(Value::as_str)
        .filter(|value| is_git_sha(value))
        .ok_or_else(|| ApiError::conflict("rollback source merge provenance is unavailable"))?;
    if permission_grant.subject != DEFAULT_GITOPS_WRITER_SUBJECT
        || grant_scope.environment.as_deref() != Some(PROTECTED_ENVIRONMENT)
        || grant_scope.capability_kinds != vec![CapabilityKind::Git]
        || grant_scope.repos != vec![PROTECTED_GITOPS_REPO.to_string()]
        || grant_scope.branches != vec![expected_branch.clone()]
        || grant_scope.work_item_ids != vec![item.id.clone()]
        || grant_scope.work_plan_ids != vec![work_plan.id]
        || grant_scope.change_set_ids != vec![change_set.id]
        || grant_scope.pipeline_intent_ids != vec![pipeline_intent.id]
        || grant_scope.pipeline_contract_ids
            != vec![item.pipeline_contract_id.clone().unwrap_or_default()]
        || grant_scope.deployment_contract_ids
            != vec![item.deployment_contract_id.clone().unwrap_or_default()]
        || grant_scope.source_merge_shas != vec![source_merge_sha.to_string()]
        || grant_scope.gitops_merge_shas != vec![base_commit.to_string()]
        || grant_scope.image_digests != vec![baseline_digest.to_string()]
        || grant_scope.production_impacting != Some(true)
        || !GITOPS_DELIVERY_ACTIONS
            .iter()
            .all(|action| grant_scope.actions.iter().any(|allowed| allowed == action))
    {
        return Err(ApiError::conflict(
            "RollbackIntent writer grant no longer matches the exact WorkItem, contracts, digest, repository, and branch",
        ));
    }
    let artifacts = state.store.list_artifacts(&run.id).await?;
    if let Some(existing) = artifacts.iter().find(|artifact| {
        artifact.kind == "rollback_delivery_execution"
            && artifact.content_json.as_ref().is_some_and(|value| {
                value.get("rollback_intent_id").and_then(Value::as_str)
                    == Some(rollback_intent_id.as_str())
            })
    }) {
        let execution_id = existing
            .content_json
            .as_ref()
            .and_then(|value| value.get("execution_id"))
            .and_then(Value::as_str);
        let status = execution_id
            .and_then(|id| {
                artifacts.iter().find_map(|artifact| {
                    (artifact.kind == "rollback_delivery_result")
                        .then_some(artifact.content_json.as_ref())
                        .flatten()
                        .filter(|value| {
                            value.get("execution_id").and_then(Value::as_str) == Some(id)
                        })
                        .and_then(|value| value.get("status").and_then(Value::as_str))
                })
            })
            .unwrap_or("dispatched");
        return Ok(Json(json!({
            "rollback_intent_id": rollback_intent_id,
            "status": status,
            "execution": ArtifactResponse::from(existing.clone()),
            "created": false,
            "manual_merge_required": true,
            "automatic_rollback": false,
        })));
    }
    let execution_id = format!("rbexec_{}", unique_suffix());
    let context = json!({
        "execution_id": execution_id,
        "repository": PROTECTED_GITOPS_REPO,
        "base_ref": item.gitops_ref.as_deref().unwrap_or("main"),
        "base_commit": base_commit,
        "head_branch": expected_branch,
        "kustomization_path": PROTECTED_KUSTOMIZATION_PATH,
        "image_name": PROTECTED_IMAGE_NAME,
        "image_ref": format!("{PROTECTED_IMAGE_NAME}@{baseline_digest}"),
        "commit_subject": format!("rollback(yfinance-wrapper): restore {}", &baseline_digest[..19]),
        "commit_body": format!("Restore the captured known-good digest for RollbackIntent {rollback_intent_id}.\n\nManual merge and explicit Argo approval remain required."),
        "pull_request_title": format!("Rollback yfinance-wrapper to {}", &baseline_digest[..19]),
        "pull_request_body": format!("Restore only the captured known-good image digest.\n\nPHarness RollbackIntent: {rollback_intent_id}\nWorkItem: {}\nRollback owner: {PROTECTED_ROLLBACK_OWNER}", item.id),
        "github_api_url": settings.github_api_url,
        "author_name": settings.author_name,
        "author_email": settings.author_email,
    });
    let execution = state
        .store
        .create_artifact(CreateArtifact {
            id: format!("art_{}_rollback_delivery_execution", unique_suffix()),
            session_id: run.session_id.clone(),
            run_id: Some(run.id.clone()),
            kind: "rollback_delivery_execution".to_string(),
            label: format!("Rollback GitOps delivery for {rollback_intent_id}"),
            mime_type: Some("application/json".to_string()),
            path: None,
            content_text: None,
            content_json: Some(json!({
                "rollback_intent_id": rollback_intent_id,
                "execution_id": execution_id,
                "status": "dispatched",
                "context": context,
            })),
        })
        .await?;
    match state
        .worker
        .dispatch_gitops_delivery(GitOpsDeliveryExecutionRequest {
            gitops_change_set_id: rollback_intent_id.clone(),
            execution_id: execution_id.clone(),
        })
        .await
    {
        Ok(receipt) => Ok(Json(json!({
            "rollback_intent_id": rollback_intent_id,
            "status": "dispatched",
            "execution": ArtifactResponse::from(execution),
            "job_name": receipt.job_name,
            "created": true,
            "manual_merge_required": true,
            "automatic_rollback": false,
        }))),
        Err(error) => {
            tracing::warn!(rollback_intent_id = %rollback_intent_id, %error, "rollback writer dispatch failed");
            let failure = append_rollback_delivery_result(
                &state,
                &run,
                &rollback_intent_id,
                &execution_id,
                "dispatch_failed",
                json!({ "error_code": "job_dispatch_failed" }),
            )
            .await?;
            let mut updated = content.clone();
            updated.insert("status".to_string(), json!("attention_required"));
            updated.insert("writer_failure_result_id".to_string(), json!(failure.id));
            append_rollback_intent_artifact(&state, &run, &Value::Object(updated)).await?;
            Ok(Json(json!({
                "rollback_intent_id": rollback_intent_id,
                "status": "dispatch_failed",
                "execution": ArtifactResponse::from(failure),
                "created": true,
                "manual_merge_required": true,
                "automatic_rollback": false,
            })))
        }
    }
}

async fn dispatch_rollback_argo_sync(
    state: &AppState,
    rollback_intent_id: &str,
) -> Result<Json<Value>, ApiError> {
    let (item, current, run) = rollback_intent_context(state, rollback_intent_id).await?;
    let content = current
        .get("content")
        .and_then(Value::as_object)
        .ok_or_else(|| ApiError::conflict("RollbackIntent content is unavailable"))?;
    validate_rollback_argo_grant(state, &item, rollback_intent_id, content).await?;
    if !state.worker.argo_executor_available()
        || !state
            .worker
            .argo_executor_allows_application(PROTECTED_ARGO_APPLICATION)
    {
        return Err(ApiError::conflict(
            "the isolated Argo executor is unavailable for the protected Application",
        ));
    }
    let artifacts = state.store.list_artifacts(&run.id).await?;
    if let Some(existing) = artifacts
        .iter()
        .filter(|artifact| artifact.kind == "rollback_argo_sync_execution")
        .filter(|artifact| {
            artifact.content_json.as_ref().is_some_and(|value| {
                value.get("rollback_intent_id").and_then(Value::as_str) == Some(rollback_intent_id)
            })
        })
        .max_by_key(|artifact| (&artifact.created_at, &artifact.id))
    {
        return Ok(Json(json!({
            "rollback_intent_id": rollback_intent_id,
            "status": "argo_syncing",
            "execution": ArtifactResponse::from(existing.clone()),
            "created": false,
            "automatic_rollback": false,
        })));
    }
    let execution_id = format!("rbaexec_{}", unique_suffix());
    let execution = state
        .store
        .create_artifact(CreateArtifact {
            id: format!("art_{}_rollback_argo_sync_execution", unique_suffix()),
            session_id: run.session_id.clone(),
            run_id: Some(run.id.clone()),
            kind: "rollback_argo_sync_execution".to_string(),
            label: format!("Rollback Argo sync for {rollback_intent_id}"),
            mime_type: Some("application/json".to_string()),
            path: None,
            content_text: None,
            content_json: Some(json!({
                "rollback_intent_id": rollback_intent_id,
                "execution_id": execution_id,
                "status": "dispatched",
                "permission_grant_id": content.get("argo_permission_grant_id"),
                "deployment_contract_id": item.deployment_contract_id,
                "gitops_merge_sha": content.get("gitops_merge_sha"),
                "baseline_digest": content.get("baseline").and_then(|value| value.get("image_digest")),
                "target": protected_target_json(),
            })),
        })
        .await?;
    match state
        .worker
        .dispatch_argo_sync_execution(ArgoSyncExecutionRequest {
            deployment_intent_id: rollback_intent_id.to_string(),
            execution_id: execution_id.clone(),
        })
        .await
    {
        Ok(receipt) => {
            let mut updated = content.clone();
            updated.insert("status".to_string(), json!("argo_syncing"));
            updated.insert("argo_execution_id".to_string(), json!(execution_id));
            append_rollback_intent_artifact(state, &run, &Value::Object(updated)).await?;
            Ok(Json(json!({
                "rollback_intent_id": rollback_intent_id,
                "status": "argo_syncing",
                "execution": ArtifactResponse::from(execution),
                "job_name": receipt.job_name,
                "created": true,
                "automatic_rollback": false,
            })))
        }
        Err(error) => {
            tracing::warn!(rollback_intent_id, %error, "rollback Argo executor dispatch failed");
            let result = append_rollback_argo_sync_result(
                state,
                &run,
                rollback_intent_id,
                &execution_id,
                "dispatch_failed",
                json!({ "error_code": "job_dispatch_failed" }),
            )
            .await?;
            let mut updated = content.clone();
            updated.insert("status".to_string(), json!("attention_required"));
            updated.insert("argo_failure_result_id".to_string(), json!(result.id));
            append_rollback_intent_artifact(state, &run, &Value::Object(updated)).await?;
            Ok(Json(json!({
                "rollback_intent_id": rollback_intent_id,
                "status": "dispatch_failed",
                "execution": ArtifactResponse::from(result),
                "created": true,
                "automatic_rollback": false,
            })))
        }
    }
}

async fn validate_rollback_argo_grant(
    state: &AppState,
    item: &StoredWorkItem,
    rollback_intent_id: &str,
    content: &serde_json::Map<String, Value>,
) -> Result<StoredPermissionGrant, ApiError> {
    let grant_id = content
        .get("argo_permission_grant_id")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("RollbackIntent has no Argo permission grant"))?;
    let grant = state
        .store
        .get_permission_grant(grant_id)
        .await?
        .filter(|grant| grant.status == "active" && grant_is_unexpired(grant, current_millis()))
        .ok_or_else(|| {
            ApiError::conflict("rollback Argo permission grant is expired or revoked")
        })?;
    let scope = serde_json::from_value::<PermissionGrantScope>(grant.scope_json.clone())
        .map_err(|_| ApiError::conflict("rollback Argo permission grant scope is malformed"))?;
    let baseline_digest = content
        .get("baseline")
        .and_then(|value| value.get("image_digest"))
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("RollbackIntent baseline digest is unavailable"))?;
    let gitops_merge_sha = content
        .get("gitops_merge_sha")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("rollback GitOps merge SHA is unavailable"))?;
    let expected_pipeline_contracts = item
        .pipeline_contract_id
        .iter()
        .cloned()
        .collect::<Vec<_>>();
    let expected_deployment_contracts = item
        .deployment_contract_id
        .iter()
        .cloned()
        .collect::<Vec<_>>();
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&item.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent WorkPlan is unavailable"))?;
    let change_set = state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent ChangeSet is unavailable"))?;
    let pipeline_intent = state
        .store
        .get_pipeline_intent_by_change_set(&change_set.id)
        .await?
        .ok_or_else(|| ApiError::conflict("RollbackIntent PipelineIntent is unavailable"))?;
    let source_merge_sha = pipeline_intent
        .intent_json
        .pointer("/source_provenance/merge_commit_sha")
        .and_then(Value::as_str)
        .filter(|value| is_git_sha(value))
        .ok_or_else(|| ApiError::conflict("rollback source merge provenance is unavailable"))?;
    if grant.subject != DEFAULT_ARGO_RUNNER_SUBJECT
        || scope.environment.as_deref() != Some(PROTECTED_ENVIRONMENT)
        || scope.capability_kinds != vec![CapabilityKind::ArgoSync]
        || !ARGO_SYNC_ACTIONS
            .iter()
            .all(|action| scope.actions.iter().any(|allowed| allowed == action))
        || scope.namespaces != vec![PROTECTED_NAMESPACE.to_string()]
        || scope.work_item_ids != vec![item.id.clone()]
        || scope.work_plan_ids != vec![work_plan.id.clone()]
        || scope.change_set_ids != vec![change_set.id.clone()]
        || scope.pipeline_intent_ids != vec![pipeline_intent.id.clone()]
        || scope.deployment_intent_ids != vec![rollback_intent_id.to_string()]
        || scope.argo_applications != vec![PROTECTED_ARGO_APPLICATION.to_string()]
        || scope.pipeline_contract_ids != expected_pipeline_contracts
        || scope.deployment_contract_ids != expected_deployment_contracts
        || scope.source_merge_shas != vec![source_merge_sha.to_string()]
        || scope.gitops_merge_shas != vec![gitops_merge_sha.to_string()]
        || scope.image_digests != vec![baseline_digest.to_string()]
        || scope.production_impacting != Some(true)
    {
        return Err(ApiError::conflict(
            "rollback Argo grant no longer matches the exact WorkItem, contracts, merge, digest, namespace, and Application",
        ));
    }
    let expected_gate_kinds = [
        "production_rollback_deployment",
        "cluster_mutation",
        "production_impact",
    ];
    let gate_ids = content
        .get("argo_approval_gate_ids")
        .and_then(Value::as_array)
        .ok_or_else(|| ApiError::conflict("rollback Argo approval gates are unavailable"))?;
    if gate_ids.len() != expected_gate_kinds.len() {
        return Err(ApiError::conflict(
            "rollback Argo approval gate set is incomplete",
        ));
    }
    for (gate_id, expected_kind) in gate_ids.iter().zip(expected_gate_kinds) {
        let gate_id = gate_id
            .as_str()
            .ok_or_else(|| ApiError::conflict("rollback Argo approval gate ID is malformed"))?;
        let gate = state
            .store
            .get_approval_gate(gate_id)
            .await?
            .filter(|gate| gate.status == "satisfied")
            .ok_or_else(|| ApiError::conflict("rollback Argo approval gate is not satisfied"))?;
        let gate_scope = gate
            .gate_json
            .get("scope")
            .and_then(Value::as_object)
            .ok_or_else(|| {
                ApiError::conflict("rollback Argo approval gate scope is unavailable")
            })?;
        if gate.work_item_id.as_deref() != Some(item.id.as_str())
            || gate.gate_kind != expected_kind
            || gate_scope.get("work_item_id").and_then(Value::as_str) != Some(item.id.as_str())
            || gate_scope.get("work_plan_id").and_then(Value::as_str) != Some(work_plan.id.as_str())
            || gate_scope.get("environment").and_then(Value::as_str) != Some(PROTECTED_ENVIRONMENT)
            || gate_scope
                .get("production_impacting")
                .and_then(Value::as_bool)
                != Some(true)
            || gate_scope.get("target_namespace").and_then(Value::as_str)
                != Some(PROTECTED_NAMESPACE)
            || gate_scope.get("argo_application").and_then(Value::as_str)
                != Some(PROTECTED_ARGO_APPLICATION)
            || gate
                .gate_json
                .get("gitops_merge_sha")
                .and_then(Value::as_str)
                != Some(gitops_merge_sha)
            || gate
                .gate_json
                .get("baseline_digest")
                .and_then(Value::as_str)
                != Some(baseline_digest)
        {
            return Err(ApiError::conflict(
                "rollback Argo approval gate no longer matches its immutable target binding",
            ));
        }
    }
    Ok(grant)
}

async fn append_rollback_argo_sync_result(
    state: &AppState,
    run: &pharness_store::StoredRun,
    rollback_intent_id: &str,
    execution_id: &str,
    status: &str,
    details: Value,
) -> Result<StoredArtifact, ApiError> {
    if let Some(existing) =
        state
            .store
            .list_artifacts(&run.id)
            .await?
            .into_iter()
            .find(|artifact| {
                artifact.kind == "rollback_argo_sync_result"
                    && artifact.content_json.as_ref().is_some_and(|content| {
                        content.get("rollback_intent_id").and_then(Value::as_str)
                            == Some(rollback_intent_id)
                            && content.get("execution_id").and_then(Value::as_str)
                                == Some(execution_id)
                            && content.get("status").and_then(Value::as_str) == Some(status)
                    })
            })
    {
        return Ok(existing);
    }
    Ok(state
        .store
        .create_artifact(CreateArtifact {
            id: format!("art_{}_rollback_argo_sync_result", unique_suffix()),
            session_id: run.session_id.clone(),
            run_id: Some(run.id.clone()),
            kind: "rollback_argo_sync_result".to_string(),
            label: format!("Rollback Argo sync {status} for {rollback_intent_id}"),
            mime_type: Some("application/json".to_string()),
            path: None,
            content_text: None,
            content_json: Some(json!({
                "rollback_intent_id": rollback_intent_id,
                "execution_id": execution_id,
                "status": status,
                "details": details,
            })),
        })
        .await?)
}

async fn observe_rollback_intent(
    State(state): State<AppState>,
    Path(rollback_intent_id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    let (_item, current, run) = rollback_intent_context(&state, &rollback_intent_id).await?;
    if current.pointer("/content/status").and_then(Value::as_str) == Some("argo_syncing") {
        return observe_rollback_argo_sync(&state, &rollback_intent_id, &current, &run).await;
    }
    require_fresh_capability(&state, "gitops_observer").await?;
    let settings = state
        .worker
        .gitops_observer_settings()
        .ok_or_else(|| ApiError::conflict("GitOps rollback observer is not configured"))?;
    if !settings
        .allowed_repos
        .iter()
        .any(|repo| repo == PROTECTED_GITOPS_REPO)
    {
        return Err(ApiError::conflict(
            "protected GitOps repository is not allowlisted for the rollback observer",
        ));
    }
    let artifacts = state.store.list_artifacts(&run.id).await?;
    let result = artifacts
        .iter()
        .filter(|artifact| artifact.kind == "rollback_delivery_result")
        .filter(|artifact| {
            artifact.content_json.as_ref().is_some_and(|value| {
                value.get("rollback_intent_id").and_then(Value::as_str)
                    == Some(rollback_intent_id.as_str())
                    && value.get("status").and_then(Value::as_str) == Some("completed")
            })
        })
        .max_by_key(|artifact| (&artifact.created_at, &artifact.id))
        .ok_or_else(|| {
            ApiError::conflict(
                "rollback observation requires a completed GitOps pull-request delivery",
            )
        })?;
    let details = result
        .content_json
        .as_ref()
        .and_then(|value| value.get("details"))
        .and_then(Value::as_object)
        .ok_or_else(|| {
            ApiError::conflict("rollback delivery result has no pull-request provenance")
        })?;
    let source_commit_sha =
        required_json_string(details, "commit_sha", "rollback delivery result")?;
    let pull_request_url =
        required_json_string(details, "pull_request_url", "rollback delivery result")?;
    let pull_request_number = details
        .get("pull_request_number")
        .and_then(Value::as_u64)
        .ok_or_else(|| ApiError::conflict("rollback delivery result has no pull-request number"))?;
    let head_branch = required_json_string(details, "branch", "rollback delivery result")?;
    if !is_git_sha(&source_commit_sha) || !is_github_pr_url(&pull_request_url) {
        return Err(ApiError::conflict(
            "rollback delivery result has invalid immutable GitHub provenance",
        ));
    }
    if let Some(merged) = artifacts
        .iter()
        .filter(|artifact| artifact.kind == "rollback_delivery_observation")
        .filter(|artifact| {
            artifact.content_json.as_ref().is_some_and(|value| {
                value.get("rollback_intent_id").and_then(Value::as_str)
                    == Some(rollback_intent_id.as_str())
                    && value.get("merged").and_then(Value::as_bool) == Some(true)
            })
        })
        .max_by_key(|artifact| (&artifact.created_at, &artifact.id))
    {
        return Ok(Json(
            json!({ "rollback_intent_id": rollback_intent_id, "status": "merged", "observation": ArtifactResponse::from(merged.clone()), "created": false, "manual_merge_required": true }),
        ));
    }
    let observation_index = artifacts
        .iter()
        .filter(|artifact| {
            artifact.kind == "rollback_delivery_observation_execution"
                && artifact.content_json.as_ref().is_some_and(|value| {
                    value.get("rollback_intent_id").and_then(Value::as_str)
                        == Some(rollback_intent_id.as_str())
                })
        })
        .count();
    let execution_id = format!("rbobs_{}", unique_suffix());
    let execution = state.store.create_artifact(CreateArtifact {
        id: format!("art_{}_rollback_delivery_observation", unique_suffix()),
        session_id: run.session_id.clone(), run_id: Some(run.id.clone()),
        kind: "rollback_delivery_observation_execution".to_string(),
        label: format!("Rollback PR observation {} for {}", observation_index + 1, rollback_intent_id),
        mime_type: Some("application/json".to_string()), path: None, content_text: None,
        content_json: Some(json!({ "rollback_intent_id": rollback_intent_id, "execution_id": execution_id, "status": "dispatched", "source": { "repository": PROTECTED_GITOPS_REPO, "head_branch": head_branch, "source_commit_sha": source_commit_sha, "pull_request_url": pull_request_url, "pull_request_number": pull_request_number, "github_api_url": settings.github_api_url } })),
    }).await?;
    match state
        .worker
        .dispatch_gitops_delivery_observation(GitOpsDeliveryObservationRequest {
            gitops_change_set_id: rollback_intent_id.clone(),
            execution_id: execution_id.clone(),
        })
        .await
    {
        Ok(receipt) => Ok(Json(
            json!({ "rollback_intent_id": rollback_intent_id, "status": "observation_dispatched", "execution": ArtifactResponse::from(execution), "job_name": receipt.job_name, "created": true, "manual_merge_required": true }),
        )),
        Err(error) => {
            tracing::warn!(rollback_intent_id = %rollback_intent_id, %error, "rollback observer dispatch failed");
            let failure = append_rollback_delivery_observation(
                &state,
                &run,
                &rollback_intent_id,
                &execution_id,
                "failed",
                json!({ "error_code": "job_dispatch_failed" }),
            )
            .await?;
            Ok(Json(
                json!({ "rollback_intent_id": rollback_intent_id, "status": "dispatch_failed", "observation": ArtifactResponse::from(failure), "created": true, "manual_merge_required": true }),
            ))
        }
    }
}

async fn observe_rollback_argo_sync(
    state: &AppState,
    rollback_intent_id: &str,
    current: &Value,
    run: &pharness_store::StoredRun,
) -> Result<Json<Value>, ApiError> {
    let content = current
        .get("content")
        .and_then(Value::as_object)
        .ok_or_else(|| ApiError::conflict("RollbackIntent content is unavailable"))?;
    let execution_id = content
        .get("argo_execution_id")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("RollbackIntent has no Argo execution"))?;
    let expected_revision = content
        .get("gitops_merge_sha")
        .and_then(Value::as_str)
        .filter(|value| is_git_sha(value))
        .ok_or_else(|| ApiError::conflict("rollback GitOps merge SHA is unavailable"))?;
    let expected_digest = content
        .get("baseline")
        .and_then(|value| value.get("image_digest"))
        .and_then(Value::as_str)
        .filter(|value| immutable_image_digest(value))
        .ok_or_else(|| ApiError::conflict("RollbackIntent baseline digest is invalid"))?;
    let artifacts = state.store.list_artifacts(&run.id).await?;
    let completed = artifacts
        .iter()
        .filter(|artifact| artifact.kind == "rollback_argo_sync_result")
        .filter(|artifact| {
            artifact.content_json.as_ref().is_some_and(|value| {
                value.get("rollback_intent_id").and_then(Value::as_str) == Some(rollback_intent_id)
                    && value.get("execution_id").and_then(Value::as_str) == Some(execution_id)
                    && value.get("status").and_then(Value::as_str) == Some("completed")
            })
        })
        .max_by_key(|artifact| (&artifact.created_at, &artifact.id));
    if completed.is_none() {
        let terminal = artifacts.iter().find(|artifact| {
            artifact.kind == "rollback_argo_sync_result"
                && artifact.content_json.as_ref().is_some_and(|value| {
                    value.get("rollback_intent_id").and_then(Value::as_str)
                        == Some(rollback_intent_id)
                        && value.get("execution_id").and_then(Value::as_str) == Some(execution_id)
                        && matches!(
                            value.get("status").and_then(Value::as_str),
                            Some("failed" | "cancelled" | "dispatch_failed")
                        )
                })
        });
        return Ok(Json(json!({
            "rollback_intent_id": rollback_intent_id,
            "status": if terminal.is_some() { "attention_required" } else { "argo_syncing" },
            "ready": false,
            "automatic_rollback": false,
            "result": terminal.cloned().map(ArtifactResponse::from),
        })));
    }

    let (item, _, _) = rollback_intent_context(state, rollback_intent_id).await?;
    let contract_id = item
        .deployment_contract_id
        .as_deref()
        .ok_or_else(|| ApiError::conflict("RollbackIntent DeploymentContract is unavailable"))?;
    let contract = state
        .store
        .get_deployment_contract(contract_id)
        .await?
        .filter(|contract| contract.status == "active")
        .ok_or_else(|| ApiError::conflict("RollbackIntent DeploymentContract is not active"))?;
    let spec = deployment_contract_spec(&contract.contract_json)?;
    validate_protected_production_deployment_contract(&spec)?;
    if contract.target_environment != PROTECTED_ENVIRONMENT
        || contract.target_namespace != PROTECTED_NAMESPACE
        || contract.argo_application != PROTECTED_ARGO_APPLICATION
    {
        return Err(ApiError::conflict(
            "RollbackIntent DeploymentContract no longer matches the protected target",
        ));
    }

    let argo = execute_direct_capability(
        state,
        AgentAction::ArgoGetApp {
            id: ActionId::new(format!("act_{}_rollback_verify_argo", unique_suffix())),
            reason: format!("verify RollbackIntent {rollback_intent_id} Argo state"),
            app: PROTECTED_ARGO_APPLICATION.to_string(),
        },
        None,
    )
    .await?;
    let deployment = execute_direct_capability(
        state,
        AgentAction::KubernetesGet {
            id: ActionId::new(format!(
                "act_{}_rollback_verify_deployment",
                unique_suffix()
            )),
            reason: format!("verify RollbackIntent {rollback_intent_id} Deployment"),
            resource: "deployments".to_string(),
            namespace: Some(PROTECTED_NAMESPACE.to_string()),
            name: Some(PROTECTED_WORKLOAD_NAME.to_string()),
            all_namespaces: false,
            label_selector: None,
        },
        None,
    )
    .await?;
    let pods = execute_direct_capability(
        state,
        AgentAction::KubernetesGet {
            id: ActionId::new(format!("act_{}_rollback_verify_pods", unique_suffix())),
            reason: format!("verify RollbackIntent {rollback_intent_id} Pod imageIDs"),
            resource: "pods".to_string(),
            namespace: Some(PROTECTED_NAMESPACE.to_string()),
            name: None,
            all_namespaces: false,
            label_selector: Some("app=yfinance-wrapper".to_string()),
        },
        None,
    )
    .await?;
    let argo_content = argo
        .result
        .as_ref()
        .map(|result| &result.content)
        .ok_or_else(|| ApiError::conflict("rollback Argo verification did not execute"))?;
    let deployment_content = deployment
        .result
        .as_ref()
        .map(|result| &result.content)
        .ok_or_else(|| ApiError::conflict("rollback Deployment verification did not execute"))?;
    let pod_content = pods
        .result
        .as_ref()
        .map(|result| &result.content)
        .ok_or_else(|| ApiError::conflict("rollback Pod verification did not execute"))?;
    let argo_healthy = argo_content
        .pointer("/analysis/sync_status")
        .and_then(Value::as_str)
        == Some("Synced")
        && argo_content
            .pointer("/analysis/health_status")
            .and_then(Value::as_str)
            == Some("Healthy")
        && argo_content
            .pointer("/analysis/revision")
            .and_then(Value::as_str)
            == Some(expected_revision);
    let deployment_healthy = deployment_content
        .pointer("/analysis/status")
        .and_then(Value::as_str)
        == Some("healthy");
    let image_ids = pod_content
        .pointer("/output/items")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .flat_map(|pod| {
            pod.pointer("/status/containers")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
        })
        .filter_map(|container| container.get("imageID").and_then(Value::as_str))
        .collect::<Vec<_>>();
    let digest_healthy = !image_ids.is_empty()
        && image_ids
            .iter()
            .all(|image_id| image_id.ends_with(expected_digest));
    let healthz = state
        .worker
        .verify_capability("yfinance_healthz", None)
        .await;
    let healthz_healthy = healthz.as_ref().is_ok_and(|outcome| outcome.available);
    let (prometheus_observation, prometheus_check) =
        verify_required_prometheus_inventory(state, None).await?;
    let prometheus_healthy = prometheus_check
        .get("passed")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let verified = argo_healthy
        && deployment_healthy
        && digest_healthy
        && healthz_healthy
        && prometheus_healthy;
    let checks = vec![
        execution_check(
            "argo_application_synced_healthy_at_rollback_merge",
            argo_healthy,
            format!("{PROTECTED_ARGO_APPLICATION} checked at {expected_revision}"),
        ),
        execution_check(
            "declared_deployment_rollout_healthy",
            deployment_healthy,
            format!("{PROTECTED_NAMESPACE}/{PROTECTED_WORKLOAD_NAME} rollout checked"),
        ),
        execution_check(
            "running_image_digest",
            digest_healthy,
            format!(
                "{} running imageID(s) checked against {expected_digest}",
                image_ids.len()
            ),
        ),
        execution_check(
            "service_healthz",
            healthz_healthy,
            "Exact apps-prod/yfinance-wrapper Service /healthz checked",
        ),
        prometheus_check,
    ];
    let verification = state
        .store
        .create_artifact(CreateArtifact {
            id: format!("art_{}_rollback_verification", unique_suffix()),
            session_id: run.session_id.clone(),
            run_id: Some(run.id.clone()),
            kind: "rollback_verification".to_string(),
            label: format!("Rollback verification for {rollback_intent_id}"),
            mime_type: Some("application/json".to_string()),
            path: None,
            content_text: None,
            content_json: Some(json!({
                "rollback_intent_id": rollback_intent_id,
                "status": if verified { "verified" } else { "attention_required" },
                "gitops_merge_sha": expected_revision,
                "expected_digest": expected_digest,
                "argo_observation_id": argo.observation_id,
                "deployment_observation_id": deployment.observation_id,
                "pod_observation_id": pods.observation_id,
                "prometheus_observation_id": prometheus_observation.map(|observation| observation.id),
                "checks": checks,
            })),
        })
        .await?;
    let mut updated = content.clone();
    updated.insert(
        "status".to_string(),
        json!(if verified {
            "verified"
        } else {
            "attention_required"
        }),
    );
    updated.insert(
        "verification_artifact_id".to_string(),
        json!(verification.id),
    );
    append_rollback_intent_artifact(state, run, &Value::Object(updated)).await?;
    Ok(Json(json!({
        "rollback_intent_id": rollback_intent_id,
        "status": if verified { "verified" } else { "attention_required" },
        "verified": verified,
        "verification": ArtifactResponse::from(verification),
        "automatic_rollback": false,
    })))
}

async fn require_fresh_capability(state: &AppState, capability: &str) -> Result<(), ApiError> {
    let available = capability_statuses(state)
        .await?
        .into_iter()
        .any(|entry| entry.capability == capability && entry.status == "available");
    if available {
        Ok(())
    } else {
        Err(ApiError::conflict(format!(
            "{capability} requires a fresh passing isolated capability verification"
        )))
    }
}

async fn append_rollback_delivery_result(
    state: &AppState,
    run: &pharness_store::StoredRun,
    rollback_intent_id: &str,
    execution_id: &str,
    status: &str,
    details: Value,
) -> Result<StoredArtifact, ApiError> {
    Ok(state.store.create_artifact(CreateArtifact { id: format!("art_{}_rollback_delivery_result", unique_suffix()), session_id: run.session_id.clone(), run_id: Some(run.id.clone()), kind: "rollback_delivery_result".to_string(), label: format!("Rollback GitOps delivery {status} for {rollback_intent_id}"), mime_type: Some("application/json".to_string()), path: None, content_text: None, content_json: Some(json!({ "rollback_intent_id": rollback_intent_id, "execution_id": execution_id, "status": status, "details": details })) }).await?)
}

async fn append_rollback_delivery_observation(
    state: &AppState,
    run: &pharness_store::StoredRun,
    rollback_intent_id: &str,
    execution_id: &str,
    status: &str,
    details: Value,
) -> Result<StoredArtifact, ApiError> {
    Ok(state.store.create_artifact(CreateArtifact { id: format!("art_{}_rollback_delivery_observation", unique_suffix()), session_id: run.session_id.clone(), run_id: Some(run.id.clone()), kind: "rollback_delivery_observation".to_string(), label: format!("Rollback pull-request observation {status} for {rollback_intent_id}"), mime_type: Some("application/json".to_string()), path: None, content_text: None, content_json: Some(json!({ "rollback_intent_id": rollback_intent_id, "execution_id": execution_id, "status": status, "details": details, "pull_request_state": details.get("pull_request_state"), "merged": details.get("merged"), "merge_commit_sha": details.get("merge_commit_sha") })) }).await?)
}

async fn rollback_intent_context(
    state: &AppState,
    rollback_intent_id: &str,
) -> Result<(StoredWorkItem, Value, pharness_store::StoredRun), ApiError> {
    let items = state
        .store
        .list_work_items(WorkItemListFilter {
            limit: 200,
            ..Default::default()
        })
        .await?;
    for item in items {
        if let Some(current) =
            latest_rollback_intent(state, &item, Some(rollback_intent_id)).await?
        {
            let run_id = item.current_run_id.clone().ok_or_else(|| {
                ApiError::conflict("RollbackIntent run provenance is unavailable")
            })?;
            let run = state
                .store
                .get_run(&run_id)
                .await?
                .ok_or_else(|| ApiError::not_found("run", run_id.as_str()))?;
            return Ok((item, current, run));
        }
    }
    Err(ApiError::not_found("rollback_intent", rollback_intent_id))
}

async fn latest_rollback_intent(
    state: &AppState,
    item: &StoredWorkItem,
    rollback_intent_id: Option<&str>,
) -> Result<Option<Value>, ApiError> {
    let Some(run_id) = item.current_run_id.as_ref() else {
        return Ok(None);
    };
    let artifact = state
        .store
        .list_artifacts(run_id)
        .await?
        .into_iter()
        .filter(|artifact| artifact.kind == "rollback_intent")
        .filter(|artifact| {
            artifact
                .content_json
                .as_ref()
                .and_then(|content| content.get("work_item_id"))
                .and_then(Value::as_str)
                == Some(item.id.as_str())
        })
        .filter(|artifact| {
            rollback_intent_id.map_or(true, |id| {
                artifact
                    .content_json
                    .as_ref()
                    .and_then(|content| content.get("rollback_intent_id"))
                    .and_then(Value::as_str)
                    == Some(id)
            })
        })
        .max_by_key(|artifact| (artifact.created_at.clone(), artifact.id.clone()));
    Ok(artifact.as_ref().map(rollback_intent_response))
}

async fn append_rollback_intent_artifact(
    state: &AppState,
    run: &pharness_store::StoredRun,
    content: &Value,
) -> Result<StoredArtifact, ApiError> {
    Ok(state
        .store
        .create_artifact(CreateArtifact {
            id: format!("art_{}_rollback_intent", unique_suffix()),
            session_id: run.session_id.clone(),
            run_id: Some(run.id.clone()),
            kind: "rollback_intent".to_string(),
            label: format!(
                "RollbackIntent {}",
                content
                    .get("rollback_intent_id")
                    .and_then(Value::as_str)
                    .unwrap_or("unknown")
            ),
            mime_type: Some("application/json".to_string()),
            path: None,
            content_text: None,
            content_json: Some(content.clone()),
        })
        .await?)
}

fn rollback_intent_response(artifact: &StoredArtifact) -> Value {
    json!({
        "artifact_id": artifact.id,
        "created_at": artifact.created_at,
        "content": artifact.content_json,
    })
}

async fn reconcile_work_item(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
    Json(request): Json<ReconcileWorkItemRequest>,
) -> Result<Json<ReconcileWorkItemResponse>, ApiError> {
    let actor = identity
        .as_ref()
        .map(|Extension(OperatorIdentity(name))| name.clone())
        .or_else(|| clean_optional_text(request.actor.clone()));
    let reason = clean_optional_text(request.reason.clone());
    let work_item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&work_item_id)
        .await?;
    let change_set = match &work_plan {
        Some(work_plan) => {
            state
                .store
                .get_change_set_by_work_plan(&work_plan.id)
                .await?
        }
        None => None,
    };

    let git_delivery = git_delivery_flow(&state.store, change_set.as_ref()).await?;
    let pipeline_intent = match change_set.as_ref() {
        Some(change_set) => {
            state
                .store
                .get_pipeline_intent_by_change_set(&change_set.id)
                .await?
        }
        None => None,
    };
    let pipeline_execution_preflight = match pipeline_intent
        .as_ref()
        .filter(|intent| pipeline_intent_requires_execution_preflight(intent))
    {
        Some(intent) => Some(pipeline_intent_execution_preflight(&state, &intent.id).await?),
        None => None,
    };
    let deployment_intent = match pipeline_intent.as_ref() {
        Some(intent) => {
            state
                .store
                .get_deployment_intent_by_pipeline_intent(&intent.id)
                .await?
        }
        None => None,
    };
    let deployment_execution_preflight = match deployment_intent
        .as_ref()
        .filter(|intent| intent.status == "approved")
    {
        Some(intent) => Some(deployment_intent_execution_preflight(&state, &intent.id).await?),
        None => None,
    };
    let deployment_dispatch_ready = deployment_execution_preflight.as_ref().map(|preflight| {
        state.worker.argo_executor_available()
            && deployment_target(&preflight.intent)
                .ok()
                .is_some_and(|target| {
                    state
                        .worker
                        .argo_executor_allows_application(&target.application)
                })
    });
    let deployment_delivery =
        deployment_intent_delivery_flow(&state.store, deployment_intent.as_ref()).await?;
    let gitops_change_set = match pipeline_intent.as_ref() {
        Some(intent) => {
            state
                .store
                .get_gitops_change_set_by_pipeline_intent(&intent.id)
                .await?
        }
        None => None,
    };
    let gitops_delivery = gitops_delivery_flow(&state.store, gitops_change_set.as_ref()).await?;
    let gitops_base_revision = match gitops_change_set.as_ref() {
        Some(change_set) => {
            Some(gitops_base_revision_reconcile_state(&state.store, change_set).await?)
        }
        None => None,
    };
    let action = work_item_reconcile_action(
        &work_item,
        work_plan.as_ref(),
        WorkItemDeliveryReconcileContext {
            change_set: change_set.as_ref(),
            git_delivery: git_delivery.as_ref(),
            pipeline_intent: pipeline_intent.as_ref(),
            pipeline_execution_ready: pipeline_execution_preflight
                .as_ref()
                .map(|preflight| preflight.ready),
            deployment_intent: deployment_intent.as_ref(),
            deployment_execution_preflight: deployment_execution_preflight.as_ref(),
            deployment_dispatch_ready,
            deployment_delivery: deployment_delivery.as_ref(),
            gitops_change_set: gitops_change_set.as_ref(),
            gitops_delivery: gitops_delivery.as_ref(),
            gitops_base_revision,
        },
    );
    let recorded_preflight =
        git_delivery_preflight_response(&state.store, git_delivery.as_ref()).await?;
    if !request.apply {
        return reconcile_work_item_response(
            &state,
            &work_item_id,
            action,
            false,
            recorded_preflight,
            "preview only; pass apply=true to perform the reported safe transition".to_string(),
        )
        .await
        .map(Json);
    }

    if action.controller_wait_kind().is_none() {
        supersede_active_controller_wait_if_present(
            &state,
            &work_item_id,
            format!("controller moved to {}", action.as_str()),
            actor.clone(),
        )
        .await?;
    }

    match action {
        WorkItemReconcileAction::DeclareWorkPlan => {
            if work_item.status == "submitted" {
                let planning = state
                    .store
                    .update_work_item_status(
                        &work_item.id,
                        "planning",
                        actor.clone(),
                        reason.clone().or_else(|| {
                            Some("controller advanced submitted WorkItem to planning".to_string())
                        }),
                    )
                    .await?;
                append_work_item_audit_event(
                    &state.store,
                    &planning,
                    "work_item.planning",
                    actor.clone(),
                    json!({ "source": "work_item.reconcile" }),
                )
                .await?;
            }
            let _ = create_work_plan_from_work_item(
                State(state.clone()),
                identity.clone(),
                Path(work_item_id.clone()),
            )
            .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                None,
                "declared the deterministic WorkPlan and ephemeral workspace; WorkPlan approval is now required"
                    .to_string(),
            )
            .await
            .map(Json)
        }
        WorkItemReconcileAction::StartCodingAttempt => {
            let Json(execution) = execute_work_item(
                State(state.clone()),
                identity,
                Path(work_item_id.clone()),
                Json(ExecuteWorkItemRequest {
                    actor,
                    reason,
                    max_turns: request.max_turns,
                }),
            )
            .await?;
            Ok(Json(ReconcileWorkItemResponse {
                action: action.as_str().to_string(),
                applied: true,
                work_item: execution.work_item,
                work_plan: state
                    .store
                    .get_work_plan_by_work_item(&work_item_id)
                    .await?
                    .map(Into::into),
                workspace: Some(execution.workspace),
                run: Some(execution.run),
                change_set: None,
                git_delivery_preflight: None,
                pipeline_intent: None,
                pipeline_execution_preflight: None,
                deployment_intent: None,
                deployment_execution_preflight: None,
                deployment_delivery: None,
                gitops_change_set: None,
                gitops_delivery: None,
                gitops_delivery_preflight: None,
                controller_wait: None,
                message: "started one bounded coding attempt in the declared isolated workspace"
                    .to_string(),
                boundary: action.as_str().to_string(),
                can_apply: false,
                effect_summary: "Started one bounded coding attempt in the declared isolated workspace."
                    .to_string(),
                blockers: vec![ReconcileBlockerResponse {
                    code: "controller_wait".to_string(),
                    summary: "Wait for the coding attempt to produce a durable outcome before reconciling again."
                        .to_string(),
                }],
                authorization_checks: vec![ReconcileAuthorizationCheckResponse {
                    kind: "controller_wait".to_string(),
                    status: "active".to_string(),
                    summary: "The bounded coding attempt now owns the next controller transition."
                        .to_string(),
                    resource_id: None,
                }],
            }))
        }
        WorkItemReconcileAction::CaptureChangeSet => {
            let Json(captured) = capture_work_item_change_set(
                State(state.clone()),
                identity,
                Path(work_item_id.clone()),
                Json(CaptureWorkItemChangeSetRequest { actor, reason }),
            )
            .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                None,
                format!(
                    "captured ChangeSet {}; source review is now required",
                    captured.change_set.id
                ),
            )
            .await
            .map(Json)
        }
        WorkItemReconcileAction::PrepareGitDelivery => {
            let Json(_) = prepare_change_set_git_delivery(
                State(state.clone()),
                Path(
                    change_set
                        .as_ref()
                        .expect("reconcile action requires a ChangeSet")
                        .id
                        .clone(),
                ),
                Json(PrepareGitDeliveryRequest {
                    actor: actor.clone(),
                    reason: reason.clone().or_else(|| {
                        Some("controller prepared immutable Git delivery plan".to_string())
                    }),
                }),
            )
            .await?;
            let Json(preflight) = preflight_change_set_git_delivery(
                State(state.clone()),
                identity,
                Path(
                    change_set
                        .as_ref()
                        .expect("reconcile action requires a ChangeSet")
                        .id
                        .clone(),
                ),
                Json(GitDeliveryPreflightRequest {
                    subject: None,
                    actor,
                    reason,
                }),
            )
            .await?;
            let message = if preflight.authorization_ready {
                "prepared and preflighted Git delivery; it is ready for the isolated Git writer"
                    .to_string()
            } else {
                "prepared and preflighted Git delivery; a matching Git writer grant is required"
                    .to_string()
            };
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                Some(preflight),
                message,
            )
            .await
            .map(Json)
        }
        WorkItemReconcileAction::AwaitingGitDeliveryExecution => Box::pin(async {
            let change_set = change_set
                .as_ref()
                .expect("Git delivery execution requires a ChangeSet");
            let Json(execution) = execute_change_set_git_delivery(
                State(state.clone()),
                identity,
                Path(change_set.id.clone()),
                Json(ExecuteGitDeliveryRequest {
                    subject: None,
                    actor: actor.clone(),
                    reason: reason.clone().unwrap_or_else(|| {
                        "controller applied the approved source Git delivery boundary".to_string()
                    }),
                }),
            )
            .await?;
            append_work_item_audit_event(
                &state.store,
                &work_item,
                "work_item.git_delivery_dispatched",
                actor.clone(),
                json!({
                    "change_set_id": change_set.id,
                    "execution_artifact_id": execution.execution.id,
                    "git_delivery_plan_artifact_id": execution.plan.id,
                    "permission_grant_id": execution.permission_grant.id,
                    "job_name": execution.job_name,
                    "status": execution.status,
                    "created": execution.created,
                    "automatic_execution": false,
                }),
            )
            .await?;

            if execution.status == "dispatch_failed" {
                return reconcile_work_item_response(
                    &state,
                    &work_item_id,
                    WorkItemReconcileAction::GitDeliveryFailed,
                    true,
                    recorded_preflight,
                    "recorded bounded source Git writer dispatch failure; apply reconcile again to record the terminal delivery block"
                        .to_string(),
                )
                .await
                .map(Json);
            }

            let (controller_wait, created) = schedule_controller_wait(
                &state,
                &work_item,
                WorkItemReconcileAction::WaitForGitDelivery,
                actor,
            )
            .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                recorded_preflight,
                if created {
                    format!(
                        "dispatched the approved isolated Git writer and scheduled bounded {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                } else {
                    format!(
                        "reused the Git writer dispatch and retained active {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                },
            )
            .await
            .map(Json)
        })
        .await,
        WorkItemReconcileAction::AwaitingPipelineExecution => Box::pin(async {
            let pipeline_intent = pipeline_intent
                .as_ref()
                .expect("Tekton execution requires a PipelineIntent");
            let Json(execution) = execute_pipeline_intent(
                State(state.clone()),
                identity,
                Path(pipeline_intent.id.clone()),
                Json(ExecutePipelineIntentRequest {
                    dry_run: false,
                    actor: actor.clone(),
                    reason: reason.clone().or_else(|| {
                        Some(
                            "controller applied the approved exact Tekton execution boundary"
                                .to_string(),
                        )
                    }),
                }),
            )
            .await?;
            append_work_item_audit_event(
                &state.store,
                &work_item,
                "work_item.pipeline_execution_dispatched",
                actor.clone(),
                json!({
                    "pipeline_intent_id": pipeline_intent.id,
                    "execution_id": execution.execution_id,
                    "executor_job_name": execution.executor_job_name,
                    "permission_grant_id": execution.permission_grant_id,
                    "status": execution.status,
                    "dry_run": execution.dry_run,
                    "automatic_execution": false,
                }),
            )
            .await?;

            if execution.status == "failed" {
                return reconcile_work_item_response(
                    &state,
                    &work_item_id,
                    WorkItemReconcileAction::PipelineExecutionFailed,
                    true,
                    recorded_preflight,
                    "recorded bounded Tekton executor dispatch failure; apply reconcile again to record the terminal delivery block"
                        .to_string(),
                )
                .await
                .map(Json);
            }

            let (controller_wait, created) = schedule_controller_wait(
                &state,
                &work_item,
                WorkItemReconcileAction::WaitForPipelineExecution,
                actor,
            )
            .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                recorded_preflight,
                if created {
                    format!(
                        "dispatched the approved isolated Tekton executor and scheduled bounded {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                } else {
                    format!(
                        "reused the Tekton executor dispatch and retained active {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                },
            )
            .await
            .map(Json)
        })
        .await,
        WorkItemReconcileAction::CompleteWorkItem => {
            let completed =
                complete_work_item_from_verified_release(&state, &work_item_id, actor, reason)
                    .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                recorded_preflight,
                format!(
                    "completed WorkItem {} from verified Release {}",
                    completed.work_item.id, completed.release.id
                ),
            )
            .await
            .map(Json)
        }
        WorkItemReconcileAction::AwaitingPullRequestObservation => Box::pin(async {
            let change_set = change_set
                .as_ref()
                .expect("pull-request observation requires a ChangeSet");
            let Json(observation) = observe_change_set_git_delivery(
                State(state.clone()),
                identity.clone(),
                Path(change_set.id.clone()),
                Json(ObserveGitDeliveryRequest {
                    actor: actor.clone(),
                    reason: reason.clone().unwrap_or_else(|| {
                        "controller applied the read-only Git delivery observation boundary"
                            .to_string()
                    }),
                }),
            )
            .await?;
            append_work_item_audit_event(
                &state.store,
                &work_item,
                "work_item.git_delivery_observation_dispatched",
                actor.clone(),
                json!({
                    "change_set_id": change_set.id,
                    "execution_artifact_id": observation.execution.id,
                    "job_name": observation.job_name,
                    "status": observation.status,
                    "created": observation.created,
                    "automatic_execution": false,
                }),
            )
            .await?;

            if observation.status == "dispatch_failed" {
                supersede_active_controller_wait_if_present(
                    &state,
                    &work_item_id,
                    "read-only Git observer dispatch failed".to_string(),
                    actor,
                )
                .await?;
                return reconcile_work_item_response(
                    &state,
                    &work_item_id,
                    action,
                    true,
                    recorded_preflight,
                    "recorded read-only Git observer dispatch failure; review executor configuration before retrying"
                        .to_string(),
                )
                .await
                .map(Json);
            }

            let (controller_wait, created) = schedule_controller_wait(
                &state,
                &work_item,
                WorkItemReconcileAction::AwaitingPullRequestObservation,
                actor,
            )
            .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                recorded_preflight,
                if created {
                    format!(
                        "dispatched the configured read-only Git observer and scheduled bounded {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                } else {
                    format!(
                        "reused the read-only Git observer dispatch and retained active {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                },
            )
            .await
            .map(Json)
        })
        .await,
        WorkItemReconcileAction::AwaitingGitOpsPullRequestObservation => Box::pin(async {
            let gitops_change_set = gitops_change_set
                .as_ref()
                .expect("GitOps pull-request observation requires a GitOps ChangeSet");
            let Json(observation) = observe_gitops_change_set_delivery(
                State(state.clone()),
                identity.clone(),
                Path(gitops_change_set.id.clone()),
                Json(ObserveGitOpsDeliveryRequest {
                    actor: actor.clone(),
                    reason: reason.clone().unwrap_or_else(|| {
                        "controller applied the read-only GitOps delivery observation boundary"
                            .to_string()
                    }),
                }),
            )
            .await?;
            append_work_item_audit_event(
                &state.store,
                &work_item,
                "work_item.gitops_delivery_observation_dispatched",
                actor.clone(),
                json!({
                    "gitops_change_set_id": gitops_change_set.id,
                    "execution_artifact_id": observation.execution.id,
                    "job_name": observation.job_name,
                    "status": observation.status,
                    "created": observation.created,
                    "automatic_execution": false,
                }),
            )
            .await?;

            if observation.status == "dispatch_failed" {
                supersede_active_controller_wait_if_present(
                    &state,
                    &work_item_id,
                    "read-only GitOps observer dispatch failed".to_string(),
                    actor,
                )
                .await?;
                return reconcile_work_item_response(
                    &state,
                    &work_item_id,
                    action,
                    true,
                    recorded_preflight,
                    "recorded read-only GitOps observer dispatch failure; review executor configuration before retrying"
                        .to_string(),
                )
                .await
                .map(Json);
            }

            let (controller_wait, created) = schedule_controller_wait(
                &state,
                &work_item,
                WorkItemReconcileAction::AwaitingGitOpsPullRequestObservation,
                actor,
            )
            .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                recorded_preflight,
                if created {
                    format!(
                        "dispatched the configured read-only GitOps observer and scheduled bounded {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                } else {
                    format!(
                        "reused the read-only GitOps observer dispatch and retained active {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                },
            )
            .await
            .map(Json)
        })
        .await,
        WorkItemReconcileAction::AwaitingGitOpsDeliveryExecution => Box::pin(async {
            let gitops_change_set = gitops_change_set
                .as_ref()
                .expect("GitOps delivery execution requires a GitOps ChangeSet");
            let Json(execution) = execute_gitops_change_set_delivery(
                State(state.clone()),
                identity,
                Path(gitops_change_set.id.clone()),
                Json(ExecuteGitOpsDeliveryRequest {
                    subject: None,
                    actor: actor.clone(),
                    reason: reason.clone().unwrap_or_else(|| {
                        "controller applied the approved immutable GitOps delivery boundary"
                            .to_string()
                    }),
                }),
            )
            .await?;
            append_work_item_audit_event(
                &state.store,
                &work_item,
                "work_item.gitops_delivery_dispatched",
                actor.clone(),
                json!({
                    "gitops_change_set_id": gitops_change_set.id,
                    "execution_artifact_id": execution.execution.id,
                    "gitops_delivery_plan_artifact_id": execution.plan.id,
                    "permission_grant_id": execution.permission_grant.id,
                    "job_name": execution.job_name,
                    "status": execution.status,
                    "created": execution.created,
                    "automatic_execution": false,
                }),
            )
            .await?;

            if execution.status == "dispatch_failed" {
                return reconcile_work_item_response(
                    &state,
                    &work_item_id,
                    WorkItemReconcileAction::GitOpsDeliveryFailed,
                    true,
                    recorded_preflight,
                    "recorded bounded GitOps writer dispatch failure; apply reconcile again to record the terminal delivery block"
                        .to_string(),
                )
                .await
                .map(Json);
            }

            let (controller_wait, created) = schedule_controller_wait(
                &state,
                &work_item,
                WorkItemReconcileAction::WaitForGitOpsDelivery,
                actor,
            )
            .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                recorded_preflight,
                if created {
                    format!(
                        "dispatched the approved isolated GitOps writer and scheduled bounded {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                } else {
                    format!(
                        "reused the GitOps writer dispatch and retained active {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                },
            )
            .await
            .map(Json)
        })
        .await,
        WorkItemReconcileAction::AwaitingDeploymentExecution => Box::pin(async {
            let deployment_intent = deployment_intent
                .as_ref()
                .expect("Argo sync execution requires a DeploymentIntent");
            let Json(execution) = execute_deployment_intent(
                State(state.clone()),
                identity,
                Path(deployment_intent.id.clone()),
                Json(ExecuteDeploymentIntentRequest {
                    dry_run: false,
                    actor: actor.clone(),
                    reason: reason.clone().or_else(|| {
                        Some(
                            "controller applied the approved exact Argo sync boundary".to_string(),
                        )
                    }),
                }),
            )
            .await?;
            append_work_item_audit_event(
                &state.store,
                &work_item,
                "work_item.deployment_execution_dispatched",
                actor.clone(),
                json!({
                    "deployment_intent_id": deployment_intent.id,
                    "execution_artifact_id": execution.execution.as_ref().map(|artifact| &artifact.id),
                    "execution_id": execution.execution_id,
                    "executor_job_name": execution.executor_job_name,
                    "permission_grant_id": execution.permission_grant.as_ref().map(|grant| &grant.id),
                    "status": execution.status,
                    "dry_run": execution.dry_run,
                    "automatic_execution": false,
                }),
            )
            .await?;

            if execution.status == "dispatch_failed" {
                return reconcile_work_item_response(
                    &state,
                    &work_item_id,
                    WorkItemReconcileAction::DeploymentExecutionFailed,
                    true,
                    recorded_preflight,
                    "recorded bounded Argo runner dispatch failure; apply reconcile again to record the terminal delivery block"
                        .to_string(),
                )
                .await
                .map(Json);
            }

            let (controller_wait, created) = schedule_controller_wait(
                &state,
                &work_item,
                WorkItemReconcileAction::WaitForDeploymentExecution,
                actor,
            )
            .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                recorded_preflight,
                if created {
                    format!(
                        "dispatched the approved isolated Argo runner and scheduled bounded {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                } else {
                    format!(
                        "reused the Argo runner dispatch and retained active {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                },
            )
            .await
            .map(Json)
        })
        .await,
        action if action.controller_wait_kind().is_some() => {
            let (controller_wait, created) =
                schedule_controller_wait(&state, &work_item, action, actor.clone()).await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                recorded_preflight,
                if created {
                    format!(
                        "scheduled bounded {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                } else {
                    format!(
                        "retained active {} wait {} for WorkItem {}",
                        controller_wait.wait_kind, controller_wait.id, work_item_id
                    )
                },
            )
            .await
            .map(Json)
        }
        action if action.delivery_failure().is_some() => {
            let (failure_code, failure_summary) = action
                .delivery_failure()
                .expect("matching controller action has a delivery failure");
            let blocked = block_work_item_from_delivery_failure(
                &state,
                &work_item_id,
                action,
                failure_code,
                failure_summary,
                actor,
                reason,
            )
            .await?;
            reconcile_work_item_response(
                &state,
                &work_item_id,
                action,
                true,
                recorded_preflight,
                format!(
                    "blocked WorkItem {}: {} ({})",
                    blocked.id, failure_summary, failure_code
                ),
            )
            .await
            .map(Json)
        }
        _ => reconcile_work_item_response(
            &state,
            &work_item_id,
            action,
            false,
            recorded_preflight,
            action.message(&work_item, work_plan.as_ref(), change_set.as_ref()),
        )
        .await
        .map(Json),
    }
}

/// Persist a terminal controller stop after a durable external-system failure.
/// It deliberately does not retry, rollback, or mutate the external target.
async fn block_work_item_from_delivery_failure(
    state: &AppState,
    work_item_id: &str,
    action: WorkItemReconcileAction,
    failure_code: &str,
    failure_summary: &str,
    actor: Option<String>,
    reason: Option<String>,
) -> Result<StoredWorkItem, ApiError> {
    let work_item = state
        .store
        .get_work_item(work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", work_item_id))?;
    if matches!(work_item.status.as_str(), "completed" | "cancelled") {
        return Err(ApiError::conflict(
            "terminal WorkItems cannot be blocked by controller reconciliation",
        ));
    }
    if work_item.status == "blocked" {
        return Ok(work_item);
    }
    let reason = reason.or_else(|| Some(failure_summary.to_string()));

    // A delivery failure is operational evidence, not merely a controller state
    // transition. Persist the evidence before blocking the WorkItem so the UI
    // and a future remediation controller have a durable, non-secret anchor.
    let work_plan = state.store.get_work_plan_by_work_item(work_item_id).await?;
    let (session_id, run_id, resource_namespace, resource_kind, resource_name, work_plan_id) =
        if let Some(work_plan) = work_plan {
            (
                work_plan.session_id,
                work_plan
                    .run_id
                    .or_else(|| work_item.current_run_id.clone()),
                work_plan
                    .resource_namespace
                    .or_else(|| work_item.target_namespace.clone()),
                work_plan
                    .resource_kind
                    .or_else(|| Some("work_item".to_string())),
                work_plan
                    .resource_name
                    .or_else(|| Some(work_item.id.clone())),
                Some(work_plan.id),
            )
        } else {
            let (session_id, run_id) = root_session_for_request(
                &state.store,
                None,
                work_item.current_run_id.clone(),
                "delivery failure evidence",
            )
            .await?;
            (
                session_id,
                run_id,
                work_item.target_namespace.clone(),
                Some("work_item".to_string()),
                Some(work_item.id.clone()),
                None,
            )
        };
    let evidence = json!({
        "source": "work_item_delivery_failure",
        "work_item_id": work_item.id,
        "work_plan_id": work_plan_id,
        "controller_action": action.as_str(),
        "failure_code": failure_code,
        "failure_summary": failure_summary,
        "source_provenance": {
            "repo": work_item.source_repo,
            "ref": work_item.source_ref,
        },
        "target": {
            "environment": work_item.target_environment,
            "namespace": work_item.target_namespace,
            "argo_application": work_item.argo_application,
            "production_impacting": work_item.production_impacting,
        },
        "budget": {
            "attempt_count": work_item.attempt_count,
            "max_attempts": work_item.max_attempts,
            "max_elapsed_seconds": work_item.max_elapsed_seconds,
        },
        "automatic_retry": false,
        "automatic_rollback": false,
        "mutation_performed": false,
    });
    let observation = state
        .store
        .create_observation(CreateObservation {
            id: format!("obs_delivery_failure_{}", unique_suffix()),
            session_id: session_id.clone(),
            run_id: run_id.clone(),
            source: "pharness_controller".to_string(),
            kind: "delivery_failure".to_string(),
            subject: format!("work_item/{}", work_item.id),
            summary: failure_summary.to_string(),
            resource_namespace: resource_namespace.clone(),
            resource_kind: resource_kind.clone(),
            resource_name: resource_name.clone(),
            resource_ref_json: Some(json!({
                "work_item_id": work_item.id,
                "work_plan_id": work_plan_id,
            })),
            artifact_id: None,
            data_json: evidence.clone(),
        })
        .await?;
    append_observation_audit_event(
        &state.store,
        &observation,
        "observation.delivery_failure_recorded",
        actor.clone(),
        reason.clone(),
    )
    .await?;
    let incident = state
        .store
        .create_incident(CreateIncident {
            id: format!("inc_delivery_failure_{}", unique_suffix()),
            observation_id: observation.id.clone(),
            session_id,
            run_id,
            status: "candidate".to_string(),
            severity: delivery_failure_severity(action).to_string(),
            title: format!("Delivery blocked: {}", work_item.title),
            summary: failure_summary.to_string(),
            resource_namespace,
            resource_kind,
            resource_name,
            data_json: evidence,
        })
        .await?;
    append_incident_audit_event(
        &state.store,
        &incident,
        "incident.delivery_failure_created",
        actor.clone(),
        reason.clone(),
    )
    .await?;
    let remediation_plan = create_delivery_failure_remediation_plan(
        &state.store,
        &incident,
        actor.clone(),
        reason.clone(),
    )
    .await?;
    let blocked = state
        .store
        .update_work_item_status(work_item_id, "blocked", actor.clone(), reason.clone())
        .await?;
    append_work_item_audit_event(
        &state.store,
        &blocked,
        "work_item.delivery_blocked",
        actor,
        json!({
            "source": "work_item.reconcile",
            "previous_status": work_item.status,
            "controller_action": action.as_str(),
            "failure_code": failure_code,
            "failure_summary": failure_summary,
            "reason": reason,
            "attempt_count": blocked.attempt_count,
            "max_attempts": blocked.max_attempts,
            "automatic_retry": false,
            "automatic_rollback": false,
            "mutation_performed": false,
            "observation_id": observation.id,
            "incident_id": incident.id,
            "remediation_plan_id": remediation_plan.as_ref().map(|plan| plan.id.as_str()),
        }),
    )
    .await?;
    Ok(blocked)
}

/// Schedule a bounded, durable wait for an external controller dependency.
/// This records intent to observe later; it does not run a poller or mutate the
/// external system. A future controller worker owns due-wait execution.
async fn schedule_controller_wait(
    state: &AppState,
    work_item: &StoredWorkItem,
    action: WorkItemReconcileAction,
    actor: Option<String>,
) -> Result<(StoredControllerWait, bool), ApiError> {
    let wait_kind = action
        .controller_wait_kind()
        .expect("only controller wait actions may schedule waits");
    if let Some(active) = state
        .store
        .get_active_controller_wait_for_work_item(&work_item.id)
        .await?
    {
        if active.wait_kind == wait_kind
            && active.subject_kind == "work_item"
            && active.subject_id == work_item.id
        {
            return Ok((active, false));
        }
        let reason = format!("controller moved to {}", action.as_str());
        let superseded = state
            .store
            .supersede_controller_wait(&active.id, reason.clone())
            .await?;
        append_controller_wait_audit_event(
            &state.store,
            &superseded,
            "controller_wait.superseded",
            actor.clone(),
            Some(reason),
        )
        .await?;
    }

    let work_plan = state
        .store
        .get_work_plan_by_work_item(&work_item.id)
        .await?;
    let (session_id, run_id) = match work_plan {
        Some(plan) => (
            plan.session_id,
            plan.run_id.or_else(|| work_item.current_run_id.clone()),
        ),
        None => {
            root_session_for_request(
                &state.store,
                None,
                work_item.current_run_id.clone(),
                "controller wait",
            )
            .await?
        }
    };
    let now = current_millis();
    let work_item_budget_ms = u128::from(work_item.max_elapsed_seconds).saturating_mul(1_000);
    let controller_budget_ms =
        CONTROLLER_WAIT_INTERVAL_MS.saturating_mul(u128::from(CONTROLLER_WAIT_MAX_CHECKS));
    let deadline_at = now.saturating_add(work_item_budget_ms.min(controller_budget_ms));
    let wait = state
        .store
        .create_controller_wait(CreateControllerWait {
            id: format!("cwait_{}", unique_suffix()),
            work_item_id: work_item.id.clone(),
            session_id,
            run_id,
            status: "active".to_string(),
            wait_kind: wait_kind.to_string(),
            subject_kind: "work_item".to_string(),
            subject_id: work_item.id.clone(),
            next_check_at: now.saturating_add(CONTROLLER_WAIT_INTERVAL_MS).to_string(),
            deadline_at: deadline_at.to_string(),
            max_checks: CONTROLLER_WAIT_MAX_CHECKS,
            data_json: json!({
                "source": "work_item.reconcile",
                "controller_action": action.as_str(),
                "work_item_id": work_item.id,
                "source_provenance": {
                    "repo": work_item.source_repo,
                    "ref": work_item.source_ref,
                },
                "target": {
                    "environment": work_item.target_environment,
                    "namespace": work_item.target_namespace,
                    "argo_application": work_item.argo_application,
                    "production_impacting": work_item.production_impacting,
                },
                "automatic_execution": false,
                "automatic_retry": false,
                "automatic_rollback": false,
            }),
        })
        .await?;
    append_controller_wait_audit_event(
        &state.store,
        &wait,
        "controller_wait.scheduled",
        actor,
        None,
    )
    .await?;
    Ok((wait, true))
}

async fn supersede_active_controller_wait_if_present(
    state: &AppState,
    work_item_id: &str,
    reason: String,
    actor: Option<String>,
) -> Result<Option<StoredControllerWait>, ApiError> {
    let Some(active) = state
        .store
        .get_active_controller_wait_for_work_item(work_item_id)
        .await?
    else {
        return Ok(None);
    };
    let wait = state
        .store
        .supersede_controller_wait(&active.id, reason.clone())
        .await?;
    append_controller_wait_audit_event(
        &state.store,
        &wait,
        "controller_wait.superseded",
        actor,
        Some(reason),
    )
    .await?;
    Ok(Some(wait))
}

/// Stop a non-terminal WorkItem when the controller can no longer observe a
/// required external result within its bounded wait budget. This creates no
/// remediation, retry, rollback, or external side effect.
async fn block_work_item_from_controller_wait_expiry(
    state: &AppState,
    work_item: &StoredWorkItem,
    wait: &StoredControllerWait,
    actor: Option<String>,
    reason: String,
) -> Result<StoredWorkItem, ApiError> {
    if matches!(
        work_item.status.as_str(),
        "blocked" | "completed" | "cancelled" | "failed"
    ) {
        return Ok(work_item.clone());
    }
    let blocked = state
        .store
        .update_work_item_status(
            &work_item.id,
            "blocked",
            actor.clone(),
            Some(reason.clone()),
        )
        .await?;
    append_work_item_audit_event(
        &state.store,
        &blocked,
        "work_item.controller_wait_blocked",
        actor,
        json!({
            "source": "controller_wait.reconcile_due",
            "previous_status": work_item.status,
            "controller_wait_id": wait.id,
            "wait_kind": wait.wait_kind,
            "deadline_at": wait.deadline_at,
            "max_checks": wait.max_checks,
            "check_count": wait.check_count,
            "reason": reason,
            "automatic_retry": false,
            "automatic_rollback": false,
            "mutation_performed": false,
        }),
    )
    .await?;
    Ok(blocked)
}

fn delivery_failure_severity(action: WorkItemReconcileAction) -> &'static str {
    match action {
        WorkItemReconcileAction::DeploymentExecutionFailed => "high",
        WorkItemReconcileAction::GitDeliveryFailed
        | WorkItemReconcileAction::PipelineExecutionFailed
        | WorkItemReconcileAction::GitOpsDeliveryFailed
        | WorkItemReconcileAction::PipelineIntentBlocked
        | WorkItemReconcileAction::GitOpsChangeSetBlocked
        | WorkItemReconcileAction::DeploymentIntentBlocked
        | WorkItemReconcileAction::ReleaseBlocked => "high",
        _ => "medium",
    }
}

async fn create_delivery_failure_remediation_plan(
    store: &SqliteStore,
    incident: &StoredIncident,
    actor: Option<String>,
    reason: Option<String>,
) -> Result<Option<StoredRemediationPlan>, ApiError> {
    if incident.status != "candidate"
        || incident.data_json.get("source").and_then(Value::as_str)
            != Some("work_item_delivery_failure")
    {
        return Ok(None);
    }

    let plan_id = format!("rplan_{}", incident.id);
    if let Some(existing) = store.get_remediation_plan(&plan_id).await? {
        return Ok(Some(existing));
    }

    let resource = incident_resource_label(incident);
    let plan = store
        .create_remediation_plan(CreateRemediationPlan {
            id: plan_id,
            incident_id: incident.id.clone(),
            session_id: incident.session_id.clone(),
            run_id: incident.run_id.clone(),
            status: "draft".to_string(),
            title: format!("Draft recovery for blocked delivery: {resource}"),
            summary: "Review the bounded delivery evidence, refresh only the affected read-only signals, and require explicit approval before any retry, source change, pipeline action, or cluster mutation.".to_string(),
            risk_level: incident.severity.clone(),
            requires_approval: true,
            resource_namespace: incident.resource_namespace.clone(),
            resource_kind: incident.resource_kind.clone(),
            resource_name: incident.resource_name.clone(),
            plan_json: delivery_failure_remediation_plan_json(incident, &resource),
        })
        .await?;
    append_remediation_plan_audit_event(
        store,
        &plan,
        "remediation_plan.created",
        actor,
        reason.or_else(|| Some("delivery failure requires operator review".to_string())),
    )
    .await?;

    for gate in approval_gates_from_remediation_plan(&plan) {
        let gate = store.create_approval_gate(gate).await?;
        append_approval_gate_audit_event(store, &gate, "approval_gate.created", "created").await?;
    }

    Ok(Some(plan))
}

fn delivery_failure_remediation_plan_json(incident: &StoredIncident, resource: &str) -> Value {
    let controller_action = incident
        .data_json
        .get("controller_action")
        .and_then(Value::as_str)
        .unwrap_or("delivery_failure");
    json!({
        "mode": "read_only_draft",
        "source": "work_item_delivery_failure",
        "incident_id": incident.id,
        "resource": {
            "namespace": incident.resource_namespace,
            "kind": incident.resource_kind,
            "name": incident.resource_name,
            "label": resource,
        },
        "evidence": {
            "work_item_id": incident.data_json.get("work_item_id"),
            "work_plan_id": incident.data_json.get("work_plan_id"),
            "controller_action": controller_action,
            "failure_code": incident.data_json.get("failure_code"),
            "failure_summary": incident.data_json.get("failure_summary"),
            "attempt_count": incident.data_json.pointer("/budget/attempt_count"),
            "max_attempts": incident.data_json.pointer("/budget/max_attempts"),
            "observation_id": incident.observation_id,
        },
        "steps": [
            {
                "order": 1,
                "kind": "read_only",
                "capability": "delivery_evidence_review",
                "summary": "Review the exact bounded failure evidence and immutable delivery lineage; do not rerun the failed action."
            },
            {
                "order": 2,
                "kind": "read_only",
                "capability": delivery_failure_observation_capability(controller_action),
                "summary": "Refresh only the affected delivery-system status and compare it with the recorded failure evidence."
            },
            {
                "order": 3,
                "kind": "proposal",
                "capability": "bounded_recovery_proposal",
                "summary": "Propose a replan, source ChangeSet, PipelineIntent, DeploymentIntent, or rollback plan only after reviewing current evidence and policy."
            }
        ],
        "approval_gates": [
            {
                "kind": "file_write",
                "required_before": "creating or patching source or GitOps changes"
            },
            {
                "kind": "git_mutation",
                "required_before": "creating, pushing, merging, or reverting a Git branch or pull request"
            },
            {
                "kind": "pipeline_mutation",
                "required_before": "rerunning or cancelling Tekton resources"
            },
            {
                "kind": "cluster_mutation",
                "required_before": "Argo sync, rollback, restart, scale, or Kubernetes write"
            },
            {
                "kind": "production_impact",
                "required_before": "any action against production-impacting scope"
            }
        ],
        "non_goals": [
            "No automatic retry",
            "No automatic rollback",
            "No automatic mutation",
            "No secret reads",
            "No ticket creation",
            "No notification dispatch"
        ]
    })
}

fn delivery_failure_observation_capability(action: &str) -> &'static str {
    match action {
        "pipeline_execution_failed" | "pipeline_intent_blocked" => "tekton_get_pipeline_runs",
        "deployment_execution_failed" | "deployment_intent_blocked" | "release_blocked" => {
            "argocd_get_application"
        }
        "git_delivery_failed" | "gitops_delivery_failed" | "gitops_change_set_blocked" => {
            "git_delivery_observation"
        }
        _ => "delivery_evidence_review",
    }
}

#[derive(Debug)]
struct CompletedWorkItemRelease {
    work_item: StoredWorkItem,
    release: StoredRelease,
}

/// Complete a WorkItem only from its already-completed, post-sync verified
/// release. This is a durable bookkeeping transition, never an external
/// deployment operation.
async fn complete_work_item_from_verified_release(
    state: &AppState,
    work_item_id: &str,
    actor: Option<String>,
    reason: Option<String>,
) -> Result<CompletedWorkItemRelease, ApiError> {
    let work_item = state
        .store
        .get_work_item(work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", work_item_id))?;
    if work_item.status != "awaiting_approval" {
        return Err(ApiError::conflict(
            "WorkItem completion requires an awaiting_approval WorkItem",
        ));
    }
    if !work_item_target_supported(&work_item) {
        return Err(ApiError::conflict(
            "Controller completion requires a supported dev or exact protected-production WorkItem",
        ));
    }
    let work_plan = state
        .store
        .get_work_plan_by_work_item(work_item_id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem completion requires a WorkPlan"))?;
    let change_set = state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem completion requires a ChangeSet"))?;
    let pipeline_intent = state
        .store
        .get_pipeline_intent_by_change_set(&change_set.id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem completion requires a PipelineIntent"))?;
    let deployment_intent = state
        .store
        .get_deployment_intent_by_pipeline_intent(&pipeline_intent.id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem completion requires a DeploymentIntent"))?;
    let release = state
        .store
        .get_release_by_deployment_intent(&deployment_intent.id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem completion requires a Release"))?;

    let lineage_matches = work_plan.status == "approved"
        && change_set.status == "approved"
        && pipeline_intent.status == "approved"
        && deployment_intent.status == "approved"
        && release.work_plan_id == work_plan.id
        && release.change_set_id == change_set.id
        && release.pipeline_intent_id == pipeline_intent.id
        && release.deployment_intent_id == deployment_intent.id;
    if !lineage_matches {
        return Err(ApiError::conflict(
            "WorkItem completion requires current approved delivery lineage",
        ));
    }
    let gitops_merge =
        observed_gitops_merge_for_deployment(&state.store, &work_item, &pipeline_intent).await?;
    let post_sync_verified = release.status == "completed"
        && release
            .release_json
            .pointer("/post_sync_verification/status")
            .and_then(Value::as_str)
            == Some("verified")
        && release
            .release_json
            .pointer("/post_sync_verification/runtime_ready")
            .and_then(Value::as_bool)
            == Some(true);
    if !post_sync_verified {
        return Err(ApiError::conflict(
            "WorkItem completion requires completed post-sync verified Release evidence",
        ));
    }

    let reason = reason.or_else(|| {
        Some(format!(
            "controller completed WorkItem from verified Release {}",
            release.id
        ))
    });
    let completed = state
        .store
        .update_work_item_status(work_item_id, "completed", actor.clone(), reason.clone())
        .await?;
    append_work_item_audit_event(
        &state.store,
        &completed,
        "work_item.completed_from_verified_release",
        actor,
        json!({
            "source": "work_item.reconcile",
            "work_plan_id": work_plan.id,
            "change_set_id": change_set.id,
            "pipeline_intent_id": pipeline_intent.id,
            "deployment_intent_id": deployment_intent.id,
            "release_id": release.id,
            "release_status": release.status,
            "gitops_delivery_merge_artifact_id": gitops_merge.as_ref().map(|artifact| &artifact.id),
            "post_sync_verification": release.release_json.get("post_sync_verification"),
            "reason": reason,
        }),
    )
    .await?;
    Ok(CompletedWorkItemRelease {
        work_item: completed,
        release,
    })
}

async fn replan_work_item(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
    Json(request): Json<ReplanWorkItemRequest>,
) -> Result<Json<ReplanWorkItemResponse>, ApiError> {
    let work_item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    if !matches!(work_item.status.as_str(), "blocked" | "failed") {
        return Err(ApiError::conflict(
            "WorkItem replan requires blocked or failed status",
        ));
    }
    if !work_item_target_supported(&work_item) {
        return Err(ApiError::conflict(
            "WorkItem replan is limited to dev or the exact protected production target",
        ));
    }
    if work_item.attempt_count >= work_item.max_attempts {
        return Err(ApiError::conflict("WorkItem attempt budget is exhausted"));
    }
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem has no WorkPlan to replan"))?;
    if work_plan.status != "approved" {
        return Err(ApiError::conflict(
            "WorkItem WorkPlan must remain approved before a retry can be scheduled",
        ));
    }
    if state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .is_some()
    {
        return Err(ApiError::conflict(
            "WorkItem already has a ChangeSet; revise and review the WorkPlan before another coding attempt",
        ));
    }

    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    let reason = required_text(request.reason, "reason")?;
    let previous_status = work_item.status.clone();
    let work_item = state
        .store
        .finish_work_item_attempt(
            &work_item.id,
            "awaiting_approval",
            actor.clone(),
            Some(reason.clone()),
        )
        .await?;
    let attempts_remaining = work_item.max_attempts - work_item.attempt_count;
    append_work_item_audit_event(
        &state.store,
        &work_item,
        "work_item.replanned",
        actor,
        json!({
            "previous_status": previous_status,
            "reason": reason,
            "work_plan_id": work_plan.id,
            "attempt_count": work_item.attempt_count,
            "max_attempts": work_item.max_attempts,
            "attempts_remaining": attempts_remaining,
        }),
    )
    .await?;
    Ok(Json(ReplanWorkItemResponse {
        work_item: work_item.into(),
        work_plan: work_plan.into(),
        attempts_remaining,
    }))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WorkItemReconcileAction {
    DeclareWorkPlan,
    AwaitingWorkPlanApproval,
    StartCodingAttempt,
    WaitForCodingAttempt,
    CaptureChangeSet,
    AwaitingChangeSetApproval,
    PrepareGitDelivery,
    AwaitingGitDeliveryAuthorization,
    AwaitingGitWriterAvailability,
    AwaitingGitDeliveryExecution,
    WaitForGitDelivery,
    AwaitingPullRequestObservation,
    AwaitingPullRequestMerge,
    AwaitingPipelineIntentDefinition,
    AwaitingPipelineIntentApproval,
    AwaitingPipelineExecutionAuthorization,
    AwaitingPipelineExecution,
    WaitForPipelineExecution,
    PipelineExecutionFailed,
    AwaitingPipelineEvidenceReview,
    AwaitingPipelineBuildOutputReview,
    AwaitingDeploymentIntentDefinition,
    AwaitingGitOpsUpdatePlan,
    AwaitingGitOpsChangeSetApproval,
    AwaitingGitOpsBaseRevision,
    WaitForGitOpsBaseRevision,
    AwaitingGitOpsDeliveryPlan,
    AwaitingGitOpsDeliveryAuthorization,
    AwaitingGitOpsWriterAvailability,
    AwaitingGitOpsDeliveryExecution,
    WaitForGitOpsDelivery,
    AwaitingGitOpsPullRequestObservation,
    AwaitingGitOpsPullRequestMerge,
    AwaitingDeploymentIntentReview,
    AwaitingDeploymentAuthorization,
    AwaitingArgoRunnerAvailability,
    AwaitingDeploymentExecution,
    WaitForDeploymentExecution,
    DeploymentExecutionFailed,
    AwaitingReleaseDefinition,
    AwaitingReleaseApproval,
    AwaitingReleaseVerification,
    CompleteWorkItem,
    DeploymentIntentBlocked,
    ReleaseBlocked,
    GitOpsDeliveryFailed,
    GitOpsChangeSetBlocked,
    PipelineIntentBlocked,
    GitDeliveryFailed,
    RequiresReplan,
    Terminal,
}

impl WorkItemReconcileAction {
    fn as_str(self) -> &'static str {
        match self {
            Self::DeclareWorkPlan => "declare_work_plan",
            Self::AwaitingWorkPlanApproval => "awaiting_work_plan_approval",
            Self::StartCodingAttempt => "start_coding_attempt",
            Self::WaitForCodingAttempt => "wait_for_coding_attempt",
            Self::CaptureChangeSet => "capture_change_set",
            Self::AwaitingChangeSetApproval => "awaiting_change_set_approval",
            Self::PrepareGitDelivery => "prepare_git_delivery",
            Self::AwaitingGitDeliveryAuthorization => "awaiting_git_delivery_authorization",
            Self::AwaitingGitWriterAvailability => "awaiting_git_writer_availability",
            Self::AwaitingGitDeliveryExecution => "awaiting_git_delivery_execution",
            Self::WaitForGitDelivery => "wait_for_git_delivery",
            Self::AwaitingPullRequestObservation => "awaiting_pull_request_observation",
            Self::AwaitingPullRequestMerge => "awaiting_pull_request_merge",
            Self::AwaitingPipelineIntentDefinition => "awaiting_pipeline_intent_definition",
            Self::AwaitingPipelineIntentApproval => "awaiting_pipeline_intent_approval",
            Self::AwaitingPipelineExecutionAuthorization => {
                "awaiting_pipeline_execution_authorization"
            }
            Self::AwaitingPipelineExecution => "awaiting_pipeline_execution",
            Self::WaitForPipelineExecution => "wait_for_pipeline_execution",
            Self::PipelineExecutionFailed => "pipeline_execution_failed",
            Self::AwaitingPipelineEvidenceReview => "awaiting_pipeline_evidence_review",
            Self::AwaitingPipelineBuildOutputReview => "awaiting_pipeline_build_output_review",
            Self::AwaitingDeploymentIntentDefinition => "awaiting_deployment_intent_definition",
            Self::AwaitingGitOpsUpdatePlan => "awaiting_gitops_update_plan",
            Self::AwaitingGitOpsChangeSetApproval => "awaiting_gitops_change_set_approval",
            Self::AwaitingGitOpsBaseRevision => "awaiting_gitops_base_revision",
            Self::WaitForGitOpsBaseRevision => "wait_for_gitops_base_revision",
            Self::AwaitingGitOpsDeliveryPlan => "awaiting_gitops_delivery_plan",
            Self::AwaitingGitOpsDeliveryAuthorization => "awaiting_gitops_delivery_authorization",
            Self::AwaitingGitOpsWriterAvailability => "awaiting_gitops_writer_availability",
            Self::AwaitingGitOpsDeliveryExecution => "awaiting_gitops_delivery_execution",
            Self::WaitForGitOpsDelivery => "wait_for_gitops_delivery",
            Self::AwaitingGitOpsPullRequestObservation => {
                "awaiting_gitops_pull_request_observation"
            }
            Self::AwaitingGitOpsPullRequestMerge => "awaiting_gitops_pull_request_merge",
            Self::AwaitingDeploymentIntentReview => "awaiting_deployment_intent_review",
            Self::AwaitingDeploymentAuthorization => "awaiting_deployment_authorization",
            Self::AwaitingArgoRunnerAvailability => "awaiting_argo_runner_availability",
            Self::AwaitingDeploymentExecution => "awaiting_deployment_execution",
            Self::WaitForDeploymentExecution => "wait_for_deployment_execution",
            Self::DeploymentExecutionFailed => "deployment_execution_failed",
            Self::AwaitingReleaseDefinition => "awaiting_release_definition",
            Self::AwaitingReleaseApproval => "awaiting_release_approval",
            Self::AwaitingReleaseVerification => "awaiting_release_verification",
            Self::CompleteWorkItem => "complete_work_item",
            Self::DeploymentIntentBlocked => "deployment_intent_blocked",
            Self::ReleaseBlocked => "release_blocked",
            Self::GitOpsDeliveryFailed => "gitops_delivery_failed",
            Self::GitOpsChangeSetBlocked => "gitops_change_set_blocked",
            Self::PipelineIntentBlocked => "pipeline_intent_blocked",
            Self::GitDeliveryFailed => "git_delivery_failed",
            Self::RequiresReplan => "requires_replan",
            Self::Terminal => "terminal",
        }
    }

    fn controller_wait_kind(self) -> Option<&'static str> {
        match self {
            Self::WaitForCodingAttempt => Some("coding_attempt"),
            Self::WaitForGitDelivery => Some("git_delivery_execution"),
            Self::AwaitingPullRequestObservation => Some("source_pull_request_observation"),
            Self::AwaitingPullRequestMerge => Some("source_pull_request_merge"),
            Self::WaitForPipelineExecution => Some("pipeline_execution"),
            Self::WaitForGitOpsBaseRevision => Some("gitops_base_revision"),
            Self::WaitForGitOpsDelivery => Some("gitops_delivery_execution"),
            Self::AwaitingGitOpsPullRequestObservation => Some("gitops_pull_request_observation"),
            Self::AwaitingGitOpsPullRequestMerge => Some("gitops_pull_request_merge"),
            Self::WaitForDeploymentExecution => Some("deployment_execution"),
            _ => None,
        }
    }

    fn is_applyable(self) -> bool {
        matches!(
            self,
            Self::DeclareWorkPlan
                | Self::StartCodingAttempt
                | Self::CaptureChangeSet
                | Self::PrepareGitDelivery
                | Self::AwaitingGitDeliveryExecution
                | Self::AwaitingPullRequestObservation
                | Self::AwaitingPipelineExecution
                | Self::AwaitingGitOpsBaseRevision
                | Self::AwaitingGitOpsDeliveryExecution
                | Self::AwaitingGitOpsPullRequestObservation
                | Self::AwaitingDeploymentExecution
                | Self::AwaitingReleaseVerification
                | Self::CompleteWorkItem
        )
    }

    fn message(
        self,
        work_item: &StoredWorkItem,
        work_plan: Option<&StoredWorkPlan>,
        change_set: Option<&StoredChangeSet>,
    ) -> String {
        match self {
            Self::AwaitingWorkPlanApproval => work_plan
                .map(|plan| format!("WorkPlan {} is {} and requires approval", plan.id, plan.status))
                .unwrap_or_else(|| "WorkItem requires a WorkPlan".to_string()),
            Self::WaitForCodingAttempt => "coding attempt is still running or awaiting its durable outcome".to_string(),
            Self::AwaitingChangeSetApproval => change_set
                .map(|change_set| {
                    format!(
                        "ChangeSet {} is {} and requires source review",
                        change_set.id, change_set.status
                    )
                })
                .unwrap_or_else(|| "ChangeSet capture is pending".to_string()),
            Self::AwaitingGitDeliveryAuthorization => {
                "Git delivery plan is prepared; a matching scoped Git writer grant and git_mutation gate decision are required"
                    .to_string()
            }
            Self::AwaitingGitWriterAvailability => {
                "Git delivery is authorized, but the dedicated Git writer is not configured for this exact repository"
                    .to_string()
            }
            Self::AwaitingGitDeliveryExecution => {
                "Git delivery is ready; explicitly execute the isolated branch-and-PR writer"
                    .to_string()
            }
            Self::WaitForGitDelivery => {
                "Git writer execution is in progress; wait for its durable branch-and-PR result"
                    .to_string()
            }
            Self::AwaitingPullRequestObservation => {
                "Git writer created a pull request; dispatch the read-only observer before any build is defined"
                    .to_string()
            }
            Self::AwaitingPullRequestMerge => {
                "Pull request is observed but lacks immutable merge provenance; wait for merge and observe again"
                    .to_string()
            }
            Self::AwaitingPipelineIntentDefinition => {
                "Immutable source merge provenance is recorded; define the exact PipelineIntent and PipelineContract next"
                    .to_string()
            }
            Self::AwaitingPipelineIntentApproval => {
                "PipelineIntent is proposed; review and approve its pinned PipelineContract and exact Tekton inputs"
                    .to_string()
            }
            Self::AwaitingPipelineExecutionAuthorization => {
                "PipelineIntent is approved but its scoped Tekton gates or trusted execution envelope are not yet ready"
                    .to_string()
            }
            Self::AwaitingPipelineExecution => {
                "PipelineIntent preflight is ready; explicitly dispatch the isolated Tekton executor"
                    .to_string()
            }
            Self::WaitForPipelineExecution => {
                "Tekton execution is in progress; wait for its signed-in executor outcome and terminal analysis"
                    .to_string()
            }
            Self::PipelineExecutionFailed => {
                "Tekton execution failed; inspect terminal evidence and revise or replan before further delivery"
                    .to_string()
            }
            Self::AwaitingPipelineEvidenceReview => {
                "Tekton completed, but its terminal PipelineRunAnalysis is not satisfied; review evidence before delivery planning"
                    .to_string()
            }
            Self::AwaitingPipelineBuildOutputReview => {
                "Tekton completed, but its build output is missing or not trusted; inspect terminal evidence before GitOps planning"
                    .to_string()
            }
            Self::AwaitingDeploymentIntentDefinition => {
                "Verified build evidence is ready; declare the exact development DeploymentIntent before GitOps update planning"
                    .to_string()
            }
            Self::AwaitingGitOpsUpdatePlan => {
                "Verified digest-pinned build output is ready; prepare the separate review-only GitOps update plan next"
                    .to_string()
            }
            Self::AwaitingGitOpsChangeSetApproval => {
                "GitOps ChangeSet is proposed; review its exact digest-pinned Kustomize update before authorization"
                    .to_string()
            }
            Self::AwaitingGitOpsBaseRevision => {
                "GitOps ChangeSet is approved; explicitly dispatch the read-only base-revision observer"
                    .to_string()
            }
            Self::WaitForGitOpsBaseRevision => {
                "GitOps base-revision observation is in progress; wait for immutable base commit evidence"
                    .to_string()
            }
            Self::AwaitingGitOpsDeliveryPlan => {
                "GitOps base revision is resolved; prepare the immutable GitOps delivery plan next"
                    .to_string()
            }
            Self::AwaitingGitOpsDeliveryAuthorization => {
                "GitOps delivery plan is prepared; a matching scoped GitOps writer grant and gitops_mutation gate decision are required"
                    .to_string()
            }
            Self::AwaitingGitOpsWriterAvailability => {
                "GitOps delivery is authorized, but the dedicated GitOps writer is not configured for this exact repository"
                    .to_string()
            }
            Self::AwaitingGitOpsDeliveryExecution => {
                "GitOps delivery is ready; explicitly execute the isolated GitOps branch-and-PR writer"
                    .to_string()
            }
            Self::WaitForGitOpsDelivery => {
                "GitOps writer execution is in progress; wait for its durable branch-and-PR result"
                    .to_string()
            }
            Self::AwaitingGitOpsPullRequestObservation => {
                "GitOps writer created a pull request; dispatch the read-only observer before Argo can be considered"
                    .to_string()
            }
            Self::AwaitingGitOpsPullRequestMerge => {
                "GitOps pull request is observed but lacks immutable merge provenance; wait for merge and observe again"
                    .to_string()
            }
            Self::AwaitingDeploymentIntentReview => {
                "Immutable GitOps merge provenance is recorded; review the declared DeploymentIntent before any Argo sync"
                    .to_string()
            }
            Self::AwaitingDeploymentAuthorization => {
                "DeploymentIntent is approved; a matching dev Argo contract, cluster_mutation gate, and scoped runner grant are required"
                    .to_string()
            }
            Self::AwaitingArgoRunnerAvailability => {
                "DeploymentIntent is authorized, but the isolated Argo runner is unavailable for this exact Application"
                    .to_string()
            }
            Self::AwaitingDeploymentExecution => {
                "DeploymentIntent is ready; explicitly dispatch the isolated Argo sync runner"
                    .to_string()
            }
            Self::WaitForDeploymentExecution => {
                "Argo sync is in progress; wait for its durable terminal result before proposing a Release"
                    .to_string()
            }
            Self::DeploymentExecutionFailed => {
                "Argo sync failed; inspect the bounded result and create a reviewed remediation or deployment revision"
                    .to_string()
            }
            Self::AwaitingReleaseDefinition => {
                "Argo sync completed; create the linked Release record before post-sync verification"
                    .to_string()
            }
            Self::AwaitingReleaseApproval => {
                "Release is proposed; review its immutable deployment provenance before verification"
                    .to_string()
            }
            Self::AwaitingReleaseVerification => {
                "Release is approved; explicitly run bounded post-sync verification against its declared targets"
                    .to_string()
            }
            Self::CompleteWorkItem => {
                "Release verification is complete; apply reconciliation to record terminal WorkItem completion"
                    .to_string()
            }
            Self::DeploymentIntentBlocked => {
                "DeploymentIntent is stale or rejected; create and review a new deployment intent before Argo execution"
                    .to_string()
            }
            Self::ReleaseBlocked => {
                "Release is stale or rejected; revise and review release provenance before post-sync verification"
                    .to_string()
            }
            Self::GitOpsDeliveryFailed => {
                "GitOps delivery failed; inspect its bounded result and create a newly reviewed GitOps ChangeSet"
                    .to_string()
            }
            Self::GitOpsChangeSetBlocked => {
                "GitOps ChangeSet is stale or rejected; create a newly reviewed GitOps plan before delivery can continue"
                    .to_string()
            }
            Self::PipelineIntentBlocked => {
                "PipelineIntent is stale or rejected; create a newly reviewed PipelineIntent before delivery can continue"
                    .to_string()
            }
            Self::GitDeliveryFailed => {
                "Git delivery failed; inspect its bounded result and revise/review the ChangeSet before another delivery"
                    .to_string()
            }
            Self::RequiresReplan => format!(
                "WorkItem is {} after {}/{} coding attempts; explicit replan or cancellation is required",
                work_item.status, work_item.attempt_count, work_item.max_attempts
            ),
            Self::Terminal => format!("WorkItem is terminal: {}", work_item.status),
            _ => format!("next action is {}", self.as_str()),
        }
    }

    fn delivery_failure(self) -> Option<(&'static str, &'static str)> {
        match self {
            Self::GitDeliveryFailed => Some((
                "source_git_delivery_failed",
                "the bounded source Git writer reported a failed delivery",
            )),
            Self::PipelineExecutionFailed => Some((
                "pipeline_execution_failed",
                "the bounded Tekton execution reported a failed delivery",
            )),
            Self::GitOpsDeliveryFailed => Some((
                "gitops_delivery_failed",
                "the bounded GitOps writer reported a failed delivery",
            )),
            Self::DeploymentExecutionFailed => Some((
                "deployment_execution_failed",
                "the bounded Argo sync execution reported a failed delivery",
            )),
            Self::PipelineIntentBlocked => Some((
                "pipeline_intent_blocked",
                "the PipelineIntent is stale or rejected and cannot be executed",
            )),
            Self::GitOpsChangeSetBlocked => Some((
                "gitops_change_set_blocked",
                "the GitOps ChangeSet is stale or rejected and cannot be delivered",
            )),
            Self::DeploymentIntentBlocked => Some((
                "deployment_intent_blocked",
                "the DeploymentIntent is stale or rejected and cannot be executed",
            )),
            Self::ReleaseBlocked => Some((
                "release_blocked",
                "the Release is stale or rejected and cannot be verified",
            )),
            _ => None,
        }
    }
}

struct WorkItemDeliveryReconcileContext<'a> {
    change_set: Option<&'a StoredChangeSet>,
    git_delivery: Option<&'a GitDeliveryFlowResponse>,
    pipeline_intent: Option<&'a StoredPipelineIntent>,
    pipeline_execution_ready: Option<bool>,
    deployment_intent: Option<&'a StoredDeploymentIntent>,
    deployment_execution_preflight: Option<&'a DeploymentIntentExecutionPreflight>,
    deployment_dispatch_ready: Option<bool>,
    deployment_delivery: Option<&'a DeploymentIntentDeliveryFlowResponse>,
    gitops_change_set: Option<&'a StoredGitOpsChangeSet>,
    gitops_delivery: Option<&'a GitOpsDeliveryFlowResponse>,
    gitops_base_revision: Option<GitOpsBaseRevisionReconcileState>,
}

fn work_item_reconcile_action(
    work_item: &StoredWorkItem,
    work_plan: Option<&StoredWorkPlan>,
    delivery: WorkItemDeliveryReconcileContext<'_>,
) -> WorkItemReconcileAction {
    match work_item.status.as_str() {
        "submitted" | "planning" => WorkItemReconcileAction::DeclareWorkPlan,
        "awaiting_approval" => match delivery.change_set {
            Some(change_set) if change_set.status == "approved" => {
                let git_action = git_delivery_reconcile_action(delivery.git_delivery);
                if git_action == WorkItemReconcileAction::AwaitingPipelineIntentDefinition {
                    let pipeline_action = pipeline_intent_reconcile_action(
                        delivery.pipeline_intent,
                        delivery.pipeline_execution_ready,
                        delivery.deployment_intent,
                    );
                    if pipeline_action == WorkItemReconcileAction::AwaitingGitOpsUpdatePlan {
                        let gitops_action = gitops_change_set_reconcile_action(
                            delivery.gitops_change_set,
                            delivery.gitops_delivery,
                            delivery.gitops_base_revision,
                        );
                        if gitops_action == WorkItemReconcileAction::AwaitingDeploymentIntentReview
                        {
                            deployment_intent_reconcile_action(
                                delivery.deployment_intent,
                                delivery.deployment_execution_preflight,
                                delivery.deployment_dispatch_ready,
                                delivery.deployment_delivery,
                            )
                        } else {
                            gitops_action
                        }
                    } else {
                        pipeline_action
                    }
                } else {
                    git_action
                }
            }
            Some(_) => WorkItemReconcileAction::AwaitingChangeSetApproval,
            None if work_plan.is_some_and(|plan| plan.status == "approved") => {
                WorkItemReconcileAction::StartCodingAttempt
            }
            None => WorkItemReconcileAction::AwaitingWorkPlanApproval,
        },
        "executing" => WorkItemReconcileAction::WaitForCodingAttempt,
        "verifying" => WorkItemReconcileAction::CaptureChangeSet,
        "blocked" | "failed" => WorkItemReconcileAction::RequiresReplan,
        "completed" | "cancelled" => WorkItemReconcileAction::Terminal,
        _ => WorkItemReconcileAction::RequiresReplan,
    }
}

fn pipeline_intent_reconcile_action(
    pipeline_intent: Option<&StoredPipelineIntent>,
    pipeline_execution_ready: Option<bool>,
    deployment_intent: Option<&StoredDeploymentIntent>,
) -> WorkItemReconcileAction {
    let Some(pipeline_intent) = pipeline_intent else {
        return WorkItemReconcileAction::AwaitingPipelineIntentDefinition;
    };
    match pipeline_intent.status.as_str() {
        "proposed" => WorkItemReconcileAction::AwaitingPipelineIntentApproval,
        "executing" => WorkItemReconcileAction::WaitForPipelineExecution,
        "failed" => WorkItemReconcileAction::PipelineExecutionFailed,
        "rejected" | "stale" => WorkItemReconcileAction::PipelineIntentBlocked,
        "approved" => match pipeline_intent_execution_state(pipeline_intent) {
            Some("pipeline_run_succeeded") => {
                if !pipeline_evidence_is_satisfied(pipeline_intent) {
                    WorkItemReconcileAction::AwaitingPipelineEvidenceReview
                } else if !pipeline_build_output_is_verified(pipeline_intent) {
                    WorkItemReconcileAction::AwaitingPipelineBuildOutputReview
                } else if deployment_intent.is_none() {
                    WorkItemReconcileAction::AwaitingDeploymentIntentDefinition
                } else {
                    WorkItemReconcileAction::AwaitingGitOpsUpdatePlan
                }
            }
            Some("pipeline_run_failed") | Some("failed") | Some("dispatch_failed") => {
                WorkItemReconcileAction::PipelineExecutionFailed
            }
            _ if pipeline_execution_ready == Some(true) => {
                WorkItemReconcileAction::AwaitingPipelineExecution
            }
            _ => WorkItemReconcileAction::AwaitingPipelineExecutionAuthorization,
        },
        _ => WorkItemReconcileAction::PipelineIntentBlocked,
    }
}

fn pipeline_intent_execution_state(intent: &StoredPipelineIntent) -> Option<&str> {
    intent
        .intent_json
        .pointer("/execution_state/state")
        .and_then(Value::as_str)
}

fn pipeline_build_output_is_verified(intent: &StoredPipelineIntent) -> bool {
    intent
        .intent_json
        .pointer("/build_output/status")
        .and_then(Value::as_str)
        == Some("verified")
}

fn pipeline_evidence_is_satisfied(intent: &StoredPipelineIntent) -> bool {
    pipeline_intent_attached_evidence_status(intent) == Some("satisfied")
}

fn pipeline_intent_is_gitops_update_eligible(intent: &StoredPipelineIntent) -> bool {
    pipeline_intent_is_deployment_eligible(&intent.status) && pipeline_evidence_is_satisfied(intent)
}

fn pipeline_intent_requires_execution_preflight(intent: &StoredPipelineIntent) -> bool {
    intent.status == "approved" && pipeline_intent_execution_state(intent).is_none()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GitOpsBaseRevisionReconcileState {
    Missing,
    Resolving,
    Resolved,
}

async fn gitops_base_revision_reconcile_state(
    store: &SqliteStore,
    change_set: &StoredGitOpsChangeSet,
) -> Result<GitOpsBaseRevisionReconcileState, ApiError> {
    let artifacts = store.list_artifacts(&change_set.run_id).await?;
    if artifacts
        .iter()
        .any(|artifact| gitops_base_revision_matches_change_set(artifact, change_set))
    {
        return Ok(GitOpsBaseRevisionReconcileState::Resolved);
    }
    let latest_execution = artifacts
        .iter()
        .filter(|artifact| {
            artifact.kind == "gitops_base_revision_execution"
                && artifact.content_json.as_ref().is_some_and(|content| {
                    content.get("gitops_change_set_id").and_then(Value::as_str)
                        == Some(change_set.id.as_str())
                        && content.get("material_hash").and_then(Value::as_str)
                            == Some(change_set.material_hash.as_str())
                })
        })
        .max_by_key(|artifact| (&artifact.created_at, &artifact.id));
    let resolving = latest_execution.is_some_and(|execution| {
        let execution_id = execution
            .content_json
            .as_ref()
            .and_then(|content| content.get("execution_id"))
            .and_then(Value::as_str);
        execution_id.is_some_and(|execution_id| {
            !artifacts.iter().any(|artifact| {
                artifact.kind == "gitops_base_revision"
                    && artifact.content_json.as_ref().is_some_and(|content| {
                        content.get("execution_id").and_then(Value::as_str) == Some(execution_id)
                            && content.get("status").and_then(Value::as_str) == Some("failed")
                    })
            })
        })
    });
    Ok(if resolving {
        GitOpsBaseRevisionReconcileState::Resolving
    } else {
        GitOpsBaseRevisionReconcileState::Missing
    })
}

fn gitops_change_set_reconcile_action(
    change_set: Option<&StoredGitOpsChangeSet>,
    delivery: Option<&GitOpsDeliveryFlowResponse>,
    base_revision: Option<GitOpsBaseRevisionReconcileState>,
) -> WorkItemReconcileAction {
    let Some(change_set) = change_set else {
        return WorkItemReconcileAction::AwaitingGitOpsUpdatePlan;
    };
    match change_set.status.as_str() {
        "proposed" => WorkItemReconcileAction::AwaitingGitOpsChangeSetApproval,
        "rejected" | "stale" => WorkItemReconcileAction::GitOpsChangeSetBlocked,
        "applied" => WorkItemReconcileAction::AwaitingDeploymentIntentReview,
        "approved" => match delivery {
            Some(delivery) => gitops_delivery_reconcile_action(delivery),
            None => match base_revision.unwrap_or(GitOpsBaseRevisionReconcileState::Missing) {
                GitOpsBaseRevisionReconcileState::Missing => {
                    WorkItemReconcileAction::AwaitingGitOpsBaseRevision
                }
                GitOpsBaseRevisionReconcileState::Resolving => {
                    WorkItemReconcileAction::WaitForGitOpsBaseRevision
                }
                GitOpsBaseRevisionReconcileState::Resolved => {
                    WorkItemReconcileAction::AwaitingGitOpsDeliveryPlan
                }
            },
        },
        _ => WorkItemReconcileAction::GitOpsChangeSetBlocked,
    }
}

fn gitops_delivery_reconcile_action(
    delivery: &GitOpsDeliveryFlowResponse,
) -> WorkItemReconcileAction {
    if delivery.latest_merge.is_some() {
        return WorkItemReconcileAction::AwaitingDeploymentIntentReview;
    }
    if let Some(observation) = delivery.latest_observation.as_ref() {
        let status = observation
            .content_json
            .as_ref()
            .and_then(|content| content.get("status"))
            .and_then(Value::as_str);
        if status == Some("failed") {
            return WorkItemReconcileAction::AwaitingGitOpsPullRequestObservation;
        }
        let merged = observation
            .content_json
            .as_ref()
            .and_then(|content| content.get("merged"))
            .and_then(Value::as_bool)
            .unwrap_or(false);
        return if merged {
            WorkItemReconcileAction::AwaitingDeploymentIntentReview
        } else {
            WorkItemReconcileAction::AwaitingGitOpsPullRequestMerge
        };
    }
    if let Some(result) = delivery.latest_result.as_ref() {
        return match result
            .content_json
            .as_ref()
            .and_then(|content| content.get("status"))
            .and_then(Value::as_str)
        {
            Some("completed") => WorkItemReconcileAction::AwaitingGitOpsPullRequestObservation,
            Some("failed") | Some("dispatch_failed") => {
                WorkItemReconcileAction::GitOpsDeliveryFailed
            }
            _ => WorkItemReconcileAction::WaitForGitOpsDelivery,
        };
    }
    if delivery.latest_execution.is_some() {
        return WorkItemReconcileAction::WaitForGitOpsDelivery;
    }
    match delivery
        .latest_preflight
        .as_ref()
        .and_then(|artifact| artifact.content_json.as_ref())
        .and_then(|content| content.get("status"))
        .and_then(Value::as_str)
    {
        Some("ready_for_writer") => {
            let dispatch_ready = delivery
                .latest_preflight
                .as_ref()
                .and_then(|artifact| artifact.content_json.as_ref())
                .and_then(|content| content.get("dispatch_ready"))
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if dispatch_ready {
                WorkItemReconcileAction::AwaitingGitOpsDeliveryExecution
            } else {
                WorkItemReconcileAction::AwaitingGitOpsWriterAvailability
            }
        }
        _ => WorkItemReconcileAction::AwaitingGitOpsDeliveryAuthorization,
    }
}

fn deployment_intent_reconcile_action(
    intent: Option<&StoredDeploymentIntent>,
    preflight: Option<&DeploymentIntentExecutionPreflight>,
    dispatch_ready: Option<bool>,
    delivery: Option<&DeploymentIntentDeliveryFlowResponse>,
) -> WorkItemReconcileAction {
    let Some(intent) = intent else {
        return WorkItemReconcileAction::AwaitingDeploymentIntentDefinition;
    };
    match intent.status.as_str() {
        "proposed" => WorkItemReconcileAction::AwaitingDeploymentIntentReview,
        "rejected" | "stale" => WorkItemReconcileAction::DeploymentIntentBlocked,
        "approved" => {
            let Some(delivery) = delivery else {
                return WorkItemReconcileAction::AwaitingDeploymentAuthorization;
            };
            if let Some(result) = delivery.latest_result.as_ref() {
                return match result
                    .content_json
                    .as_ref()
                    .and_then(|content| content.get("status"))
                    .and_then(Value::as_str)
                {
                    Some("completed") => release_reconcile_action(delivery.release.as_ref()),
                    Some("failed") | Some("cancelled") | Some("dispatch_failed") => {
                        WorkItemReconcileAction::DeploymentExecutionFailed
                    }
                    _ => WorkItemReconcileAction::WaitForDeploymentExecution,
                };
            }
            if delivery.latest_execution.is_some() {
                return WorkItemReconcileAction::WaitForDeploymentExecution;
            }
            let Some(preflight) = preflight else {
                return WorkItemReconcileAction::AwaitingDeploymentAuthorization;
            };
            if !preflight.ready {
                return WorkItemReconcileAction::AwaitingDeploymentAuthorization;
            }
            if dispatch_ready == Some(true) {
                WorkItemReconcileAction::AwaitingDeploymentExecution
            } else {
                WorkItemReconcileAction::AwaitingArgoRunnerAvailability
            }
        }
        _ => WorkItemReconcileAction::DeploymentIntentBlocked,
    }
}

fn release_reconcile_action(release: Option<&ReleaseResponse>) -> WorkItemReconcileAction {
    let Some(release) = release else {
        return WorkItemReconcileAction::AwaitingReleaseDefinition;
    };
    match release.status.as_str() {
        "proposed" => WorkItemReconcileAction::AwaitingReleaseApproval,
        "approved" => WorkItemReconcileAction::AwaitingReleaseVerification,
        "completed" => WorkItemReconcileAction::CompleteWorkItem,
        "rejected" | "stale" => WorkItemReconcileAction::ReleaseBlocked,
        _ => WorkItemReconcileAction::ReleaseBlocked,
    }
}

fn git_delivery_reconcile_action(
    git_delivery: Option<&GitDeliveryFlowResponse>,
) -> WorkItemReconcileAction {
    let Some(git_delivery) = git_delivery else {
        return WorkItemReconcileAction::PrepareGitDelivery;
    };

    if git_delivery.latest_merge.is_some() {
        return WorkItemReconcileAction::AwaitingPipelineIntentDefinition;
    }

    if let Some(observation) = git_delivery.latest_observation.as_ref() {
        let observation_status = observation
            .content_json
            .as_ref()
            .and_then(|content| content.get("status"))
            .and_then(Value::as_str);
        if observation_status == Some("failed") {
            return WorkItemReconcileAction::AwaitingPullRequestObservation;
        }
        let merged = observation
            .content_json
            .as_ref()
            .and_then(|content| content.get("merged"))
            .and_then(Value::as_bool)
            .unwrap_or(false);
        if merged {
            return WorkItemReconcileAction::AwaitingPipelineIntentDefinition;
        }
        return WorkItemReconcileAction::AwaitingPullRequestMerge;
    }

    if let Some(result) = git_delivery.latest_result.as_ref() {
        return match result
            .content_json
            .as_ref()
            .and_then(|content| content.get("status"))
            .and_then(Value::as_str)
        {
            Some("completed") => WorkItemReconcileAction::AwaitingPullRequestObservation,
            Some("failed") | Some("dispatch_failed") => WorkItemReconcileAction::GitDeliveryFailed,
            _ => WorkItemReconcileAction::WaitForGitDelivery,
        };
    }

    if git_delivery.latest_execution.is_some() {
        return WorkItemReconcileAction::WaitForGitDelivery;
    }

    match git_delivery
        .latest_preflight
        .as_ref()
        .and_then(|artifact| artifact.content_json.as_ref())
        .and_then(|content| content.get("status"))
        .and_then(Value::as_str)
    {
        Some("ready_for_writer") => {
            let dispatch_ready = git_delivery
                .latest_preflight
                .as_ref()
                .and_then(|artifact| artifact.content_json.as_ref())
                .and_then(|content| content.get("dispatch_ready"))
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if dispatch_ready {
                WorkItemReconcileAction::AwaitingGitDeliveryExecution
            } else {
                WorkItemReconcileAction::AwaitingGitWriterAvailability
            }
        }
        _ => WorkItemReconcileAction::AwaitingGitDeliveryAuthorization,
    }
}

async fn git_delivery_preflight_response(
    store: &SqliteStore,
    git_delivery: Option<&GitDeliveryFlowResponse>,
) -> Result<Option<GitDeliveryPreflightResponse>, ApiError> {
    let Some(git_delivery) = git_delivery else {
        return Ok(None);
    };
    let Some(artifact) = git_delivery.latest_preflight.as_ref() else {
        return Ok(None);
    };
    let Some(content) = artifact.content_json.as_ref() else {
        return Ok(None);
    };
    let Some(status) = content.get("status").and_then(Value::as_str) else {
        return Ok(None);
    };
    let permission_grant = match content
        .get("permission_grant_id")
        .and_then(Value::as_str)
        .filter(|grant_id| !grant_id.is_empty())
    {
        Some(grant_id) => store.get_permission_grant(grant_id).await?.map(Into::into),
        None => None,
    };
    let checks = content
        .get("checks")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();

    Ok(Some(GitDeliveryPreflightResponse {
        status: status.to_string(),
        approval_gate_ready: content
            .get("approval_gate_ready")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        authorization_ready: content
            .get("authorization_ready")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        dispatch_ready: content
            .get("dispatch_ready")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        plan: git_delivery.plan.clone(),
        permission_grant,
        checks,
        artifact: artifact.clone(),
        created: false,
    }))
}

async fn gitops_delivery_preflight_response(
    store: &SqliteStore,
    gitops_delivery: Option<&GitOpsDeliveryFlowResponse>,
) -> Result<Option<GitOpsDeliveryPreflightResponse>, ApiError> {
    let Some(gitops_delivery) = gitops_delivery else {
        return Ok(None);
    };
    let Some(artifact) = gitops_delivery.latest_preflight.as_ref() else {
        return Ok(None);
    };
    let Some(content) = artifact.content_json.as_ref() else {
        return Ok(None);
    };
    let Some(status) = content.get("status").and_then(Value::as_str) else {
        return Ok(None);
    };
    let permission_grant = match content
        .get("permission_grant_id")
        .and_then(Value::as_str)
        .filter(|grant_id| !grant_id.is_empty())
    {
        Some(grant_id) => store.get_permission_grant(grant_id).await?.map(Into::into),
        None => None,
    };
    let checks = content
        .get("checks")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    Ok(Some(GitOpsDeliveryPreflightResponse {
        status: status.to_string(),
        approval_gate_ready: content
            .get("approval_gate_ready")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        authorization_ready: content
            .get("authorization_ready")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        dispatch_ready: content
            .get("dispatch_ready")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        plan: gitops_delivery.plan.clone(),
        base_revision: gitops_delivery.base_revision.clone(),
        permission_grant,
        checks,
        artifact: artifact.clone(),
        created: false,
    }))
}

fn deployment_intent_execution_preflight_response(
    preflight: DeploymentIntentExecutionPreflight,
    dispatch_ready: Option<bool>,
) -> DeploymentIntentPreflightResponse {
    let ready_for_argo_runner = preflight.ready;
    DeploymentIntentPreflightResponse {
        status: if ready_for_argo_runner {
            "ready_for_argo_runner"
        } else {
            "blocked"
        }
        .to_string(),
        ready_for_argo_runner,
        dispatch_ready: dispatch_ready.unwrap_or(false),
        deployment_intent: preflight.intent.into(),
        deployment_contract: preflight.contract.map(Into::into),
        permission_grant: preflight.grant.map(Into::into),
        checks: preflight.checks,
    }
}

async fn reconcile_work_item_response(
    state: &AppState,
    work_item_id: &str,
    action: WorkItemReconcileAction,
    applied: bool,
    git_delivery_preflight: Option<GitDeliveryPreflightResponse>,
    message: String,
) -> Result<ReconcileWorkItemResponse, ApiError> {
    let work_item = state
        .store
        .get_work_item(work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", work_item_id))?;
    let work_plan = state.store.get_work_plan_by_work_item(work_item_id).await?;
    let controller_wait = state
        .store
        .get_active_controller_wait_for_work_item(work_item_id)
        .await?;
    let change_set = match &work_plan {
        Some(work_plan) => {
            state
                .store
                .get_change_set_by_work_plan(&work_plan.id)
                .await?
        }
        None => None,
    };
    let workspace = state
        .store
        .list_workspaces(WorkspaceListFilter {
            work_item_id: Some(work_item_id.to_string()),
            limit: 50,
            ..WorkspaceListFilter::default()
        })
        .await?
        .into_iter()
        .max_by(|left, right| {
            left.updated_at
                .cmp(&right.updated_at)
                .then_with(|| left.id.cmp(&right.id))
        });
    let run = match &work_item.current_run_id {
        Some(run_id) => state.store.get_run(run_id).await?,
        None => None,
    };
    let pipeline_intent = match change_set.as_ref() {
        Some(change_set) => {
            state
                .store
                .get_pipeline_intent_by_change_set(&change_set.id)
                .await?
        }
        None => None,
    };
    let pipeline_execution_preflight = match pipeline_intent
        .as_ref()
        .filter(|intent| pipeline_intent_requires_execution_preflight(intent))
    {
        Some(intent) => Some(pipeline_intent_execution_preflight(state, &intent.id).await?),
        None => None,
    };
    let deployment_intent = match pipeline_intent.as_ref() {
        Some(intent) => {
            state
                .store
                .get_deployment_intent_by_pipeline_intent(&intent.id)
                .await?
        }
        None => None,
    };
    let deployment_execution_preflight = match deployment_intent
        .as_ref()
        .filter(|intent| intent.status == "approved")
    {
        Some(intent) => Some(deployment_intent_execution_preflight(state, &intent.id).await?),
        None => None,
    };
    let deployment_dispatch_ready = deployment_execution_preflight.as_ref().map(|preflight| {
        state.worker.argo_executor_available()
            && deployment_target(&preflight.intent)
                .ok()
                .is_some_and(|target| {
                    state
                        .worker
                        .argo_executor_allows_application(&target.application)
                })
    });
    let deployment_delivery =
        deployment_intent_delivery_flow(&state.store, deployment_intent.as_ref()).await?;
    let gitops_change_set = match pipeline_intent.as_ref() {
        Some(intent) => {
            state
                .store
                .get_gitops_change_set_by_pipeline_intent(&intent.id)
                .await?
        }
        None => None,
    };
    let gitops_delivery = gitops_delivery_flow(&state.store, gitops_change_set.as_ref()).await?;
    let gitops_delivery_preflight =
        gitops_delivery_preflight_response(&state.store, gitops_delivery.as_ref()).await?;

    let can_apply = action.is_applyable() && controller_wait.is_none();
    let mut blockers = Vec::new();
    if let Some(wait) = &controller_wait {
        blockers.push(ReconcileBlockerResponse {
            code: "controller_wait".to_string(),
            summary: format!(
                "{} is active for {} and must resolve or expire before another controller action can run",
                wait.wait_kind, wait.subject_id
            ),
        });
    } else if !action.is_applyable() {
        blockers.push(ReconcileBlockerResponse {
            code: action.as_str().to_string(),
            summary: message.clone(),
        });
    }
    let authorization_checks = reconcile_authorization_checks(action);
    let effect_summary = if can_apply {
        format!(
            "Applying this controller action will {}",
            action_effect(action)
        )
    } else {
        message.clone()
    };

    Ok(ReconcileWorkItemResponse {
        action: action.as_str().to_string(),
        applied,
        work_item: work_item.into(),
        work_plan: work_plan.map(Into::into),
        workspace: workspace.map(Into::into),
        run: run.map(Into::into),
        change_set: change_set.map(Into::into),
        git_delivery_preflight,
        pipeline_intent: pipeline_intent.map(Into::into),
        pipeline_execution_preflight: pipeline_execution_preflight
            .map(pipeline_execution_preflight_response),
        deployment_intent: deployment_intent.map(Into::into),
        deployment_execution_preflight: deployment_execution_preflight.map(|preflight| {
            deployment_intent_execution_preflight_response(preflight, deployment_dispatch_ready)
        }),
        deployment_delivery,
        gitops_change_set: gitops_change_set.map(Into::into),
        gitops_delivery,
        gitops_delivery_preflight,
        controller_wait: controller_wait.map(Into::into),
        message,
        boundary: action.as_str().to_string(),
        can_apply,
        effect_summary,
        blockers,
        authorization_checks,
    })
}

fn action_effect(action: WorkItemReconcileAction) -> &'static str {
    match action {
        WorkItemReconcileAction::DeclareWorkPlan => {
            "declare one deterministic WorkPlan and its ephemeral workspace"
        }
        WorkItemReconcileAction::StartCodingAttempt => {
            "dispatch one bounded model-backed coding attempt"
        }
        WorkItemReconcileAction::CaptureChangeSet => {
            "capture the completed workspace diff and test evidence as a proposed ChangeSet"
        }
        WorkItemReconcileAction::PrepareGitDelivery => {
            "prepare a review-only source Git delivery plan"
        }
        WorkItemReconcileAction::AwaitingGitDeliveryExecution => {
            "dispatch one isolated source branch-and-pull-request writer"
        }
        WorkItemReconcileAction::AwaitingPullRequestObservation => {
            "dispatch one read-only source pull-request observer"
        }
        WorkItemReconcileAction::AwaitingPipelineExecution => {
            "dispatch one isolated Tekton executor"
        }
        WorkItemReconcileAction::AwaitingGitOpsBaseRevision => {
            "dispatch one read-only GitOps base-revision observer"
        }
        WorkItemReconcileAction::AwaitingGitOpsDeliveryExecution => {
            "dispatch one isolated GitOps branch-and-pull-request writer"
        }
        WorkItemReconcileAction::AwaitingGitOpsPullRequestObservation => {
            "dispatch one read-only GitOps pull-request observer"
        }
        WorkItemReconcileAction::AwaitingDeploymentExecution => {
            "dispatch one isolated Argo reconciliation runner"
        }
        WorkItemReconcileAction::AwaitingReleaseVerification => {
            "record the bounded release verification action"
        }
        WorkItemReconcileAction::CompleteWorkItem => "mark the verified WorkItem complete",
        _ => "perform the next bounded controller action",
    }
}

fn reconcile_authorization_checks(
    action: WorkItemReconcileAction,
) -> Vec<ReconcileAuthorizationCheckResponse> {
    let authorization_missing = matches!(
        action,
        WorkItemReconcileAction::AwaitingGitDeliveryAuthorization
            | WorkItemReconcileAction::AwaitingPipelineExecutionAuthorization
            | WorkItemReconcileAction::AwaitingGitOpsDeliveryAuthorization
            | WorkItemReconcileAction::AwaitingDeploymentAuthorization
    );
    let executor_unavailable = matches!(
        action,
        WorkItemReconcileAction::AwaitingGitWriterAvailability
            | WorkItemReconcileAction::AwaitingGitOpsWriterAvailability
            | WorkItemReconcileAction::AwaitingArgoRunnerAvailability
    );
    vec![
        ReconcileAuthorizationCheckResponse {
            kind: "approval_gate".to_string(),
            status: if authorization_missing { "missing" } else { "not_required" }.to_string(),
            summary: if authorization_missing {
                "A matching approval gate must be satisfied before this controller boundary can advance."
            } else {
                "No approval gate decision is required for the current controller boundary."
            }
            .to_string(),
            resource_id: None,
        },
        ReconcileAuthorizationCheckResponse {
            kind: "permission_grant".to_string(),
            status: if authorization_missing { "missing" } else { "not_required" }.to_string(),
            summary: if authorization_missing {
                "A matching scoped PermissionGrant or trusted envelope is required."
            } else {
                "No scoped mutation grant is required for the current controller boundary."
            }
            .to_string(),
            resource_id: None,
        },
        ReconcileAuthorizationCheckResponse {
            kind: "executor_allowlist".to_string(),
            status: if executor_unavailable { "unavailable" } else { "not_required" }.to_string(),
            summary: if executor_unavailable {
                "The required dedicated executor is not configured for this exact target."
            } else {
                "No dedicated executor availability check is required for the current boundary."
            }
            .to_string(),
            resource_id: None,
        },
    ]
}

async fn execute_work_item(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
    Json(request): Json<ExecuteWorkItemRequest>,
) -> Result<Json<ExecuteWorkItemResponse>, ApiError> {
    let local_workspace = state.worker.supports_local_workspace();
    let remote_workspace = state.worker.supports_remote_workspace();
    if !local_workspace && !remote_workspace {
        return Err(ApiError::conflict(
            "real coding alpha requires a local or Kubernetes worker",
        ));
    }
    if remote_workspace && !state.workspace.remote_configured() {
        return Err(ApiError::conflict(
            "Kubernetes coding requires PHARNESS_WORKSPACE_ALLOWED_REMOTE_REPOS",
        ));
    }
    let work_item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    if !work_item_target_supported(&work_item) {
        return Err(ApiError::conflict(
            "coding execution is limited to dev or the exact protected production target",
        ));
    }
    let environment_profile = match work_item.environment_profile_id.as_deref() {
        Some(profile_id) => Some(
            environment::select_profile(
                &state.environment_profiles,
                profile_id,
                &work_item.source_repo,
            )
            .map_err(ApiError::conflict)?
            .clone(),
        ),
        None if work_item.production_impacting => {
            return Err(ApiError::conflict(
                "production coding requires an immutable environment profile",
            ));
        }
        None => None,
    };
    if environment_profile.is_some() && !remote_workspace {
        return Err(ApiError::conflict(
            "immutable environment profile execution requires the Kubernetes worker",
        ));
    }
    if work_item.status != "awaiting_approval" {
        return Err(ApiError::conflict(
            "WorkItem must be awaiting_approval before an execution attempt can start",
        ));
    }
    if work_item.attempt_count >= work_item.max_attempts {
        return Err(ApiError::conflict("WorkItem attempt budget is exhausted"));
    }
    if request
        .max_turns
        .is_some_and(|requested| requested != work_item.run_budget.initial_turns)
    {
        return Err(ApiError::conflict(
            "attempt max_turns is fixed by the WorkItem RunBudget; update it through the wizard or a budget extension",
        ));
    }
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem has no WorkPlan"))?;
    if work_plan.status != "approved" {
        return Err(ApiError::conflict(
            "WorkItem WorkPlan must be approved before source execution",
        ));
    }
    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    let workspace = state
        .store
        .list_workspaces(WorkspaceListFilter {
            work_item_id: Some(work_item_id.clone()),
            status: Some("declared".to_string()),
            limit: 1,
            ..Default::default()
        })
        .await?
        .into_iter()
        .next();
    let workspace = match workspace {
        Some(workspace) => workspace,
        None => {
            state
                .store
                .create_workspace(CreateWorkspace {
                    id: format!("ws_{}", unique_suffix()),
                    work_item_id: work_item.id.clone(),
                    run_id: None,
                    status: "declared".to_string(),
                    source_repo: work_item.source_repo.clone(),
                    source_ref: work_item.source_ref.clone(),
                    resolved_commit: None,
                    branch: None,
                    retention_status: "ephemeral".to_string(),
                    actor: actor.clone(),
                    reason: Some("retry attempt requires a fresh isolated workspace".to_string()),
                })
                .await?
        }
    };
    let reason = clean_optional_text(request.reason).unwrap_or_else(|| {
        if local_workspace {
            "bounded local coding attempt".to_string()
        } else {
            "bounded Kubernetes coding attempt".to_string()
        }
    });
    let attempt = work_item.attempt_count + 1;
    let (cwd, branch, base_commit, workspace_source, workspace_status, execution_kind) =
        if local_workspace {
            let provisioned = state
                .workspace
                .provision(
                    &work_item.id,
                    attempt,
                    &work_item.source_repo,
                    &work_item.source_ref,
                    work_item.source_commit.as_deref(),
                )
                .await
                .map_err(|error| ApiError::conflict(error.to_string()))?;
            (
                provisioned.cwd.to_string_lossy().to_string(),
                provisioned.branch,
                Some(provisioned.resolved_commit),
                None,
                "executing",
                "local_workspace",
            )
        } else {
            let branch = format!("pharness/{}/attempt-{attempt}", work_item.id);
            let source = pharness_runhost::WorkspaceSourceSpec {
                workspace_id: workspace.id.clone(),
                source_repo: work_item.source_repo.clone(),
                source_ref: work_item.source_ref.clone(),
                source_commit: work_item.source_commit.clone(),
                branch: branch.clone(),
                resolved_commit: None,
            };
            state
                .workspace
                .remote_source_allowed(&source)
                .map_err(|error| ApiError::conflict(error.to_string()))?;
            (
                state.worker.effective_cwd("/workspace"),
                branch,
                None,
                Some(source),
                "provisioning",
                "kubernetes_workspace",
            )
        };
    let run_id = RunId::new(format!("run_{}", unique_suffix()));
    let session_id = SessionId::new(format!("ses_{}", run_id.as_str()));
    let run_scope = RunScope {
        run_id: Some(run_id.to_string()),
        namespace: work_item.target_namespace.clone(),
        repo: Some(work_item.source_repo.clone()),
        branch: Some(branch.clone()),
        work_item_id: Some(work_item.id.clone()),
        workspace_id: Some(workspace.id.clone()),
        work_plan_id: Some(work_plan.id.clone()),
        change_set_id: None,
        production_impacting: work_item.production_impacting,
    };
    let contract = work_item
        .repository_contract_json
        .clone()
        .map(serde_json::from_value::<ProjectContract>)
        .transpose()
        .map_err(|error| {
            ApiError::internal(format!("stored repository contract is invalid: {error}"))
        })?;
    if work_item.production_impacting && contract.is_none() {
        return Err(ApiError::conflict(
            "production coding requires a validated repository contract",
        ));
    }
    if let Some(contract) = contract.as_ref() {
        create_permission_grant_record(
            &state.store,
            CreatePermissionGrantRequest {
                subject: state.policy.subject.clone(),
                created_by: actor.clone(),
                reason: format!(
                    "attempt-scoped workspace authorization for WorkItem {} run {}",
                    work_item.id, run_id
                ),
                scope: json!({
                    "environment": state.policy.environment,
                    "capability_kinds": ["filesystem"],
                    "actions": ["write_file", "patch_file", "create_directory"],
                    "max_risk": "medium",
                    "namespaces": work_item.target_namespace.iter().collect::<Vec<_>>(),
                    "repos": [work_item.source_repo],
                    "branches": [branch],
                    "run_ids": [run_id.to_string()],
                    "workspace_ids": [workspace.id],
                    "writable_path_globs": contract.writable_paths,
                    "work_item_ids": [work_item.id],
                    "work_plan_ids": [work_plan.id],
                    "production_impacting": work_item.production_impacting,
                }),
                policy: json!({ "policy_mode": "trusted_writes" }),
                expires_at: Some((current_millis() + 4 * 60 * 60 * 1_000).to_string()),
            },
        )
        .await?;
    }
    let mut policy = run_policy(&state.policy, None);
    policy.permission_grants = active_permission_grants(&state.store).await?;
    state
        .store
        .create_session(CreateSession {
            id: session_id.clone(),
            title: format!("WorkItem attempt: {}", work_item.title),
            cwd: cwd.clone(),
        })
        .await?;
    let run = state
        .store
        .create_run(CreateRun {
            id: run_id.clone(),
            session_id: session_id.clone(),
            user_task: coding_task_prompt(&work_item),
            cwd: cwd.clone(),
            max_turns: work_item.run_budget.initial_turns,
            initial_status: if environment_profile.is_some() {
                "preparing".to_string()
            } else {
                "queued".to_string()
            },
            execution_target_json: json!({
                "kind": execution_kind,
                "policy": &policy,
                "run_scope": run_scope.to_optional_json(),
                "workspace": {
                    "base_commit": base_commit,
                    "branch": branch,
                },
                "workspace_source": workspace_source,
                "run_budget": &work_item.run_budget,
                "environment_profile_id": work_item.environment_profile_id,
                "repository_contract": work_item.repository_contract_json,
                "selected_acceptance_commands": work_item.acceptance_criteria,
                "runner_profile": environment_profile.clone(),
            }),
        })
        .await?;
    let run = state
        .store
        .set_run_budget(
            &run.id,
            &work_item.run_budget,
            &RunBudgetConsumption {
                allowed_turns: work_item.run_budget.initial_turns,
                allowed_tokens: work_item.run_budget.initial_tokens,
                ..RunBudgetConsumption::default()
            },
        )
        .await?;
    let run = state.store.set_run_origin(&run.id, "controller").await?;
    let run = state
        .store
        .set_run_created_by(&run.id, actor.clone())
        .await?;
    state
        .store
        .append_event(&AgentEvent {
            event_id: EventId::new(format!("evt_{}_1", run_id.as_str())),
            session_id: session_id.clone(),
            run_id: run_id.clone(),
            seq: 1,
            kind: EventKind::RunQueued,
            payload: json!({
                "source": "work_item.execute",
                "worker": state.worker.mode(),
                "provider": state.worker.config_json().get("provider"),
                "model": state.worker.config_json().get("model"),
                "run_scope": run_scope.to_optional_json(),
                "base_commit": base_commit,
                "branch": branch,
            }),
        })
        .await?;
    let workspace = state
        .store
        .update_workspace_execution(
            &workspace.id,
            UpdateWorkspaceExecution {
                run_id: Some(run_id.clone()),
                status: workspace_status.to_string(),
                resolved_commit: base_commit.clone(),
                branch: Some(branch.clone()),
                actor: actor.clone(),
                reason: Some(reason.clone()),
            },
        )
        .await?;
    let work_item = state
        .store
        .start_work_item_attempt(&work_item.id, &run_id, actor.clone(), Some(reason))
        .await?;
    append_workspace_audit_event(
        &state.store,
        &workspace,
        if local_workspace {
            "workspace.provisioned"
        } else {
            "workspace.provisioning_requested"
        },
        actor.clone(),
    )
    .await?;
    append_work_item_audit_event(
        &state.store,
        &work_item,
        "work_item.execution_started",
        actor,
        json!({ "workspace_id": workspace.id, "run_id": run_id, "base_commit": workspace.resolved_commit, "branch": workspace.branch, "execution_kind": execution_kind }),
    )
    .await?;
    if let Some(profile) = environment_profile.as_ref() {
        let source_commit = work_item
            .source_commit
            .clone()
            .ok_or_else(|| ApiError::conflict("environment preparation requires source_commit"))?;
        let preparation = state
            .store
            .create_environment_preparation(CreateEnvironmentPreparation {
                id: format!("prep_{}", unique_suffix()),
                work_item_id: work_item.id.clone(),
                workspace_id: workspace.id.clone(),
                run_id: Some(run.id.clone()),
                status: "queued".to_string(),
                environment_profile_id: profile.id.clone(),
                source_commit,
            })
            .await?;
        let receipt = state
            .worker
            .dispatch_environment_preparation(&run, profile)
            .await
            .map_err(|error| ApiError::internal(error.to_string()))?;
        state
            .store
            .update_environment_preparation(UpdateEnvironmentPreparation {
                id: preparation.id,
                status: "running".to_string(),
                project_contract_json: None,
                project_contract_hash: None,
                environment_snapshot_json: None,
                logs_json: json!([{"step":"dispatch","status":"succeeded","job_name":receipt.job_name}]),
                error: None,
            })
            .await?;
    } else {
        state.worker.spawn_run(run.clone(), cwd);
    }
    Ok(Json(ExecuteWorkItemResponse {
        work_item: work_item.into(),
        workspace: workspace.into(),
        run: run.into(),
    }))
}

async fn capture_work_item_change_set(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
    Json(request): Json<CaptureWorkItemChangeSetRequest>,
) -> Result<Json<CreateChangeSetResponse>, ApiError> {
    let work_item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    if !matches!(work_item.status.as_str(), "executing" | "verifying") {
        return Err(ApiError::conflict(
            "WorkItem has no completed coding attempt to capture",
        ));
    }
    let workspace = state
        .store
        .list_workspaces(WorkspaceListFilter {
            work_item_id: Some(work_item_id.clone()),
            status: Some("verifying".to_string()),
            limit: 1,
            ..Default::default()
        })
        .await?
        .into_iter()
        .next()
        .ok_or_else(|| {
            ApiError::conflict("WorkItem has no completed workspace ready for capture")
        })?;
    let run_id = workspace
        .run_id
        .clone()
        .ok_or_else(|| ApiError::conflict("workspace has no run"))?;
    let run = state
        .store
        .get_run(&run_id)
        .await?
        .ok_or_else(|| ApiError::not_found("run", run_id.as_str()))?;
    if run.status != "completed" {
        return Err(ApiError::conflict(
            "coding run must complete before ChangeSet capture",
        ));
    }
    if state
        .store
        .get_change_set_by_work_plan(
            &state
                .store
                .get_work_plan_by_work_item(&work_item_id)
                .await?
                .ok_or_else(|| ApiError::conflict("WorkItem has no WorkPlan"))?
                .id,
        )
        .await?
        .is_some()
    {
        return Err(ApiError::conflict(
            "WorkItem already has a captured ChangeSet",
        ));
    }
    let base_commit = workspace
        .resolved_commit
        .as_deref()
        .ok_or_else(|| ApiError::conflict("workspace has no pinned base commit"))?;
    let (evidence, diff_artifact_id, status_artifact_id, test_events) = if run
        .execution_target_json
        .get("workspace_source")
        .is_some()
    {
        worker_workspace_evidence(&state.store, &run, &workspace).await?
    } else {
        state
            .workspace
            .ensure_managed(FsPath::new(&run.cwd))
            .await
            .map_err(|error| ApiError::conflict(error.to_string()))?;
        let evidence = crate::workspace::collect_git_evidence(FsPath::new(&run.cwd), base_commit)
            .await
            .map_err(|error| ApiError::conflict(error.to_string()))?;
        let artifact = state
            .store
            .create_artifact(CreateArtifact {
                id: format!("art_{}", unique_suffix()),
                session_id: run.session_id.clone(),
                run_id: Some(run_id.clone()),
                kind: "workspace_git_diff".to_string(),
                label: format!("Git diff for {}", work_item.title),
                mime_type: Some("text/x-diff".to_string()),
                path: None,
                content_text: Some(evidence.diff.clone()),
                content_json: None,
            })
            .await?;
        let test_events = shell_test_evidence(&state.store.list_events(&run_id).await?);
        let source_status = state.store.create_artifact(CreateArtifact {
                id: format!("art_{}", unique_suffix()), session_id: run.session_id.clone(), run_id: Some(run_id.clone()),
                kind: "workspace_git_status".to_string(), label: "Captured Git status and test summaries".to_string(),
                mime_type: Some("application/json".to_string()), path: None, content_text: None,
                content_json: Some(json!({ "status": evidence.status, "changed_paths": evidence.changed_paths, "test_events": test_events })),
            }).await?;
        (evidence, artifact.id, source_status.id, test_events)
    };
    if evidence.changed_paths.is_empty() || evidence.diff.is_empty() {
        return Err(ApiError::conflict("coding run produced no source diff"));
    }
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem has no WorkPlan"))?;
    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    let diff_hash = format!("{:x}", Sha256::digest(evidence.diff.as_bytes()));
    let change_set_json = json!({
        "source": { "kind": "workspace_git", "work_item_id": work_item.id, "workspace_id": workspace.id, "base_commit": base_commit, "branch": workspace.branch },
        "evidence": { "git_diff_artifact_id": diff_artifact_id, "git_status_artifact_id": status_artifact_id, "diff_sha256": diff_hash, "changed_paths": evidence.changed_paths },
        "verification": { "run_id": run_id, "test_event_count": test_events.len() }
    });
    let change_set = state
        .store
        .create_change_set(CreateChangeSet {
            id: format!("cset_{}", unique_suffix()),
            work_item_id: Some(work_item.id.clone()),
            work_plan_id: work_plan.id.clone(),
            remediation_plan_id: None,
            incident_id: None,
            session_id: run.session_id.clone(),
            run_id: Some(run_id.clone()),
            status: "proposed".to_string(),
            title: format!("ChangeSet: {}", work_item.title),
            summary: run
                .result_json
                .as_ref()
                .and_then(|result| result.get("summary"))
                .and_then(Value::as_str)
                .unwrap_or(&work_item.intent)
                .to_string(),
            risk_level: work_plan.risk_level.clone(),
            material_hash: material_hash(&change_set_json)?,
            resource_namespace: work_plan.resource_namespace.clone(),
            resource_kind: work_plan.resource_kind.clone(),
            resource_name: work_plan.resource_name.clone(),
            change_set_json,
        })
        .await?;
    let workspace = state
        .store
        .update_workspace_execution(
            &workspace.id,
            UpdateWorkspaceExecution {
                run_id: Some(run_id.clone()),
                status: "captured".to_string(),
                resolved_commit: Some(base_commit.to_string()),
                branch: workspace.branch.clone(),
                actor: actor.clone(),
                reason: clean_optional_text(request.reason),
            },
        )
        .await?;
    let work_item = state
        .store
        .update_work_item_status(
            &work_item.id,
            "awaiting_approval",
            actor.clone(),
            Some("real ChangeSet captured; source review required".to_string()),
        )
        .await?;
    append_change_set_audit_event(&state.store, &change_set, "change_set.captured", actor.clone(), None, json!({ "workspace_id": workspace.id, "run_id": run_id, "git_diff_artifact_id": diff_artifact_id, "git_status_artifact_id": status_artifact_id })).await?;
    append_workspace_audit_event(
        &state.store,
        &workspace,
        "workspace.change_set_captured",
        actor.clone(),
    )
    .await?;
    append_work_item_audit_event(
        &state.store,
        &work_item,
        "work_item.awaiting_approval",
        actor,
        json!({ "change_set_id": change_set.id }),
    )
    .await?;
    Ok(Json(CreateChangeSetResponse {
        change_set: change_set.into(),
        created: true,
    }))
}

async fn create_work_item_pipeline_intent(
    State(state): State<AppState>,
    identity: Option<Extension<OperatorIdentity>>,
    Path(work_item_id): Path<String>,
    Json(request): Json<CreateWorkItemPipelineIntentRequest>,
) -> Result<Json<CreatePipelineIntentResponse>, ApiError> {
    let work_item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem has no WorkPlan"))?;
    let change_set = state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .ok_or_else(|| {
            ApiError::conflict(
                "WorkItem has no captured ChangeSet; source review and immutable merge evidence are required before a PipelineIntent",
            )
        })?;
    if change_set.work_item_id.as_deref() != Some(work_item.id.as_str()) {
        return Err(ApiError::conflict(
            "WorkItem ChangeSet lineage does not match the requested WorkItem",
        ));
    }

    let source_provenance = work_item_pipeline_source_provenance(&state.store, &change_set)
        .await?
        .ok_or_else(|| {
            ApiError::conflict(
                "WorkItem PipelineIntent requires immutable Git merge provenance before a pipeline definition",
            )
        })?;
    let pipeline_contract_id = required_text(request.pipeline_contract_id, "pipeline_contract_id")?;
    let pipeline_contract = state
        .store
        .get_pipeline_contract(&pipeline_contract_id)
        .await?
        .ok_or_else(|| ApiError::not_found("pipeline_contract", &pipeline_contract_id))?;
    if pipeline_contract.status != "active" {
        return Err(ApiError::conflict(format!(
            "WorkItem PipelineIntent requires an active PipelineContract; {} is {}",
            pipeline_contract.id, pipeline_contract.status
        )));
    }
    let mut intent_json = request.intent_json.ok_or_else(|| {
        ApiError::bad_request(
            "WorkItem PipelineIntent requires an exact enabled Tekton execution definition",
        )
    })?;
    let execution = tekton_execution_spec(&intent_json)?;
    if !execution.enabled {
        return Err(ApiError::conflict(
            "WorkItem PipelineIntent execution must be enabled before it can be reviewed against a PipelineContract",
        ));
    }
    let source_revision = required_json_string(
        source_provenance.as_object().ok_or_else(|| {
            ApiError::internal("WorkItem source provenance must have an object body")
        })?,
        "merge_commit_sha",
        "WorkItem source provenance",
    )?;
    execution_matches_pipeline_contract(&execution, &pipeline_contract, Some(&source_revision))?;
    let intent_object = intent_json.as_object_mut().ok_or_else(|| {
        ApiError::bad_request("WorkItem PipelineIntent intent_json must be a JSON object")
    })?;
    intent_object.insert(
        "pipeline_contract".to_string(),
        json!({
            "id": pipeline_contract.id,
            "version": pipeline_contract.version,
            "namespace": pipeline_contract.namespace,
            "pipeline_ref": pipeline_contract.pipeline_ref,
        }),
    );
    let actor = identity
        .map(|Extension(OperatorIdentity(name))| name)
        .or_else(|| clean_optional_text(request.actor));
    let reason = clean_optional_text(request.reason);
    let Json(response) = create_pipeline_intent_from_change_set(
        State(state.clone()),
        Json(CreatePipelineIntentFromChangeSetRequest {
            change_set_id: change_set.id.clone(),
            title: request.title,
            summary: request.summary,
            risk_level: request.risk_level,
            intent_kind: request.intent_kind,
            intent_json: Some(intent_json),
            actor: actor.clone(),
            reason: reason.clone(),
        }),
    )
    .await?;
    if response.created {
        append_work_item_audit_event(
            &state.store,
            &work_item,
            "work_item.pipeline_intent_proposed",
            actor,
            json!({
                "work_plan_id": work_plan.id,
                "change_set_id": change_set.id,
                "pipeline_intent_id": response.pipeline_intent.id,
                "pipeline_contract_id": pipeline_contract.id,
                "pipeline_contract_version": pipeline_contract.version,
                "source_provenance": source_provenance,
                "reason": reason,
            }),
        )
        .await?;
    }

    Ok(Json(response))
}

#[derive(Debug, Default, serde::Deserialize)]
struct WorkItemPipelineContextQuery {
    namespace: Option<String>,
    pipeline_ref: Option<String>,
}

async fn work_item_pipeline_intent_context(
    State(state): State<AppState>,
    Path(work_item_id): Path<String>,
    Query(query): Query<WorkItemPipelineContextQuery>,
) -> Result<Json<WorkItemPipelineContextResponse>, ApiError> {
    let work_item = state
        .store
        .get_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::not_found("work_item", &work_item_id))?;
    let work_plan = state
        .store
        .get_work_plan_by_work_item(&work_item_id)
        .await?
        .ok_or_else(|| ApiError::conflict("WorkItem has no WorkPlan"))?;
    let change_set = state
        .store
        .get_change_set_by_work_plan(&work_plan.id)
        .await?
        .ok_or_else(|| {
            ApiError::conflict(
                "WorkItem has no captured ChangeSet; immutable source provenance is unavailable",
            )
        })?;
    if change_set.work_item_id.as_deref() != Some(work_item.id.as_str()) {
        return Err(ApiError::conflict(
            "WorkItem ChangeSet lineage does not match the requested WorkItem",
        ));
    }
    let source_provenance = work_item_pipeline_source_provenance(&state.store, &change_set)
        .await?
        .ok_or_else(|| {
            ApiError::conflict("WorkItem pipeline context requires immutable Git merge provenance")
        })?;
    let contract_namespace = clean_optional_text(query.namespace);
    let contract_pipeline_ref = clean_optional_text(query.pipeline_ref);
    let active_pipeline_contracts = state
        .store
        .list_pipeline_contracts(PipelineContractListFilter {
            namespace: contract_namespace.clone(),
            pipeline_ref: contract_pipeline_ref.clone(),
            status: Some("active".to_string()),
            limit: 200,
            offset: 0,
        })
        .await?
        .into_iter()
        .map(Into::into)
        .collect();
    let pipeline_intent = state
        .store
        .get_pipeline_intent_by_change_set(&change_set.id)
        .await?
        .map(Into::into);

    Ok(Json(WorkItemPipelineContextResponse {
        work_item: work_item.into(),
        work_plan: work_plan.into(),
        change_set: change_set.into(),
        pipeline_intent,
        source_provenance,
        contract_namespace,
        contract_pipeline_ref,
        active_pipeline_contracts,
    }))
}

fn coding_task_prompt(work_item: &StoredWorkItem) -> String {
    let criteria = work_item
        .acceptance_criteria
        .iter()
        .map(|criterion| format!("- {criterion}"))
        .collect::<Vec<_>>()
        .join("\n");
    let target = if work_item.production_impacting {
        "protected-production source WorkItem"
    } else {
        "development WorkItem"
    };
    format!(
        "Implement this {target} in the current workspace.\n\nIntent:\n{}\n\nAcceptance criteria:\n{}\n\nBoundaries: work only in this workspace; do not read secrets; do not use network access; do not push, commit, create a pull request, deploy, or modify Git configuration other than the isolated workspace's local configuration. Run focused tests when available. Finish with a concise summary of changes and tests.",
        work_item.intent,
        if criteria.is_empty() { "- No explicit criteria were supplied." } else { &criteria }
    )
}

pub(crate) fn shell_test_evidence(events: &[AgentEvent]) -> Vec<Value> {
    let mut active_action = None;
    let mut evidence = Vec::new();
    for event in events {
        if event.kind == EventKind::ToolStarted {
            active_action = event
                .payload
                .get("action")
                .and_then(Value::as_str)
                .map(str::to_string);
            continue;
        }
        if event.kind == EventKind::ToolFinished && active_action.as_deref() == Some("run_shell") {
            evidence.push(json!({
                "event_id": event.event_id,
                "status": event.payload.get("status"),
                "summary": event.payload.get("summary"),
            }));
        }
    }
    evidence
}

async fn worker_workspace_evidence(
    store: &SqliteStore,
    run: &pharness_store::StoredRun,
    workspace: &pharness_store::StoredWorkspace,
) -> Result<(crate::workspace::GitEvidence, String, String, Vec<Value>), ApiError> {
    let artifacts = store.list_artifacts(&run.id).await?;
    let diff_artifact = artifacts
        .iter()
        .rev()
        .find(|artifact| artifact.kind == "workspace_git_diff")
        .ok_or_else(|| ApiError::conflict("worker did not retain workspace Git diff evidence"))?;
    let status_artifact = artifacts
        .iter()
        .rev()
        .find(|artifact| artifact.kind == "workspace_git_status")
        .ok_or_else(|| ApiError::conflict("worker did not retain workspace Git status evidence"))?;
    let diff = diff_artifact
        .content_text
        .clone()
        .ok_or_else(|| ApiError::conflict("workspace Git diff artifact has no text content"))?;
    let status_json = status_artifact
        .content_json
        .as_ref()
        .ok_or_else(|| ApiError::conflict("workspace Git status artifact has no JSON content"))?;
    let base_commit = status_json
        .get("base_commit")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("workspace Git status artifact has no base commit"))?;
    if workspace.resolved_commit.as_deref() != Some(base_commit) {
        return Err(ApiError::conflict(
            "workspace Git evidence does not match the pinned base commit",
        ));
    }
    let branch = status_json
        .get("branch")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("workspace Git status artifact has no branch"))?;
    if workspace.branch.as_deref() != Some(branch) {
        return Err(ApiError::conflict(
            "workspace Git evidence does not match the pinned branch",
        ));
    }
    let status = status_json
        .get("status")
        .and_then(Value::as_str)
        .ok_or_else(|| ApiError::conflict("workspace Git status artifact has no status"))?
        .to_string();
    let changed_paths = status_json
        .get("changed_paths")
        .and_then(Value::as_array)
        .ok_or_else(|| ApiError::conflict("workspace Git status artifact has no changed paths"))?
        .iter()
        .map(|path| {
            path.as_str()
                .map(ToOwned::to_owned)
                .ok_or_else(|| ApiError::conflict("workspace changed path is not a string"))
        })
        .collect::<Result<Vec<_>, _>>()?;
    let test_events = status_json
        .get("test_events")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    Ok((
        crate::workspace::GitEvidence {
            status,
            diff,
            changed_paths,
        },
        diff_artifact.id.clone(),
        status_artifact.id.clone(),
        test_events,
    ))
}

